## WebKit, when the tool isn't enough

```js
// Playwright from the tools/qa cache
const { webkit, devices } = playwright;
const browser = await webkit.launch();
const ctx = await browser.newContext({ ...devices["iPhone 15 Pro"] });  // UA, DPR 3, touch
const page = await ctx.newPage();
await page.goto(url, { waitUntil: "load" });
// touch momentum: page.touchscreen.tap / a sequence of mouse.wheel is not touch —
// drive scroll with page.evaluate(() => scrollBy({ top, behavior: "smooth" })) in steps,
// and reproduce the reviewer's exact sequence (down to the bottom, wait, back up).
```
WebKit-on-macOS is not iOS Safari (no real toolbar, a different GPU), but it
runs WebKit's compositor and canvas rules — closer than Chrome.

# Patterns — copy-paste implementations

Every block here is lifted from an optimised production scene, or is the
generalised form of one. Adapt the framework glue; keep the reasoning comments —
they are why the numbers are what they are. Where this starter already ships a
module (`src/lib/scene/per-frame.ts`, `webgl-context.ts`, `device-tilt.ts`,
`src/utils/stable-viewport.ts`), use the module; these blocks are for scenes
that need the shape in their own class.

---

## 1. `lib/scene/device.ts` — the single source of tiering

Source: the fullest of several production `device.ts` files.

```ts
export type DeviceTier = "mobile" | "tablet" | "desktop";

const TABLET_MAX = 1180;
const MOBILE_MAX = 768;

/** The media-query half of the tier. Subscribe to it (§5): DevTools emulation
 *  and a mouse plugged into a tablet flip it without any `resize` event. */
export const COARSE_POINTER_QUERY = "(hover: none) and (pointer: coarse)";
export const isCoarsePointer = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia(COARSE_POINTER_QUERY).matches;

/** Read at scene construction and held in a mutable slot. Never recompute per
 *  frame and never rebuild buffers on every `resize` event — but DO re-read it
 *  when the width or the pointer media query changes (§5). Otherwise a window
 *  dragged across a breakpoint, or emulation switched off, keeps the phone
 *  tier on a desktop viewport and the scene draws skewed until reload. */
export const deviceTier = (): DeviceTier => {
  if (typeof window === "undefined") return "desktop";
  const width = window.innerWidth;
  const coarse = isCoarsePointer();

  if (width < MOBILE_MAX || coarse) return "mobile";
  if (width < TABLET_MAX) return "tablet";
  return "desktop";
};

/** Phones: 1.0 for soft point clouds, up to 1.5 (+ MSAA) for a model, hard
 *  edges or in-shader text. Below 1.0 two production heroes read as
 *  "noisy" on an iPhone; 1.5 + MSAA fixed it with performance held.
 *  Desktop ≤ 1.5 even on 2× panels. */
const MOBILE_MAX_DPR = 1.5;

export const clampedPixelRatio = (tier: DeviceTier = deviceTier()): number => {
  if (typeof window === "undefined") return 1;
  const dpr = window.devicePixelRatio || 1;
  if (tier === "mobile") return Math.min(Math.max(dpr, 1), MOBILE_MAX_DPR);
  return Math.min(Math.max(dpr, 1), 1.5);
};

/** Minimum ms between scene DRAWS. NOT a phone cap: a `1000/30` budget drew
 *  20 fps on 60 Hz and 26 fps on a 120 Hz iPhone and read as "very low fps"
 *  (rule, 5+ sites) — and it tripped one scene's fps→DPR fallback into a noisy
 *  0.75. Phones draw every tick and pay with a cheaper frame. Desktop gates the
 *  draw at 60 fps so a 120 Hz panel doesn't double the GPU work (rule, 6 sites);
 *  12.5 ms sits between a 120 Hz and a 60 Hz tick, so a 60 Hz screen never
 *  skips. Gate the draw only — per-tick easing keeps stepping. */
export const frameBudgetMs = (tier: DeviceTier = deviceTier()): number => {
  if (tier === "desktop") return 12.5;
  return 0; // phones and tablets: every rAF tick
};

export const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Best-effort "spend less here". Data Saver is the nearest web-exposed proxy
 *  for iOS Low Power Mode, which has no API. Both inputs are absent on most
 *  desktops, so this only ever trips on a constrained client. */
export const isEnergySaver = (): boolean => {
  if (typeof navigator === "undefined") return false;
  const nav = navigator as Navigator & {
    connection?: { saveData?: boolean };
    deviceMemory?: number;
  };
  if (nav.connection?.saveData === true) return true;
  if (typeof nav.deviceMemory === "number" && nav.deviceMemory > 0) {
    return nav.deviceMemory <= 2;
  }
  return false;
};

/** Play the entrance once, then stop ADVANCING TIME on a settled frame. Do not
 *  stop drawing while the canvas is visible: iOS drops the last frame after a
 *  toolbar resize / re-composite and a stopped scene never repaints (the hero
 *  "disappears"). Redraw the settled frame on resize, visibility return and
 *  context restore. */
export const sceneShouldFreeze = (tier: DeviceTier = deviceTier()): boolean =>
  prefersReducedMotion() || (tier === "mobile" && isEnergySaver());

/** Point sizes are set in device px, so a mark tuned on a tall screen occupies a
 *  larger fraction of a short one — additive sprites pile up and bloom blows out.
 *  Scale both by viewport height against a reference. */
const VIEW_SCALE_REFERENCE = 1080;
export const viewScale = (): number =>
  typeof window === "undefined"
    ? 1
    : Math.min(1, Math.max(0.5, window.innerHeight / VIEW_SCALE_REFERENCE));

/** Whether to attach pointer listeners at all. */
export const wantsPointer = (tier: DeviceTier = deviceTier()): boolean =>
  tier !== "mobile";

export const byTier = <T,>(tier: DeviceTier, values: Record<DeviceTier, T>): T =>
  values[tier];
```

