/**
 * `/admin/analytics` — visitors, page views, time on page and bounce rate,
 * the day-by-day, and where people land, come from, and read on. A custom admin view inside Payload's own template, so the nav and
 * the header stay.
 */
import type { AdminViewServerProps } from "payload";
import { DefaultTemplate } from "@payloadcms/next/templates";
import Link from "next/link";
import { redirect } from "next/navigation";

import { readStats } from "@/cms/analytics";

import { AnalyticsChart } from "./analytics-chart";
import { Kpis, RankList, countryLabel, languageLabel } from "./analytics-ui";

const RANGES = [7, 30, 90] as const;

const capitalise = (value: string): string => value.charAt(0).toUpperCase() + value.slice(1);

export const AnalyticsView = async ({ initPageResult, params, searchParams }: AdminViewServerProps) => {
  const { req, permissions, visibleEntities, locale } = initPageResult;
  if (!req.user) redirect("/admin/login");

  const asked = Number(searchParams?.range);
  const days = RANGES.find((range) => range === asked) ?? 30;
  const stats = await readStats(days);

  return (
    <DefaultTemplate
      i18n={req.i18n}
      locale={locale}
      params={params}
      payload={req.payload}
      permissions={permissions}
      searchParams={searchParams}
      user={req.user}
      visibleEntities={visibleEntities}
    >
      <div className="ca gutter--left gutter--right">
        <header className="ca-head">
          <div>
            <h1 className="ca-head__title">Analytics</h1>
            <p className="ca-head__copy">
              Visitors who allowed analytics in the cookie banner. No cookies of our own and no IP
              addresses are stored; a visitor is counted once per day.
            </p>
          </div>
          <nav className="ca-range" aria-label="Period">
            {RANGES.map((range) => (
              <Link
                key={range}
                href={`/admin/analytics?range=${range}`}
                className={range === days ? "is-active" : undefined}
                aria-current={range === days ? "page" : undefined}
              >
                {range} days
              </Link>
            ))}
          </nav>
        </header>

        <Kpis stats={stats} />
        <AnalyticsChart daily={stats.daily} />

        <div className="ca-grid ca-grid--wide">
          <RankList title="Top pages" items={stats.pages} empty="No views yet." showTime />
          <RankList title="Where they came from" items={stats.referrers} empty="No visits yet." />
        </div>
        <div className="ca-grid">
          <RankList
            title="Countries"
            items={stats.countries}
            empty="No visits yet."
            label={countryLabel}
            badge={(code) => code}
            note={
              stats.countriesApprox
                ? "Some countries are estimated from the browser language — exact once the site runs on Vercel."
                : undefined
            }
          />
          <RankList title="Languages" items={stats.languages} empty="No visits yet." label={languageLabel} />
          <RankList title="Devices" items={stats.devices} empty="No visits yet." label={capitalise} />
          <RankList title="Browsers" items={stats.browsers} empty="No visits yet." />
          <RankList title="Operating systems" items={stats.systems} empty="No visits yet." />
        </div>
      </div>
    </DefaultTemplate>
  );
};

// 📖 Docs: obsidian/backend/cms-payload.md → Analytics
/**
 * Formatting shared by the analytics view's server parts and its client chart
 * — kept out of `analytics-chart.tsx`, whose `"use client"` would turn any
 * export into a client reference a server component cannot call.
 */

/** Seconds as "2m 05s", or "42s" under a minute. */
export const duration = (seconds: number): string => {
  if (seconds <= 0) return "0s";
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds % 60);
  return m > 0 ? `${m}m ${String(s).padStart(2, "0")}s` : `${s}s`;
};

// 📖 Docs: obsidian/backend/cms-payload.md → Analytics
/**
 * The admin's light analytics — recording a view and reading the numbers back
 *.
 *
 * Self-hosted in the CMS's own Postgres: no third-party script, no cookie of
 * its own. A view is recorded only when the visitor allowed analytics in the
 * cookie banner (the beacon checks), and never for bots, the admin, or a
 * browser that asks not to be tracked (the route checks).
 *
 * "Visitors" are counted per day: the visitor hash is salted with the date, so
 * one person is one visitor per day and cannot be linked across days. Over a
 * range, visitors are therefore the sum of each day's — what most privacy-
 * first tools call "visits".
 *
 * Time on page is the time the page was *visible*, reported by the beacon as
 * the visitor leaves; it can only be written once per view, and only by the
 * same visitor hash that created it.
 */
import "server-only";

import { createHash } from "node:crypto";

import { sql } from "@payloadcms/db-postgres";
import type { PostgresAdapter } from "@payloadcms/db-postgres";
import { getPayload } from "payload";

import config from "@payload-config";
import { getServerEnv } from "@/env";

/** Fourteen months. PROJECT CONFIG — the privacy policy's retention figure, in days; the two must agree. */
const RETENTION_DAYS = 427;

/** A view longer than this is a tab left open, not reading. */
export const MAX_DURATION_S = 30 * 60;

export type Device = "desktop" | "tablet" | "mobile";

const deviceOf = (ua: string): Device => {
  if (/ipad|tablet|(android(?!.*mobile))/i.test(ua)) return "tablet";
  if (/mobi|iphone|android/i.test(ua)) return "mobile";
  return "desktop";
};

const browserOf = (ua: string): string => {
  if (/edg\//i.test(ua)) return "Edge";
  if (/opr\/|opera/i.test(ua)) return "Opera";
  if (/yabrowser/i.test(ua)) return "Yandex";
  if (/samsungbrowser/i.test(ua)) return "Samsung Internet";
  if (/firefox|fxios/i.test(ua)) return "Firefox";
  if (/chrome|crios/i.test(ua)) return "Chrome";
  if (/safari/i.test(ua)) return "Safari";
  return "Other";
};

const osOf = (ua: string): string => {
  if (/iphone|ipad|ipod/i.test(ua)) return "iOS";
  if (/android/i.test(ua)) return "Android";
  if (/windows/i.test(ua)) return "Windows";
  if (/mac os x|macintosh/i.test(ua)) return "macOS";
  if (/cros/i.test(ua)) return "ChromeOS";
  if (/linux/i.test(ua)) return "Linux";
  return "Other";
};

const BOT = /bot|crawl|spider|slurp|lighthouse|pagespeed|headless|gtmetrix|pingdom|preview|monitor/i;

/** The country the host's edge reports, or a guess from the browser language. */
const countryOf = (
  edgeCountry: string | undefined,
  acceptLanguage: string,
): { country?: string; approx: boolean } => {
  const edge = edgeCountry?.trim().toUpperCase();
  if (edge && /^[A-Z]{2}$/.test(edge) && edge !== "XX") return { country: edge, approx: false };
  const region = /^[a-z]{2,3}-([A-Za-z]{2})\b/.exec(acceptLanguage.trim())?.[1];
  return region ? { country: region.toUpperCase(), approx: true } : { approx: false };
};

const languageOf = (acceptLanguage: string): string | undefined =>
  /^([a-z]{2,3})\b/i.exec(acceptLanguage.trim())?.[1]?.toLowerCase();

export interface RequestFacts {
  ip: string;
  userAgent: string;
  host: string;
  acceptLanguage: string;
  edgeCountry?: string;
}

const visitorOf = (secret: string, facts: RequestFacts): string => {
  const day = new Date().toISOString().slice(0, 10);
  return createHash("sha256")
    .update(`${secret}|${day}|${facts.ip}|${facts.userAgent}`)
    .digest("hex")
    .slice(0, 24);
};

const countable = (facts: RequestFacts): string | null => {
  const { DATABASE_URL, PAYLOAD_SECRET } = getServerEnv();
  if (!DATABASE_URL || !PAYLOAD_SECRET) return null;
  if (!facts.userAgent || BOT.test(facts.userAgent)) return null;
  return PAYLOAD_SECRET;
};

/** Store one view. Returns its id, or null when the request is not one to count. */
export const recordView = async (
  view: { path: string; referrer?: string },
  facts: RequestFacts,
): Promise<string | number | null> => {
  const secret = countable(facts);
  if (!secret) return null;
  if (view.path.startsWith("/admin") || view.path.startsWith("/api")) return null;

  // Only another site's host is a referrer; moving between our own pages is not.
  let referrer: string | undefined;
  if (view.referrer) {
    try {
      const host = new URL(view.referrer).hostname.replace(/^www\./, "");
      if (host && host !== facts.host.replace(/^www\./, "").split(":")[0]) referrer = host;
    } catch {
      referrer = undefined;
    }
  }

  const { country, approx } = countryOf(facts.edgeCountry, facts.acceptLanguage);
  const payload = await getPayload({ config });
  const doc = await payload.create({
    collection: "page-views",
    overrideAccess: true,
    data: {
      path: view.path,
      visitor: visitorOf(secret, facts),
      referrer,
      device: deviceOf(facts.userAgent),
      browser: browserOf(facts.userAgent),
      os: osOf(facts.userAgent),
      country,
      countryApprox: approx,
      language: languageOf(facts.acceptLanguage),
    },
  });

  // Housekeeping on roughly one view in a hundred: drop what is past retention.
  if (Math.random() < 0.01) {
    const cutoff = new Date(Date.now() - RETENTION_DAYS * 86_400_000).toISOString();
    await payload.delete({
      collection: "page-views",
      overrideAccess: true,
      where: { createdAt: { less_than: cutoff } },
    });
  }
  return doc.id;
};

/**
 * Write a view's time on page — once, and only from the visitor who made it
 * (same day hash), so the endpoint cannot be used to rewrite other rows.
 */
export const recordDuration = async (
  id: string | number,
  seconds: number,
  facts: RequestFacts,
): Promise<boolean> => {
  const secret = countable(facts);
  if (!secret) return false;
  const payload = await getPayload({ config });
  const result = await payload.update({
    collection: "page-views",
    overrideAccess: true,
    where: {
      and: [
        { id: { equals: id } },
        { visitor: { equals: visitorOf(secret, facts) } },
        { duration: { exists: false } },
      ],
    },
    data: { duration: Math.min(Math.max(Math.round(seconds), 0), MAX_DURATION_S) },
  });
  return result.docs.length > 0;
};

export interface Ranked {
  label: string;
  count: number;
  /** Average seconds on page, where the list is of pages. */
  seconds?: number;
}

export interface DayPoint {
  day: string;
  views: number;
  visitors: number;
  seconds: number;
}

export interface AnalyticsStats {
  days: number;
  views: number;
  visitors: number;
  avgSeconds: number;
  bounceRate: number;
  liveVisitors: number;
  previous: { views: number; visitors: number; avgSeconds: number; bounceRate: number };
  daily: DayPoint[];
  pages: Ranked[];
  referrers: Ranked[];
  devices: Ranked[];
  browsers: Ranked[];
  systems: Ranked[];
  countries: Ranked[];
  languages: Ranked[];
  countriesApprox: boolean;
}

type Row = Record<string, unknown>;

const num = (value: unknown): number => Number(value ?? 0) || 0;

/** The numbers for the last `days` days, today included. */
export const readStats = async (days: number): Promise<AnalyticsStats> => {
  const payload = await getPayload({ config });
  const db = (payload.db as unknown as PostgresAdapter).drizzle;
  const run = async (query: ReturnType<typeof sql>): Promise<Row[]> =>
    ((await db.execute(query)) as unknown as { rows: Row[] }).rows;

  const since = sql`date_trunc('day', now()) - (${days - 1} * interval '1 day')`;
  const before = sql`date_trunc('day', now()) - (${2 * days - 1} * interval '1 day')`;

  // Totals for a window: views, daily visitors, average visible time, and the
  // share of visitor-days that saw a single page (bounces).
  const totalsFor = (from: ReturnType<typeof sql>, to: ReturnType<typeof sql>) =>
    run(sql`with v as (
              select visitor, date_trunc('day', created_at) as d, duration
              from page_views where created_at >= ${from} and created_at < ${to}
            ), s as (
              select visitor, d, count(*) as n from v group by visitor, d
            )
            select (select count(*) from v) as views,
                   (select count(*) from s) as visitors,
                   (select coalesce(avg(duration), 0) from v where duration is not null) as seconds,
                   (select coalesce(avg(case when n = 1 then 1.0 else 0 end), 0) from s) as bounce`);

  const ranked = (rows: Row[]): Ranked[] =>
    rows.map((row) => ({
      label: String(row.label),
      count: num(row.count),
      ...(row.seconds !== undefined ? { seconds: num(row.seconds) } : {}),
    }));

  const [totals, previous, live, daily, pages, referrers, devices, browsers, systems, countries, languages] =
    await Promise.all([
      totalsFor(since, sql`now() + interval '1 day'`),
      totalsFor(before, since),
      run(sql`select count(distinct visitor) as visitors
              from page_views where created_at >= now() - interval '30 minutes'`),
      run(sql`select to_char(d, 'YYYY-MM-DD') as day,
                     count(v.id) as views, count(distinct v.visitor) as visitors,
                     coalesce(avg(v.duration), 0) as seconds
              from generate_series(${since}, date_trunc('day', now()), interval '1 day') as d
              left join page_views v on date_trunc('day', v.created_at) = d
              group by d order by d`),
      run(sql`select path as label, count(*) as count, coalesce(avg(duration), 0) as seconds
              from page_views where created_at >= ${since}
              group by path order by count desc limit 8`),
      run(sql`select coalesce(referrer, 'Direct / none') as label, count(*) as count
              from page_views where created_at >= ${since}
              group by 1 order by count desc limit 8`),
      run(sql`select coalesce(device::text, 'unknown') as label, count(*) as count
              from page_views where created_at >= ${since} group by 1 order by count desc`),
      run(sql`select coalesce(browser, 'Other') as label, count(*) as count
              from page_views where created_at >= ${since} group by 1 order by count desc limit 6`),
      run(sql`select coalesce(os, 'Other') as label, count(*) as count
              from page_views where created_at >= ${since} group by 1 order by count desc limit 6`),
      run(sql`select country as label, count(*) as count, bool_or(country_approx) as approx
              from page_views where created_at >= ${since} and country is not null
              group by 1 order by count desc limit 8`),
      run(sql`select language as label, count(*) as count
              from page_views where created_at >= ${since} and language is not null
              group by 1 order by count desc limit 6`),
    ]);

  const t = totals[0] ?? {};
  const p = previous[0] ?? {};
  return {
    days,
    views: num(t.views),
    visitors: num(t.visitors),
    avgSeconds: num(t.seconds),
    bounceRate: num(t.bounce),
    liveVisitors: num(live[0]?.visitors),
    previous: {
      views: num(p.views),
      visitors: num(p.visitors),
      avgSeconds: num(p.seconds),
      bounceRate: num(p.bounce),
    },
    daily: daily.map((row) => ({
      day: String(row.day),
      views: num(row.views),
      visitors: num(row.visitors),
      seconds: num(row.seconds),
    })),
    pages: ranked(pages),
    referrers: ranked(referrers),
    devices: ranked(devices),
    browsers: ranked(browsers),
    systems: ranked(systems),
    countries: ranked(countries),
    languages: ranked(languages),
    countriesApprox: countries.some((row) => row.approx === true),
  };
};

// 📖 Docs: obsidian/backend/cms-payload.md → Analytics
import type { CollectionConfig } from "payload";

/**
 * One row per page view — the admin's light analytics.
 *
 * Written only by `/api/track`, and only for a visitor who allowed analytics
 * in the cookie banner. Nothing here identifies a person: `visitor` is a hash
 * of a per-day salt, the IP and the user agent, so it counts unique visitors
 * within a day and cannot follow anyone across days; the IP itself is never
 * stored. Rows older than fourteen months are deleted, as the privacy policy
 * promises.
 *
 * Hidden from the nav — editors read it through the Analytics view, not as a
 * list of rows.
 */
export const PageViews: CollectionConfig = {
  slug: "page-views",
  labels: { singular: "Page view", plural: "Page views" },
  admin: { hidden: true, group: "Settings" },
  // Read by signed-in editors only; written in process by the track route.
  access: {
    read: ({ req }) => Boolean(req.user),
    create: () => false,
    update: () => false,
    delete: ({ req }) => Boolean(req.user),
  },
  fields: [
    { name: "path", type: "text", required: true, index: true },
    { name: "visitor", type: "text", required: true, index: true },
    { name: "referrer", type: "text", index: true },
    {
      name: "device",
      type: "select",
      options: ["desktop", "tablet", "mobile"],
      index: true,
    },
    { name: "browser", type: "text" },
    { name: "os", type: "text" },
    /** ISO country code; `countryApprox` when guessed from the browser language. */
    { name: "country", type: "text", index: true },
    { name: "countryApprox", type: "checkbox", defaultValue: false },
    { name: "language", type: "text" },
    /** Seconds the page was visible, reported when the visitor leaves it. */
    { name: "duration", type: "number" },
  ],
};

// 📖 Docs: obsidian/frontend/components/common.md
"use client";
/**
 * Counts a page view for the admin's analytics, and how long it was read
 * — **only once the visitor has allowed analytics** in
 * the cookie banner.
 *
 * Renders nothing. No cookie, no storage. On a new page it posts the path and
 * the referrer and keeps the view's id; when the visitor leaves — another page,
 * a closed or hidden tab — it posts the seconds the page was *visible*, so a
 * tab left in the background does not inflate the time. A visitor who has not
 * decided yet, or said no, is not counted.
 */
import { useCallback, useEffect, useRef } from "react";
import { usePathname } from "next/navigation";

import { useCookieStore } from "@/components/common/Cookie/cookieStore";

const ENDPOINT = "/api/track";

interface Current {
  id: string | number | null;
  /** Visible milliseconds banked before the latest return to the tab. */
  banked: number;
  /** When the page last became visible, or null while hidden. */
  since: number | null;
  reported: boolean;
}

const send = (body: object) => {
  const json = JSON.stringify(body);
  if (!navigator.sendBeacon?.(ENDPOINT, new Blob([json], { type: "application/json" }))) {
    void fetch(ENDPOINT, {
      method: "POST",
      body: json,
      keepalive: true,
      headers: { "content-type": "application/json" },
    });
  }
};

export const AnalyticsBeacon = () => {
  const pathname = usePathname();
  const allowed = useCookieStore((state) => state.hydrated && state.consent?.analytics === true);
  const current = useRef<Current | null>(null);
  const sentFor = useRef<string | null>(null);

  // Report the open view's visible time, once.
  const report = useCallback(() => {
    const view = current.current;
    if (!view || view.reported || view.id === null) return;
    const visible = view.banked + (view.since === null ? 0 : performance.now() - view.since);
    view.reported = true;
    send({ id: view.id, seconds: visible / 1000 });
  }, []);

  useEffect(() => {
    if (!allowed || !pathname || sentFor.current === pathname) return;
    report();
    sentFor.current = pathname;
    const view: Current = {
      id: null,
      banked: 0,
      since: document.visibilityState === "visible" ? performance.now() : null,
      reported: false,
    };
    current.current = view;
    // The server keeps only another site's host — moving between our own
    // pages is not a referral.
    void fetch(ENDPOINT, {
      method: "POST",
      keepalive: true,
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ path: pathname, referrer: document.referrer }),
    })
      .then((res) => (res.ok ? (res.json() as Promise<{ data?: { id?: string | number | null } }>) : null))
      .then((json) => {
        view.id = json?.data?.id ?? null;
      })
      .catch(() => undefined);
  }, [allowed, pathname, report]);

  useEffect(() => {
    if (!allowed) return;
    const onVisibility = () => {
      const view = current.current;
      if (!view) return;
      if (document.visibilityState === "hidden") {
        if (view.since !== null) view.banked += performance.now() - view.since;
        view.since = null;
        // A hidden tab may never come back — report now; a later return
        // simply goes unreported rather than counted twice.
        report();
      } else if (!view.reported) {
        view.since = performance.now();
      }
    };
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", report);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", report);
    };
  }, [allowed, report]);

  return null;
};

