// ⚠️ ADAPT, DO NOT COPY BLIND — written against a project whose legal mocks were
// `LegalDocument { sections: { title, short, anchor, summary, blocks: LegalBlock[] } }`
// with block kinds paragraph / list / table / preferences. Map `toRichText` and
// `fromLegal` onto THIS project's legal mock shape (the starter ships
// `{ heading, body: string[] }` sections — paragraphs only). Playbook:
// `.claude/skills/payload-cms/references/legal-rich-text.md`.
// 📖 Docs: obsidian/backend/cms-payload.md
/**
 * A legal section's text as rich text — the shape the admin edits and the site
 * renders.
 *
 * The code's copy stays written as `LegalBlock`s in `data/mocks/legal.ts`, the
 * readable form; `toRichText` turns them into the Lexical state the editor
 * stores, so the admin's defaults and the site's fallback are the same text.
 * A list item written `Lead — rest` becomes a bold lead and the rest; a
 * paragraph's closing link becomes a link inside it; a table and the cookie
 * settings button become blocks.
 *
 * Pure data — no Payload runtime — so the views can import the types.
 */
import type { SerializedEditorState, SerializedLexicalNode } from "@payloadcms/richtext-lexical/lexical";

import type { LegalBlock, LegalDocument, LegalSection } from "@/data/mocks/legal";

export type LegalBody = SerializedEditorState;

export interface LegalPageSection extends Omit<LegalSection, "blocks"> {
  body: LegalBody;
}

/** A legal document as the site renders it: each section's text is rich text. */
export interface LegalPage extends Omit<LegalDocument, "sections"> {
  sections: readonly LegalPageSection[];
}

/** The slugs of the blocks an editor can drop into the text. */
export const LEGAL_RICH_BLOCKS = { table: "table", preferences: "preferences" } as const;

/** `format` bit Lexical sets on bold text. */
const BOLD = 1;

/** `Lead — rest`: the lead is set bold, the rest stays as it is. */
const LEAD_SEPARATOR = " — ";

type Node = SerializedLexicalNode & Record<string, unknown>;

const text = (value: string, format = 0): Node => ({
  type: "text",
  version: 1,
  text: value,
  format,
  detail: 0,
  mode: "normal",
  style: "",
});

const element = (type: string, children: Node[], extra: Record<string, unknown> = {}): Node => ({
  type,
  version: 1,
  children,
  direction: "ltr",
  format: "",
  indent: 0,
  ...extra,
});

const paragraph = (children: Node[]): Node =>
  element("paragraph", children, { textFormat: 0, textStyle: "" });

const link = (label: string, href: string): Node =>
  element("link", [text(label)], {
    version: 3,
    fields: { linkType: "custom", url: href, newTab: false },
  });

/** Block ids only need to be unique within the document; these are stable across builds. */
const blockId = (seed: number): string => seed.toString(16).padStart(24, "0");

const block = (seed: number, fields: Record<string, unknown>): Node => ({
  type: "block",
  version: 2,
  format: "",
  fields: { id: blockId(seed), blockName: "", ...fields },
});

const leadAndRest = (item: string): Node[] => {
  const at = item.indexOf(LEAD_SEPARATOR);
  return at > 0 ? [text(item.slice(0, at), BOLD), text(item.slice(at))] : [text(item)];
};

const toNode = (entry: LegalBlock, seed: number): Node => {
  switch (entry.kind) {
    case "paragraph":
      return paragraph(
        entry.link ? [text(`${entry.text} `), link(entry.link.label, entry.link.href)] : [text(entry.text)],
      );
    case "list":
      return element(
        "list",
        entry.items.map((item, index) => element("listitem", leadAndRest(item), { value: index + 1 })),
        { listType: "bullet", start: 1, tag: "ul" },
      );
    case "table":
      return block(seed, {
        blockType: LEGAL_RICH_BLOCKS.table,
        caption: entry.caption,
        columns: entry.columns.map((column) => ({ text: column })),
        rows: entry.rows.map((row) => ({ cells: row.map((cell) => ({ text: cell })) })),
      });
    case "preferences":
      return block(seed, { blockType: LEGAL_RICH_BLOCKS.preferences, label: entry.label });
  }
};

/** The code's blocks as the Lexical state the editor stores. `seed` keeps block ids apart. */
export const toRichText = (blocks: readonly LegalBlock[], seed = 0): LegalBody => ({
  root: {
    type: "root",
    version: 1,
    direction: "ltr",
    format: "",
    indent: 0,
    children: blocks.map((entry, index) => toNode(entry, seed * 100 + index + 1)),
  },
});

/** The code's whole document, as the site renders it. */
export const toLegalPage = (doc: LegalDocument): LegalPage => ({
  ...doc,
  sections: doc.sections.map(({ blocks, ...section }, index) => ({
    ...section,
    body: toRichText(blocks, index + 1),
  })),
});

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/** A saved field that is a Lexical state with something in it. */
export const asRichText = (value: unknown): LegalBody | undefined => {
  if (!isRecord(value) || !isRecord(value.root) || !Array.isArray(value.root.children)) return undefined;
  return value.root.children.length > 0 ? (value as unknown as LegalBody) : undefined;
};

// ⚠️ ADAPT, DO NOT COPY BLIND — written against a project whose legal mocks were
// `LegalDocument { sections: { title, short, anchor, summary, blocks: LegalBlock[] } }`
// with block kinds paragraph / list / table / preferences. Map `toRichText` and
// `fromLegal` onto THIS project's legal mock shape (the starter ships
// `{ heading, body: string[] }` sections — paragraphs only). Playbook:
// `.claude/skills/payload-cms/references/legal-rich-text.md`.
// 📖 Docs: obsidian/backend/cms-payload.md
/**
 * The legal pages in the admin — and back.
 *
 * Unlike a board, a document has no layout to protect: its sections are the
 * content, so the editor adds, drops and reorders them. Each section's text is
 * one rich-text field — bold, italic, links, lists and sub-headings
 * typed in place, with the table and the cookie settings button as blocks
 * dropped into the text. A section's `anchor` is the `id` the contents rail
 * links to (written from the title when left blank).
 *
 * `fromLegal` maps a saved document onto the `LegalPage` the site renders,
 * falling back to the code's copy field by field, and wholesale when nothing
 * was saved yet.
 */
import type { Block, Field } from "payload";
import {
  BlocksFeature,
  BoldFeature,
  FixedToolbarFeature,
  HeadingFeature,
  InlineToolbarFeature,
  ItalicFeature,
  LinkFeature,
  OrderedListFeature,
  ParagraphFeature,
  StrikethroughFeature,
  UnderlineFeature,
  UnorderedListFeature,
  lexicalEditor,
} from "@payloadcms/richtext-lexical";

import type { LegalDocument } from "@/data/mocks/legal";

import {
  LEGAL_RICH_BLOCKS,
  asRichText,
  toLegalPage,
  toRichText,
  type LegalPage,
  type LegalPageSection,
} from "./legal-rich-text";

type Plain = Record<string, unknown>;

const isRecord = (value: unknown): value is Plain =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const text = (value: unknown): string | undefined =>
  typeof value === "string" && value.trim() !== "" ? value : undefined;

const rows = (value: unknown): Plain[] => (Array.isArray(value) ? value.filter(isRecord) : []);

const stringList = (name: string, label: string): Field => ({
  name,
  type: "array",
  label,
  labels: { singular: "Line", plural: "Lines" },
  admin: { components: { RowLabel: "/cms/admin/row-label#RowLabel" } },
  fields: [{ name: "text", type: "textarea", label: "Text", required: true }],
});

/** What can sit in the text besides words: the two things a paragraph cannot hold. */
const BLOCKS: Block[] = [
  {
    slug: LEGAL_RICH_BLOCKS.table,
    labels: { singular: "Table", plural: "Tables" },
    fields: [
      { name: "caption", type: "text", label: "Caption (screen readers)", required: true },
      stringList("columns", "Column headings"),
      {
        name: "rows",
        type: "array",
        label: "Table rows",
        labels: { singular: "Line", plural: "Lines" },
        fields: [stringList("cells", "Cells — in column order")],
      },
    ],
  },
  {
    slug: LEGAL_RICH_BLOCKS.preferences,
    labels: { singular: "Cookie settings button", plural: "Cookie settings buttons" },
    fields: [{ name: "label", type: "text", label: "Button text", required: true }],
  },
];

/**
 * The section editor: what a policy needs and nothing that would break the
 * page — no uploads, no h1/h2 (the page and the section own those), links to
 * addresses only (`https://…`, `mailto:…`, `/path`).
 */
const bodyEditor = lexicalEditor({
  features: () => [
    ParagraphFeature(),
    BoldFeature(),
    ItalicFeature(),
    UnderlineFeature(),
    StrikethroughFeature(),
    LinkFeature({ enabledCollections: [] }),
    UnorderedListFeature(),
    OrderedListFeature(),
    HeadingFeature({ enabledHeadingSizes: ["h3"] }),
    BlocksFeature({ blocks: BLOCKS }),
    FixedToolbarFeature(),
    InlineToolbarFeature(),
  ],
});

/** The admin's fields for one document, with the code's copy as defaults. */
export const legalFields = (doc: LegalDocument): Field[] => [
  {
    name: "eyebrow",
    type: "group",
    label: "Eyebrow (pill above the headline)",
    fields: [
      { name: "label", type: "text", label: "Text", defaultValue: doc.eyebrow.label },
      { name: "accent", type: "text", label: "Accent (blue part)", defaultValue: doc.eyebrow.accent },
    ],
  },
  {
    type: "row",
    fields: [
      { name: "lead", type: "text", label: "Headline — first part", defaultValue: doc.lead },
      { name: "accent", type: "text", label: "Headline — blue part", defaultValue: doc.accent },
    ],
  },
  {
    name: "description",
    type: "textarea",
    label: "Intro (also the meta description)",
    defaultValue: doc.description,
  },
  {
    type: "row",
    fields: [
      { name: "effective", type: "text", label: "Effective (YYYY-MM-DD)", defaultValue: doc.effective },
      { name: "updated", type: "text", label: "Updated (YYYY-MM-DD)", defaultValue: doc.updated },
    ],
  },
  {
    name: "sections",
    type: "array",
    label: "Sections",
    labels: { singular: "Section", plural: "Sections" },
    admin: { initCollapsed: true, components: { RowLabel: "/cms/admin/row-label#RowLabel" } },
    defaultValue: doc.sections.map((section, index) => ({
      anchor: section.id,
      title: section.title,
      label: section.label,
      summary: section.summary,
      body: toRichText(section.blocks, index + 1),
    })),
    fields: [
      { name: "title", type: "text", label: "Section heading", required: true },
      {
        type: "row",
        fields: [
          { name: "label", type: "text", label: "Short name (table of contents)" },
          { name: "anchor", type: "text", label: "Anchor (#…) — blank: from the heading" },
        ],
      },
      { name: "summary", type: "textarea", label: "One sentence for the table of contents" },
      { name: "body", type: "richText", label: "Text", editor: bodyEditor },
    ],
  },
];

const slugify = (value: string): string =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** A saved document over the code's one. Nothing saved → the code's copy. */
export const fromLegal = (doc: LegalDocument, data: unknown): LegalPage => {
  const base = toLegalPage(doc);
  if (!isRecord(data)) return base;
  const eyebrow = isRecord(data.eyebrow) ? data.eyebrow : {};
  const saved = rows(data.sections);
  const used = new Set<string>();
  const sections: LegalPageSection[] = saved.flatMap((row) => {
    const title = text(row.title);
    if (!title) return [];
    let id = text(row.anchor) ?? slugify(title);
    while (used.has(id)) id = `${id}-2`;
    used.add(id);
    return [
      {
        id,
        title,
        label: text(row.label) ?? title,
        summary: text(row.summary) ?? "",
        body: asRichText(row.body) ?? toRichText([]),
      },
    ];
  });
  return {
    ...base,
    eyebrow: {
      label: text(eyebrow.label) ?? base.eyebrow.label,
      accent: text(eyebrow.accent) ?? base.eyebrow.accent,
    },
    lead: text(data.lead) ?? base.lead,
    accent: text(data.accent) ?? base.accent,
    description: text(data.description) ?? base.description,
    effective: text(data.effective) ?? base.effective,
    updated: text(data.updated) ?? base.updated,
    sections: sections.length > 0 ? sections : base.sections,
  };
};

// ⚠️ ADAPT, DO NOT COPY BLIND — written against a project whose legal mocks were
// `LegalDocument { sections: { title, short, anchor, summary, blocks: LegalBlock[] } }`
// with block kinds paragraph / list / table / preferences. Map `toRichText` and
// `fromLegal` onto THIS project's legal mock shape (the starter ships
// `{ heading, body: string[] }` sections — paragraphs only). Playbook:
// `.claude/skills/payload-cms/references/legal-rich-text.md`.
// 📖 Docs: obsidian/frontend/components/layout.md → Legal pages
/**
 * A legal section's rich text, in the page's own type. A Server
 * Component: Payload's converter walks the saved Lexical state and each node
 * comes out as the element the page styled by hand before — muted copy with
 * ink-coloured bold, the site's `TextLink`, the accent-dot bullets, and the
 * framed table. Nothing animates: a policy is read, not presented.
 */
import type { SerializedBlockNode } from "@payloadcms/richtext-lexical";
import { RichText, type JSXConvertersFunction } from "@payloadcms/richtext-lexical/react";

import { TextLink } from "@/components/ui";
import type { LegalBody } from "@/cms/legal-rich-text";

import { CookiePreferencesButton } from "./cookie-preferences-button";

interface Line {
  text?: string | null;
}

interface TableFields {
  blockType: "table";
  caption?: string | null;
  columns?: Line[] | null;
  rows?: { cells?: Line[] | null }[] | null;
}

interface PreferencesFields {
  blockType: "preferences";
  label?: string | null;
}

const words = (lines: Line[] | null | undefined): string[] =>
  (lines ?? []).flatMap(({ text }) => (text ? [text] : []));

const Table = ({ fields }: { fields: TableFields }) => {
  const columns = words(fields.columns);
  const body = (fields.rows ?? []).map((row) => words(row.cells));
  if (columns.length === 0) return null;

  return (
    // Wider than a phone's column: the table scrolls inside its own frame.
    <div className="overflow-x-auto rounded-panel border border-border-grid bg-surface-panel">
      <table className="w-full min-w-copy border-collapse text-left text-body leading-copy">
        {fields.caption ? <caption className="sr-only">{fields.caption}</caption> : null}
        <thead>
          <tr className="border-b border-border-grid">
            {columns.map((column, index) => (
              <th key={index} scope="col" className="px-5 py-4 font-medium text-ink">
                {column}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {body.map(([name, ...cells], rowIndex) => (
            <tr key={rowIndex} className="border-b border-border-grid last:border-b-0">
              <th scope="row" className="whitespace-nowrap px-5 py-4 align-top font-medium text-accent">
                <code>{name}</code>
              </th>
              {cells.map((cell, index) => (
                <td key={index} className="px-5 py-4 align-top text-ink-muted">
                  {cell}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

/** Leaves the site: an absolute address on another host. `mailto:` and `/path` stay in. */
const isExternal = (href: string): boolean => /^https?:\/\//i.test(href);

const converters: JSXConvertersFunction = ({ defaultConverters }) => ({
  ...defaultConverters,
  paragraph: ({ node, nodesToJSX }) =>
    node.children.length > 0 ? <p>{nodesToJSX({ nodes: node.children })}</p> : null,
  heading: ({ node, nodesToJSX }) => (
    <h3 className="pt-2 text-lead font-medium leading-tight text-ink">
      {nodesToJSX({ nodes: node.children })}
    </h3>
  ),
  link: ({ node, nodesToJSX }) => {
    const href = node.fields.url ?? "";
    const children = nodesToJSX({ nodes: node.children });
    return href ? (
      <TextLink href={href} external={node.fields.newTab || isExternal(href)}>
        {children}
      </TextLink>
    ) : (
      <>{children}</>
    );
  },
  list: ({ node, nodesToJSX }) => {
    const children = nodesToJSX({ nodes: node.children });
    return node.listType === "number" ? (
      <ol className="flex list-decimal flex-col gap-3 pl-6 marker:text-accent">{children}</ol>
    ) : (
      <ul className="flex flex-col gap-3">{children}</ul>
    );
  },
  listitem: ({ node, nodesToJSX, parent }) => {
    const children = nodesToJSX({ nodes: node.children });
    const numbered = "listType" in parent && parent.listType === "number";
    const nested = node.children.some((child) => child.type === "list");
    if (numbered || nested) return <li className={nested ? "list-none" : undefined}>{children}</li>;
    return (
      <li className="flex gap-3">
        {/* Centred on the first line: half a line box, less half the marker. */}
        <span aria-hidden className="mt-[0.55em] size-marker shrink-0 rounded-marker bg-accent" />
        <span>{children}</span>
      </li>
    );
  },
  blocks: {
    table: ({ node }: { node: SerializedBlockNode<TableFields> }) => <Table fields={node.fields} />,
    preferences: ({ node }: { node: SerializedBlockNode<PreferencesFields> }) =>
      node.fields.label ? (
        <div>
          <CookiePreferencesButton label={node.fields.label} />
        </div>
      ) : null,
  },
});

export const LegalRichText = ({ body }: { body: LegalBody }) => (
  <RichText
    data={body}
    converters={converters}
    disableContainer
    className="[&_em]:italic [&_strong]:font-semibold [&_strong]:text-ink"
  />
);

