const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

import { z } from "zod";

import { getServerEnv } from "@/env";
import { ApiError, handle } from "@/lib/api";

/**
 * Example `app/api` endpoint — a contact / lead submission.
 *
 * Demonstrates the convention: the handler owns the work — it validates input,
 * reads a secret env var, and calls an upstream service inline. Secrets are
 * safe here because `route.ts` is never bundled to the browser.
 */

// Request schema — kept in the route since it isn't shared. Lift to a shared
// module only once another route needs it.
const contactSchema = z.object({
  name: z.string().min(1).max(100),
  email: z.email(),
  message: z.string().min(1).max(2000),
});

export const POST = handle(async (req) => {
  const input = contactSchema.parse(await req.json());

  const { CONTACT_ENDPOINT } = getServerEnv();

  if (CONTACT_ENDPOINT) {
    // Forward the lead to the configured upstream (CRM, webhook, …).
    const upstream = await fetch(CONTACT_ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(input),
    });
    if (!upstream.ok) {
      throw new ApiError(502, "upstream_error", "Failed to deliver the message.");
    }
  } else {
    // No upstream configured — log server-side so the starter runs as-is.
    console.log("[api/contact] submission:", input);
  }

  return { received: true };
});

"use client";

import { useEffect } from "react";

/**
 * Route-segment error boundary. Must be a Client Component. Catches render and
 * data errors in this segment and offers a recovery action via `reset()`.
 */
export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Surface the error for logging/monitoring (kept by removeConsole's exclude).
    console.error(error);
  }, [error]);

  return (
    <div className="flex flex-col items-center justify-center gap-4 text-center">
      <h1 className="text-3xl font-bold">Something went wrong</h1>
      <button
        type="button"
        onClick={reset}
        className="underline underline-offset-4"
      >
        Try again
      </button>
    </div>
  );
}

/* `source("../")` limits class detection to `src/` (this file lives in src/app).
   Without it Tailwind v4 scans the whole repo — including obsidian/ and .claude/,
   where documented class *patterns* like duration-[var(--duration-*)] parse as
   real candidates and emit CSS warnings. Docs are not a source of utilities. */
@import "tailwindcss" source("../");

/* ---------------------------------------------------------------------------
   TIER 1 — PRIMITIVES  (`--raw-*`)
   Raw literal values. The only tier allowed to contain a hex/px/ms literal.
   Never referenced in markup, never bound into @theme. Rename freely.
   Grammar: --raw-<category>-<name>[-<shade>]
   See obsidian/frontend/design-system.md → "Token naming convention".
   --------------------------------------------------------------------------- */
:root {
  --raw-color-white: #ffffff;
  --raw-color-neutral-100: #ededed;
  --raw-color-neutral-900: #171717;
  --raw-color-neutral-950: #0a0a0a;

  --raw-radius-sm: 0.5rem;
  --raw-radius-md: 0.75rem;

  --raw-duration-fast: 150ms;
  --raw-duration-normal: 250ms;
}

/* ---------------------------------------------------------------------------
   TIER 2 — SEMANTIC  (role names, no namespace prefix)
   Purpose, not appearance. Always `var(--raw-*)` — never a literal.
   This is the themeable layer: dark mode overrides happen HERE, which is why
   these are separate from the @theme bindings below (see the note there).
   Grammar: --<role>[-<variant>][-<state>]
   --------------------------------------------------------------------------- */
:root {
  --background: var(--raw-color-white);
  --foreground: var(--raw-color-neutral-900);

  --duration-fast: var(--raw-duration-fast);
  --duration-normal: var(--raw-duration-normal);

  /* Consent UI (cookie banner + preferences modal) — its own roles so it can be
     dressed in the project's brand without touching the page theme. Re-point
     these at the project's tokens when the site gets its palette — see
     obsidian/frontend/components/common.md → "Brand the consent UI". */
  --consent-surface: var(--background);
  --consent-text: var(--foreground);
  --consent-action: var(--foreground);
  --consent-action-text: var(--background);
  --consent-radius: var(--raw-radius-md);
  --consent-radius-control: var(--raw-radius-sm);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: var(--raw-color-neutral-950);
    --foreground: var(--raw-color-neutral-100);
  }
}

/* ---------------------------------------------------------------------------
   THEME BINDINGS — map semantic tokens into Tailwind namespaces.
   Every entry is exactly `--<tw-namespace>-<role>: var(--<role>)`.
   `inline` is required: it inlines the var() into each utility, so the
   dark-mode overrides on the Tier 2 tokens above cascade. Binding a literal
   here instead would freeze the value and break theming.

   Only these namespaces generate utilities (verified against tailwindcss
   v4.3.3): --color-* --spacing-* --radius-* --leading-* --tracking-* --text-*
   --font-* --ease-* --breakpoint-* --container-* --shadow-* --blur-* --animate-*
   NOTE: there is NO --duration-* namespace in v4 — `duration-fast` compiles to
   nothing. Durations stay Tier 2 only and are used as duration-[var(--duration-fast)].
   --------------------------------------------------------------------------- */
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-consent-surface: var(--consent-surface);
  --color-consent-text: var(--consent-text);
  --color-consent-action: var(--consent-action);
  --color-consent-action-text: var(--consent-action-text);
  --radius-consent: var(--consent-radius);
  --radius-consent-control: var(--consent-radius-control);
  --font-sans: var(--font-onest);

  /* Leading floor for clipped TextEngine reveals — see
     obsidian/frontend/text-engine.md → "Alignment & line-height". */
  --leading-display: 1.1;

  --ease-entrance: cubic-bezier(0.2, 0, 0, 1);
}

body {
  background: var(--background);
  color: var(--foreground);
  display: flex;
  flex-direction: column;
  align-items: center;
  /* `safe center`: a page taller than the viewport starts at the top instead of
     being centred past the scroll origin (a long page — a privacy policy — lost
     its back link and title above the top edge with plain `center`). One-screen
     pages and the 404 stay centred. */
  justify-content: safe center;
  height: 100vh;
  width: 100vw;
}

@layer base {
  /* Adaptive scaling grid — scales the root font-size with the viewport so a
     rem-based layout stays proportional. Each breakpoint divides FONT_BASE
     (16px) by the design base width its range was laid out at:
       font-size: 16 * 100 / baseWidth  (vw)
     Above 1920px the AdaptiveGrid component takes over (scale-up).
     Keep in sync with src/components/common/grid/grid.config.ts. */
  html {
    font-size: 16px;
  }

  @media (max-width: 1920px) {
    html {
      font-size: 0.833333vw; /* 16 * 100 / 1920 */
    }
  }

  @media (max-width: 1440px) {
    html {
      font-size: 1.111111vw; /* 16 * 100 / 1440 */
    }
  }

  @media (max-width: 1024px) {
    html {
      font-size: 1.5625vw; /* 16 * 100 / 1024 */
    }
  }

  @media (max-width: 640px) {
    html {
      font-size: 4.444444vw; /* 16 * 100 / 360 */
    }
  }
}

@layer utilities {
}

@layer components {
}

