/**
 * The root layout. Keep it static: nothing here (or in any page) may read
 * `headers()` / `cookies()` — that renders every route per request. Robots are
 * told apart in `src/proxy.ts` instead (obsidian/frontend/robot-form.md).
 *
 * There is deliberately no `app/loading.tsx`: even one that returns `null`
 * wraps the page in a Suspense boundary, and the server then streams the whole
 * page inside `<div hidden>` — crawlers that don't run JS (most AI crawlers)
 * read a page whose content is hidden. Add a loading state per route, only
 * with a real skeleton.
 */
export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    // `data-consent` is set on <html> by CONSENT_FLAG_SCRIPT before hydration.
    <html lang={siteConfig.locale.split("_")[0]} suppressHydrationWarning>
      <body className={`${onest.variable}`}>
        {/* Before anything is parsed: marks a returning visitor's choice so the
            server-rendered consent banner is hidden before its first paint. */}
        <script dangerouslySetInnerHTML={{ __html: CONSENT_FLAG_SCRIPT }} />
        {/* Canonical + share URLs follow the origin serving the page. */}
        <script
          dangerouslySetInnerHTML={{ __html: originSyncScript(siteConfig.url) }}
        />
        <JsonLd data={getSiteStructuredData()} />
        <ScrollLayout>
          <AdaptiveGrid />
          <ReducedMotion />
          <LazyCookie />
          {children}
        </ScrollLayout>
      </body>
    </html>
  );
}

// 📖 Docs: obsidian/frontend/seo-metadata.md
/**
 * `/llms.txt` — a plain-markdown map of the site for language models
 * (llmstxt.org). Built from the route registry (`src/lib/routes.ts`) and
 * `siteConfig`, the same sources as `sitemap.xml` and the JSON-LD, so it can't
 * list a page the sitemap doesn't or state a fact the schema contradicts.
 * Prerendered at build time — nothing here reads the request.
 *
 * Facts, not marketing: a summary for a machine. The Payload kit
 * (`payload-cms`) replaces this file with one that reads the SEO global.
 */
import { ROUTES, type SiteRoute } from "@/lib/routes";
import { siteConfig } from "@/lib/site";

export const dynamic = "force-static";

export function GET(): Response {
  const { organization } = siteConfig;
  const absolute = (path: string) =>
    path === "/" ? siteConfig.url : `${siteConfig.url}${path}`;

  const pages = (ROUTES as readonly SiteRoute[])
    .filter((route) => route.indexable)
    // The home page's summary is the blockquote above — not repeated.
    .map(
      (route) =>
        `- [${route.label}](${absolute(route.path)})${route.summary ? `: ${route.summary}` : ""}`,
    );

  const address = organization.address;
  const facts = [
    organization.foundingDate && `- Founded: ${organization.foundingDate}`,
    address &&
      `- Location: ${[address.addressLocality, address.addressRegion, address.addressCountry]
        .filter(Boolean)
        .join(", ")}`,
    organization.email && `- Email: ${organization.email}`,
    organization.telephone && `- Telephone: ${organization.telephone}`,
    ...organization.sameAs.map((profile) => `- Profile: ${profile}`),
  ].filter((line): line is string => Boolean(line));

  const body = [
    `# ${siteConfig.name}`,
    "",
    `> ${siteConfig.description}`,
    "",
    "## Pages",
    "",
    ...pages,
    ...(facts.length > 0 ? ["", "## Key facts", "", ...facts] : []),
    "",
  ].join("\n");

  return new Response(body, {
    headers: { "Content-Type": "text/plain; charset=utf-8" },
  });
}

