"use client";

/**
 * Client wrapper for the Cookie banner + preferences modal.
 *
 * Not lazy, on purpose. It used to be `dynamic({ ssr: false })`, which kept
 * ~3.7 KB gz out of the first load but mounted the banner only after hydration
 * — and on a phone the banner's paragraph is the largest text on screen, so
 * LCP waited for the JS (the banner was the mobile LCP element on every site
 * measured). It is server-rendered now and paints with the page; returning
 * visitors and the robot form hide it in CSS before paint (`consent-flag.ts`,
 * `globals.css`).
 */

import { useSyncExternalStore } from "react";

import { isRobotView } from "@/components/common/robot-view";

import { Cookie } from "./Cookie";

/** The marker is fixed for the page's life — nothing to subscribe to. */
const subscribeNever = () => () => undefined;
const notRobot = () => false;

export function LazyCookie() {
  // Robots get no consent banner: there is no visitor to ask. Read from the
  // server's marker, which never changes on a page: the server snapshot
  // (`false`) is used while hydrating — returning null on the first render
  // would not match the served banner (React #418) — and React re-renders
  // with the client's answer straight after, before paint. Until then
  // `globals.css` keeps the served copy from painting.
  const robot = useSyncExternalStore(subscribeNever, isRobotView, notRobot);
  return robot ? null : <Cookie />;
}

// 📖 Docs: obsidian/frontend/components/common.md

/** localStorage key holding the visitor's cookie choice. */
export const CONSENT_STORAGE_KEY = "cookie-consent-v1";

/**
 * The banner is server-rendered, so it paints with the page instead of after
 * hydration — on a phone its paragraph is the largest text on screen, i.e. the
 * LCP element, and a client-only banner made LCP wait for the JS (measured on
 * production sites: mobile LCP 11.0 → 2.3 s, perf 53 → 74).
 *
 * This runs before the banner is parsed — first child of <body> — and marks
 * <html data-consent> for a visitor who has already decided; `globals.css`
 * hides the banner under that mark before its first paint, so a returning
 * visitor never sees it flash.
 *
 * No "use client": the server layout imports the string itself, not a client
 * reference.
 */
export const CONSENT_FLAG_SCRIPT = `try{if(localStorage.getItem(${JSON.stringify(
  CONSENT_STORAGE_KEY,
)}))document.documentElement.setAttribute("data-consent","")}catch(e){}`;

// 📖 Docs: obsidian/frontend/components/common.md
"use client";

import { create } from "zustand";

import { CONSENT_STORAGE_KEY as STORAGE_KEY } from "./consent-flag";

export type CookieConsent = {
  /** Strictly necessary — always true, never user-disabled. */
  necessary: true;
  analytics: boolean;
  marketing: boolean;
};

const DEFAULT_CONSENT: CookieConsent = {
  necessary: true,
  analytics: false,
  marketing: false,
};

const loadConsent = (): CookieConsent | null => {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<CookieConsent>;
    return { ...DEFAULT_CONSENT, ...parsed, necessary: true };
  } catch {
    return null;
  }
};

const saveConsent = (consent: CookieConsent) => {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(consent));
  } catch {
    /* ignore storage failures (private mode, quota) */
  }
};

interface CookieStore {
  /** null until the user has decided. After hydration, the banner shows iff this is null. */
  consent: CookieConsent | null;
  /** True once the client has read localStorage — guards against SSR/CSR mismatch. */
  hydrated: boolean;
  modalOpen: boolean;
  hydrate: () => void;
  acceptAll: () => void;
  rejectAll: () => void;
  savePreferences: (next: { analytics: boolean; marketing: boolean }) => void;
  openModal: () => void;
  closeModal: () => void;
}

export const useCookieStore = create<CookieStore>((set) => ({
  consent: null,
  hydrated: false,
  modalOpen: false,
  hydrate: () => set({ consent: loadConsent(), hydrated: true }),
  acceptAll: () => {
    // "Accept all" means every category on — it used to save them all off,
    // which made it the same choice as "Reject all".
    const next: CookieConsent = { necessary: true, analytics: true, marketing: true };
    saveConsent(next);
    set({ consent: next, modalOpen: false });
  },
  rejectAll: () => {
    const next = { ...DEFAULT_CONSENT };
    saveConsent(next);
    set({ consent: next, modalOpen: false });
  },
  savePreferences: ({ analytics, marketing }) => {
    const next: CookieConsent = { necessary: true, analytics, marketing };
    saveConsent(next);
    set({ consent: next, modalOpen: false });
  },
  openModal: () => set({ modalOpen: true }),
  closeModal: () => set({ modalOpen: false }),
}));

