/**
 * Validated environment variables.
 *
 * `publicEnv` holds `NEXT_PUBLIC_*` values — inlined into the client bundle,
 * safe in the browser. `getServerEnv()` holds server-only values (secrets) —
 * never read it from client code; on the client those values are `undefined`.
 *
 * A missing/invalid variable fails fast with a clear zod error rather than
 * surfacing as a confusing runtime bug later.
 */

import { z } from "zod";

/**
 * Treat an empty env var as unset.
 *
 * `cp .env.example .env` leaves declared-but-blank keys (`CONTACT_ENDPOINT=`),
 * which reach us as `""` — and `""` is not `undefined`, so an `.optional()`
 * schema would reject it as "Invalid URL". Without this, the documented setup
 * flow would break every optional variable the moment someone copied the
 * example file.
 */
const optionalUrl = () =>
  z.preprocess((v) => (v === "" ? undefined : v), z.url().optional());

const publicSchema = z.object({
  NEXT_PUBLIC_SITE_URL: optionalUrl(),
});

/** An optional string, empty treated as unset (same reason as `optionalUrl`). */
const optionalString = () =>
  z.preprocess((v) => (v === "" ? undefined : v), z.string().optional());

const serverSchema = z.object({
  /** Optional upstream the contact endpoint forwards leads to (CRM / webhook). */
  CONTACT_ENDPOINT: optionalUrl(),
  /**
   * Vercel's production domain (a system variable, set at build time, no
   * scheme). The site's origin falls back to it when `NEXT_PUBLIC_SITE_URL` is
   * unset — see `src/lib/site.ts`.
   */
  VERCEL_PROJECT_PRODUCTION_URL: optionalString(),
  /** `production` | `preview` | `development` on Vercel builds (system variable). */
  VERCEL_ENV: optionalString(),
  /**
   * Search Console's HTML-tag verification code (the `content` value only).
   * Renders `<meta name="google-site-verification">` — see `src/lib/site.ts`.
   */
  GOOGLE_SITE_VERIFICATION: optionalString(),
  /** Bing Webmaster Tools' code — renders `<meta name="msvalidate.01">`. */
  BING_SITE_VERIFICATION: optionalString(),
});

/** Public env — safe to read anywhere (server or client). */
export const publicEnv = publicSchema.parse({
  NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL,
});

let cachedServerEnv: z.infer<typeof serverSchema> | undefined;

/**
 * Server-only env. Call from route handlers / server code only — parsed
 * lazily so the client bundle never evaluates it.
 */
export function getServerEnv() {
  cachedServerEnv ??= serverSchema.parse({
    CONTACT_ENDPOINT: process.env.CONTACT_ENDPOINT,
    VERCEL_PROJECT_PRODUCTION_URL: process.env.VERCEL_PROJECT_PRODUCTION_URL,
    VERCEL_ENV: process.env.VERCEL_ENV,
    GOOGLE_SITE_VERIFICATION: process.env.GOOGLE_SITE_VERIFICATION,
    BING_SITE_VERIFICATION: process.env.BING_SITE_VERIFICATION,
  });
  return cachedServerEnv;
}

"use client";

/**
 * Custom hook that observes an element's viewport visibility.
 *
 * This hook:
 * 1. Creates a single IntersectionObserver for the observed element
 * 2. Observes either an external `trigger` ref or the element attached via the
 *    returned callback ref
 * 3. Re-creates the observer only when the observed element or observer options
 *    actually change — not on every render
 * 4. Exposes visibility as both reactive state and a synchronous ref
 * 5. Disconnects the observer automatically on cleanup
 *
 * @param {IntersectionObserverOptions} options - Configuration object containing:
 *   - root: Root element for intersection observation
 *   - rootMargin: Margin around the root
 *   - threshold: Intersection ratio thresholds
 *   - onEnter: Callback when element enters viewport
 *   - onLeave: Callback when element leaves viewport
 *   - trigger: Optional external ref to observe instead of the attached element
 *
 * @returns {[TargetRefCallback, boolean, RefObject<boolean>]} Tuple of:
 * - targetRef: callback ref — attach it to the element to observe
 * - inView: current visibility state (reactive)
 * - inViewRef: ref mirroring the current visibility state (synchronous reads)
 */

import { RefObject, useEffect, useRef, useState } from "react";

interface IntersectionObserverOptions {
  root?: Element | Document | null;
  rootMargin?: string;
  threshold?: number | number[];
  onEnter?: (entry: IntersectionObserverEntry) => void;
  onLeave?: (entry: IntersectionObserverEntry) => void;
  trigger?: RefObject<HTMLElement | HTMLDivElement | null>;
}

type TargetRefCallback = (node: HTMLElement | null) => void;

export const useDynamicInView = (
  options: IntersectionObserverOptions = {},
): [TargetRefCallback, boolean, RefObject<boolean>] => {
  const [node, setNode] = useState<HTMLElement | null>(null);
  const [inView, setInView] = useState(false);
  const inViewRef = useRef(false);

  const { trigger, root, rootMargin, threshold, onEnter, onLeave } = options;

  // Hold the callbacks in refs so changing them never re-creates the observer.
  const onEnterRef = useRef(onEnter);
  const onLeaveRef = useRef(onLeave);
  useEffect(() => {
    onEnterRef.current = onEnter;
    onLeaveRef.current = onLeave;
  });

  useEffect(() => {
    const target = trigger?.current ?? node;
    if (!target) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        const intersecting = entry.isIntersecting;
        inViewRef.current = intersecting;
        setInView(intersecting);
        if (intersecting) {
          onEnterRef.current?.(entry);
        } else {
          onLeaveRef.current?.(entry);
        }
      },
      { root, rootMargin, threshold },
    );

    observer.observe(target);
    return () => observer.disconnect();
  }, [node, trigger, root, rootMargin, threshold]);

  return [setNode, inView, inViewRef];
};

"use client";

/**
 * Custom hook that provides both a ref for intersection observation and a ref containing the current view state
 *
 * This hook:
 * 1. Uses react-spring's useInView hook to observe element visibility
 * 2. Maintains a ref that always contains the current visibility state
 * 3. Returns both the element ref and the state ref for flexible usage
 *
 * @returns {[React.RefObject<HTMLElement>, React.MutableRefObject<boolean>]}
 * Tuple containing:
 * - ref: Reference to attach to observed element
 * - inViewRef: Reference containing current visibility state
 */

import { useInView } from "@react-spring/web";
import { useEffect, useRef } from "react";

export const useInViewRef = () => {
  const [ref, inView] = useInView();
  const inViewRef = useRef(inView);
  useEffect(() => {
    inViewRef.current = inView;
  }, [inView]);
  return [ref, inViewRef];
};

"use client";

/**
 * Custom hook that manages a render loop based on element visibility
 *
 * This hook creates a render loop that:
 * 1. Runs continuously while the element is in view
 * 2. When element goes out of view, continues rendering for 10 more frames
 *    to ensure proper cleanup and prevent abrupt stops
 * 3. Automatically restarts when element comes back into view
 *
 * @param ref - React ref for the element to observe
 * @param onRender - Callback function executed on each render frame
 * @param props - Optional loop configuration (framerate, mount/unmount handlers)
 */

import { useEffect, useRef } from "react";
import { useLoop, LoopProps } from "./use-render-loop";

export const useLoopInView = (
  ref: React.RefObject<Element | null>,
  onRender: (time: number) => void,
  props: LoopProps = {},
) => {
  const isInView = useRef(false);
  const renderCount = useRef(0);
  const shouldRender = useRef(true);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (isInView.current !== entry.isIntersecting) {
          if (!entry.isIntersecting) {
            renderCount.current = 0;
            shouldRender.current = true;
          }
        }
        isInView.current = entry.isIntersecting;
      },
      { threshold: 0 },
    );

    if (ref.current) {
      observer.observe(ref.current);
      renderCount.current = 0;
      shouldRender.current = true;
    }

    return () => observer.disconnect();
  }, [ref]);

  useLoop((time) => {
    if (isInView.current || shouldRender.current) {
      onRender(time);

      if (!isInView.current) {
        renderCount.current++;
        if (renderCount.current >= 10) {
          shouldRender.current = false;
        }
      }
    }
  }, props);
};

/**
 * @fileoverview A React hook for creating scroll-triggered progress animations.
 *
 * Features:
 * - Configurable trigger points using element positions (top/center/bottom)
 * - Mobile device handling with optional disabling
 * - Frame rate control for performance optimization
 * - Progress tracking and change notifications
 * - Spring configuration customization
 * - SSR-safe implementation
 *
 * @param {Object} props - Hook configuration options
 * @param {boolean} [props.enabled=true] - Whether the trigger is enabled
 * @param {RefObject<HTMLElement>} [props.trigger] - Optional trigger element ref
 * @param {TriggerPos} [props.start="top bottom"] - Starting trigger position
 * @param {TriggerPos} [props.end="bottom top"] - Ending trigger position
 * @param {Function} [props.onChange] - Callback when progress changes
 * @param {boolean} [props.disableOnMobile=false] - Whether to disable on mobile
 * @param {SpringConfig} [props.config] - Spring animation configuration
 * @param {number} [props.frameInterval=10] - Frame rate interval in ms
 * @param {RefObject<HTMLElement>} props.elementRef - Target element ref
 *
 * @returns {Object} Progress values
 * @returns {RefObject<number>} .progress - Ref holding the raw 0-1 progress; read `.current`
 * @returns {SpringValue} .interpolatedProgress - Spring-animated progress
 */

import { RefObject, useEffect, useMemo, useRef } from "react";
import { SpringConfig, useSpring } from "@react-spring/web";
import { useWindowWidth } from "@/hooks/use-window-size";
import { isMobileDisabled, springsConfig } from "@/lib/springs/config";
import { useLoopInView } from "./use-loop-in-view";
import { TriggerPos } from "@/components/animation/springs/progress-trigger";

interface UseProgressTriggerProps {
  enabled?: boolean;
  trigger?: RefObject<HTMLElement> | undefined;
  start?: TriggerPos;
  end?: TriggerPos;
  onChange?: (state: {
    progress: number;
    interpolatedProgress: number;
  }) => void;
  disableOnMobile?: boolean;
  config?: SpringConfig;
  frameInterval?: number;
  elementRef: RefObject<HTMLElement | null>;
}

export function useProgressTrigger({
  start = "top bottom",
  end = "bottom top",
  trigger,
  onChange,
  enabled = true,
  disableOnMobile = false,
  frameInterval = 10,
  config: springConfig,
  elementRef,
}: UseProgressTriggerProps) {
  const width = useWindowWidth();
  const savedProgress = useRef(-1);
  const activeRef = useRef(false);

  const [{ interpolatedProgress }, springApi] = useSpring(() => ({
    interpolatedProgress: 0,
    config: springConfig,
  }));

  const active = useMemo(() => {
    if (
      isMobileDisabled(
        springsConfig.disableOnMobile.springtrigger || disableOnMobile,
        width,
      )
    ) {
      return false;
    }
    if (!enabled) {
      return false;
    }
    return true;
  }, [enabled, disableOnMobile, width]);

  useEffect(() => {
    activeRef.current = active;
  }, [active]);

  useLoopInView(
    trigger || elementRef,
    () => {
      if (typeof window === "undefined") return;
      const _ref = trigger || elementRef;
      if (!activeRef.current || !_ref.current) return;

      const bb = _ref.current.getBoundingClientRect();
      const clientHeight = window.innerHeight;

      const poses = {
        top_top: bb.top,
        center_top: bb.top + bb.height / 2,
        bottom_top: bb.bottom,
        top_bottom: bb.top - clientHeight,
        center_bottom: bb.top + bb.height / 2 - clientHeight,
        bottom_bottom: bb.bottom - clientHeight,
        top_center: bb.top - clientHeight / 2,
        center_center: bb.top + bb.height / 2 - clientHeight / 2,
        bottom_center: bb.bottom - clientHeight / 2,
      };

      const scrollStart =
        poses[start.split(" ").join("_") as keyof typeof poses];
      const scrollEnd = poses[end.split(" ").join("_") as keyof typeof poses];
      const length = Math.abs(scrollStart - scrollEnd);
      const progress = Math.min(
        Math.max(0, 1 - (scrollStart + length) / length),
        1,
      );

      if (progress !== savedProgress.current) {
        savedProgress.current = progress;
        springApi.start({ interpolatedProgress: progress });
        onChange?.({
          progress,
          interpolatedProgress: interpolatedProgress.get(),
        });
      }
    },
    { framerate: frameInterval },
  );

  return {
    interpolatedProgress,
    // The ref itself — not `.current` — so reading it isn't a render-time ref
    // access. Consumers read `progress.current` for the live 0-1 value.
    progress: savedProgress,
  };
}

"use client";

/**
 * Custom hook that runs a callback on a render loop with a configurable framerate.
 *
 * This hook subscribes the callback to the shared animation ticker
 * (`src/lib/animation/ticker.ts`) — a single app-wide `requestAnimationFrame`
 * loop — instead of starting its own rAF. It:
 * 1. Executes the provided render callback at (most) the specified framerate
 * 2. Allows optional mount/unmount handlers
 * 3. Automatically unsubscribes when the component unmounts
 *
 * `onRender` and `framerate` are read live through refs, so prop changes take
 * effect without re-subscribing (and without the stale-closure bug a captured
 * callback would cause).
 *
 * @param onRender - Callback function executed on each render frame
 * @param props - Optional configuration object:
 *   - framerate: Minimum time (ms) between renders (default: 100ms)
 *   - onMount: Handler called when the loop subscription starts
 *   - onUnMount: Handler called when the loop subscription ends
 */

import { useEffect, useRef } from "react";

import { subscribeToTicker } from "@/lib/animation/ticker";

export interface LoopProps {
  onMount?: () => void;
  onUnMount?: () => void;
  framerate?: number;
}

const DEFAULT_FRAMERATE = 100;

export const useLoop = (
  onRender: (time: number) => void,
  props: LoopProps = {},
) => {
  const onRenderRef = useRef(onRender);
  const propsRef = useRef(props);

  // Keep the live values reachable from the mount-only subscription below.
  useEffect(() => {
    onRenderRef.current = onRender;
    propsRef.current = props;
  });

  useEffect(() => {
    propsRef.current.onMount?.();

    const unsubscribe = subscribeToTicker(
      (time) => onRenderRef.current(time),
      () => propsRef.current.framerate ?? DEFAULT_FRAMERATE,
    );

    return () => {
      unsubscribe();
      propsRef.current.onUnMount?.();
    };
    // Mount-only: live values are read through refs above.
  }, []);
};

/**
 * @fileoverview A React hook for creating scroll-triggered spring animations.
 *
 * The hook provides two modes of operation:
 * - "scrub": Smoothly interpolates between values based on scroll position
 * - "toggle": Switches between two states based on scroll threshold
 *
 * Features:
 * - Configurable trigger points using element positions (top/center/bottom)
 * - Mobile device handling with optional disabling
 * - Frame rate control for performance optimization
 * - Progress tracking and change notifications
 * - Spring configuration customization
 * - SSR-safe implementation
 *
 * @param {Object} props - Hook configuration options
 * @param {boolean} [props.enabled=true] - Whether the trigger is enabled
 * @param {RefObject<HTMLElement>} [props.trigger] - Optional trigger element ref
 * @param {TriggerPos} [props.start="top bottom"] - Starting trigger position
 * @param {TriggerPos} [props.end="bottom top"] - Ending trigger position
 * @param {Object} [props.from={}] - Starting values for spring animation
 * @param {Object} [props.to={}] - Target values for spring animation
 * @param {Function} [props.onChange] - Callback when progress changes
 * @param {boolean} [props.disableOnMobile=false] - Whether to disable on mobile
 * @param {SpringConfig} [props.config] - Spring animation configuration
 * @param {number} [props.frameInterval=10] - Frame rate interval in ms
 * @param {"toggle"|"scrub"} [props.mode="scrub"] - Animation mode
 * @param {RefObject<HTMLElement>} props.elementRef - Target element ref
 *
 * Returns spring values that can be used with react-spring animations
 * and an interpolated progress value between 0 and 1.
 */

import { SpringConfig, useSpring } from "@react-spring/web";
import { RefObject, useEffect, useMemo, useRef } from "react";
import { useWindowWidth } from "@/hooks/use-window-size";
import { isMobileDisabled, springsConfig } from "@/lib/springs/config";
import { interpolate } from "@/utils/math";
import { useLoopInView } from "@/hooks/animation/use-loop-in-view";

export type TriggerPos =
  | "top top"
  | "center top"
  | "bottom top"
  | "top center"
  | "center center"
  | "bottom center"
  | "top bottom"
  | "center bottom"
  | "bottom bottom";

interface UseSpringTriggerProps {
  enabled?: boolean;
  trigger?: RefObject<HTMLElement> | undefined;
  start?: TriggerPos;
  end?: TriggerPos;
  onChange?: (state: {
    progress: number;
    interpolatedProgress: number;
  }) => void;
  from?: { [x: string]: string | number };
  to?: { [x: string]: string | number };
  disableOnMobile?: boolean;
  config?: SpringConfig;
  frameInterval?: number;
  mode?: "toggle" | "scrub";
  elementRef: RefObject<HTMLElement | null>;
}

export function useSpringTrigger({
  start = "top bottom",
  end = "bottom top",
  trigger,
  from = {},
  to = {},
  onChange,
  enabled = true,
  disableOnMobile = false,
  frameInterval = 10,
  config: springConfig = { duration: 1 },
  mode = "scrub",
  elementRef,
}: UseSpringTriggerProps) {
  const width = useWindowWidth();
  const savedProgress = useRef(-1);
  const activeRef = useRef(false);
  const dataRef = useRef({
    from: {},
    to: {},
  });

  useEffect(() => {
    dataRef.current.from = from;
    dataRef.current.to = to;
  }, [from, to]);

  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  const [{ interpolatedProgress }, springApi] = useSpring(() => ({
    interpolatedProgress: 0,
    config: springConfig,
  }));

  const [springs, api] = useSpring(() => ({
    from,
    config: springConfig,
  }));

  const active = useMemo(() => {
    if (
      isMobileDisabled(
        springsConfig.disableOnMobile.springtrigger || disableOnMobile,
        width,
      )
    ) {
      return false;
    }
    if (!enabled) {
      return false;
    }
    return true;
  }, [enabled, disableOnMobile, width]);

  useEffect(() => {
    activeRef.current = active;
  }, [active]);

  function animate(progress: number) {
    if (!Object.keys(dataRef.current.to).length) return;

    api.start(() => {
      if (mode === "toggle") {
        if (progress >= 1) {
          return {
            ...dataRef.current.to,
            config: springConfig,
          };
        }
        return {
          ...dataRef.current.from,
          config: springConfig,
        };
      }

      const interpolatedValue = interpolate(
        dataRef.current.from,
        dataRef.current.to,
        progress,
      );
      return {
        ...interpolatedValue,
        config: springConfig,
      };
    });
  }

  useLoopInView(
    trigger || elementRef,
    () => {
      if (typeof window === "undefined") return;
      const _ref = trigger || elementRef;
      if (!activeRef.current || !_ref.current) return;

      const bb = _ref.current.getBoundingClientRect();
      const clientHeight = window.innerHeight;

      const poses = {
        top_top: bb.top,
        center_top: bb.top + bb.height / 2,
        bottom_top: bb.bottom,
        top_bottom: bb.top - clientHeight,
        center_bottom: bb.top + bb.height / 2 - clientHeight,
        bottom_bottom: bb.bottom - clientHeight,
        top_center: bb.top - clientHeight / 2,
        center_center: bb.top + bb.height / 2 - clientHeight / 2,
        bottom_center: bb.bottom - clientHeight / 2,
      };

      const scrollStart =
        poses[start.split(" ").join("_") as keyof typeof poses];
      const scrollEnd = poses[end.split(" ").join("_") as keyof typeof poses];
      const length = Math.abs(scrollStart - scrollEnd);
      const progress = Math.min(
        Math.max(0, 1 - (scrollStart + length) / length),
        1,
      );

      if (progress !== savedProgress.current) {
        savedProgress.current = progress;
        springApi.start({ interpolatedProgress: progress });
        animate(progress);
        onChangeRef.current?.({
          progress,
          interpolatedProgress: interpolatedProgress.get(),
        });
      }
    },
    { framerate: frameInterval },
  );

  return {
    springs,
    interpolatedProgress,
  };
}

"use client";

/**
 * Custom hook that executes a callback when window width changes
 *
 * This hook:
 * 1. Sets up a render loop that checks window width on each frame
 * 2. Only triggers the callback when width actually changes
 * 3. Maintains previous width in a ref to detect changes
 * 4. Supports optional loop configuration via props
 *
 * @param onResize - Callback function executed when width changes
 * @param props - Optional loop configuration (framerate, mount/unmount handlers)
 */

import { useRef } from "react";
import { LoopProps, useLoop } from "./use-render-loop";

export const useResizeLoop = (
  onResize: (time: number) => void,
  props?: LoopProps,
) => {
  const width = useRef(0);
  useLoop((time: number) => {
    if (width.current !== window.innerWidth) {
      onResize?.(time);
      width.current = window.innerWidth;
    }
  }, props);
};

import Lenis from "lenis";
import { create } from "zustand";

export interface UseScroll {
  lenis: Lenis | null;
  setLenis: (lenis: Lenis | null) => void;
  isEnableScroll: boolean;
  start: () => void;
  stop: () => void;
}

export const useScroll = create<UseScroll>((set) => ({
  lenis: null,
  setLenis: (lenis) => set({ lenis }),
  isEnableScroll: true,
  start: () => set({ isEnableScroll: true }),
  stop: () => set({ isEnableScroll: false }),
}));

"use client";

/**
 * Adaptive scaling grid hook.
 *
 * Scales the root (`<html>`) font-size up while the viewport is wider than
 * `baseWidth`, so a rem-based layout keeps growing proportionally on large
 * displays. At or below `baseWidth` the inline font-size is cleared and the
 * `vw` media queries in `globals.css` take over.
 *
 * 📖 Docs: obsidian/frontend/hooks.md
 */

import { useCallback, useEffect } from "react";

import { useResizeLoop } from "@/hooks/animation/user-resize-loop";

/** Root font-size (px) the design is measured against. */
const FONT_BASE = 16;

export interface UseAdaptiveGridOptions {
  /** Viewport width (px) above which the root font-size scales up. */
  baseWidth: number;
  /** Damping factor (0–1) for the scale-up; 1 = fully proportional. */
  coef?: number;
}

/**
 * Interpolates a font-size for `windowWidth` relative to `baseWidth`. `coef`
 * damps the effect: at 1 the size tracks the viewport 1:1, at 0 it stays flat.
 */
export const interpolateFontSize = (
  baseFontSize: number,
  baseWidth: number,
  windowWidth: number,
  coef = 0.5,
): number => {
  const widthReduction = ((baseWidth - windowWidth) / baseWidth) * 100;
  const fontReduction = widthReduction * coef;
  return baseFontSize - (baseFontSize * fontReduction) / 100;
};

export const useAdaptiveGrid = ({
  baseWidth,
  coef = 0.6666,
}: UseAdaptiveGridOptions): void => {
  const apply = useCallback(() => {
    const root = document.documentElement;
    const size = interpolateFontSize(
      FONT_BASE,
      baseWidth,
      window.innerWidth,
      coef,
    );

    if (size > FONT_BASE) {
      root.style.setProperty("font-size", `${size}px`);
    } else {
      // Below the base width, let the `vw` media queries in globals.css drive.
      root.style.removeProperty("font-size");
    }
  }, [baseWidth, coef]);

  useEffect(() => {
    apply();
  }, [apply]);

  useResizeLoop(apply);
};

"use client";

// 📖 Docs: obsidian/frontend/animation-system.md → "Loops and motion off"

import { useState } from "react";
import { useReducedMotion } from "@react-spring/web";

import { useRobot } from "@/components/common/robot-view";

const reducedAtStart = (): boolean =>
  typeof window !== "undefined" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * True when motion is off: the visitor prefers reduced motion, or this is the
 * robot form. **Every looping spring must read it** — `loop: !motionOff` — and
 * every `while (alive) { await … }` spring loop must stop on it, because both
 * conditions switch on react-spring's global `skipAnimation`, under which a
 * loop finishes each lap instantly and starts the next in the same tick: the
 * page freezes (a hung page on load, measured on 6+ production sites; ~300 ms
 * of main thread per load at best).
 *
 * The media query is read on the first render: `useReducedMotion()` alone
 * reports `false` until its effect runs, by which time the loop has started.
 * The flag doesn't touch the DOM, so reading it during render can't mismatch.
 */
export const useMotionOff = (): boolean => {
  const [reducedFirst] = useState(reducedAtStart);
  const reduced = Boolean(useReducedMotion());
  const robot = useRobot();
  return reducedFirst || reduced || robot;
};

"use client";

// 📖 Docs: obsidian/frontend/smooth-scroll.md → "One-screen pages"

import { useEffect } from "react";

import { useScroll } from "@/hooks/smooth-scroll/use-scroll";

/**
 * Lock the page scroll while `locked` is true — a one-screen layout, an open
 * menu, a modal.
 *
 * Lenis drives the scroll position itself, so `body { overflow: hidden }` does
 * NOT stop the wheel on a Lenis page (a one-screen design could be wheeled
 * ~140 px on a fresh desktop load). This goes through the scroll store, which
 * stops Lenis and locks native scroll together, and restores both on unlock.
 * `toTop` scrolls to the top on locking — a one-screen layout entered after a
 * scroll would otherwise stay offset.
 */
export const useScrollLock = (locked: boolean, { toTop = false } = {}) => {
  const stop = useScroll((s) => s.stop);
  const start = useScroll((s) => s.start);
  const lenis = useScroll((s) => s.lenis);

  useEffect(() => {
    if (!locked) return;
    if (toTop) {
      lenis?.scrollTo(0, { immediate: true, force: true });
      window.scrollTo(0, 0);
    }
    stop();
    return () => start();
  }, [locked, toTop, lenis, stop, start]);
};

/**
 * @fileoverview Hooks for accessing and responding to window dimensions.
 *
 * - useWindowWidth: current window width
 * - useWindowHeight: current window height
 * - useWindowSize: both width and height
 *
 * All three read from a **single shared store**: one debounced `resize`
 * listener is attached for the whole app (on the first mounted consumer) and
 * removed when the last consumer unmounts — instead of one listener + one
 * debounce timer per hook call. State is delivered through
 * `useSyncExternalStore`, so it is SSR-safe and tear-free.
 */

"use client";

import { useSyncExternalStore } from "react";

/** Debounce applied to the single shared `resize` listener (ms). */
const DEBOUNCE_MS = 300;

interface WindowSize {
  width: number;
  height: number;
}

/** Stable snapshot returned during SSR / before the window is measured. */
const SERVER_SNAPSHOT: WindowSize = { width: 0, height: 0 };

const measure = (): WindowSize => ({
  width: window.innerWidth,
  height: window.innerHeight,
});

// Initialised eagerly on the client so the first render already has real
// values (no post-mount re-render); falls back to the server snapshot in SSR.
let snapshot: WindowSize =
  typeof window !== "undefined" ? measure() : SERVER_SNAPSHOT;

const listeners = new Set<() => void>();
let resizeBound = false;
let debounceId: ReturnType<typeof setTimeout> | undefined;

const publish = (): void => {
  const next = measure();
  if (next.width === snapshot.width && next.height === snapshot.height) return;
  snapshot = next; // new reference only on a real change — keeps snapshots stable
  listeners.forEach((listener) => listener());
};

const handleResize = (): void => {
  if (debounceId) clearTimeout(debounceId);
  debounceId = setTimeout(publish, DEBOUNCE_MS);
};

const subscribe = (listener: () => void): (() => void) => {
  if (!resizeBound) {
    snapshot = measure();
    window.addEventListener("resize", handleResize, { passive: true });
    resizeBound = true;
  }
  listeners.add(listener);

  return () => {
    listeners.delete(listener);
    if (listeners.size === 0) {
      window.removeEventListener("resize", handleResize);
      if (debounceId) clearTimeout(debounceId);
      resizeBound = false;
    }
  };
};

export function useWindowSize(): WindowSize {
  return useSyncExternalStore(
    subscribe,
    () => snapshot,
    () => SERVER_SNAPSHOT,
  );
}

export function useWindowWidth(): number {
  return useSyncExternalStore(
    subscribe,
    () => snapshot.width,
    () => SERVER_SNAPSHOT.width,
  );
}

export function useWindowHeight(): number {
  return useSyncExternalStore(
    subscribe,
    () => snapshot.height,
    () => SERVER_SNAPSHOT.height,
  );
}

"use client";

import { useEffect } from "react";
import Lenis from "lenis";
import { usePathname } from "next/navigation";
import { useScroll } from "@/hooks/smooth-scroll/use-scroll";
import { scrollTo } from "@/utils/scroll-to";
import { useShallow } from "zustand/react/shallow";

export const scrollSpeed = { current: 1 };

export function ScrollLayout({ children }: { children: React.ReactNode }) {
  // Server-safe rendering
  return (
    <div className="scroll-layout">
      {/* Static content that can be rendered on server */}
      <div className="scroll-layout-content">{children}</div>

      {/* Client-only functionality */}
      <ScrollController />
    </div>
  );
}

function ScrollController() {
  const isEnableScroll = useScroll((state) => state.isEnableScroll);
  const [lenis, setLenis] = useScroll(
    useShallow((state) => [state.lenis, state.setLenis]),
  );
  const pathname = usePathname();
  // The section to land on, read from the address — derived, not stored, so
  // it can't fall out of step with the route.
  const hash = pathname.includes("#") ? (pathname.split("#").pop() ?? "") : "";

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.scrollTo(0, 0);
    const lenis = new Lenis({
      smoothWheel: true,
      // syncTouch: true,
    });
    (window as typeof window & { lenis: Lenis }).lenis = lenis;
    setLenis(lenis);

    let rafId = 0;
    const raf = (time: number) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(raf);
    };
    rafId = requestAnimationFrame(raf);

    return () => {
      // Cancel the loop before destroying Lenis — otherwise it keeps calling
      // `raf` on a destroyed instance after unmount/HMR.
      cancelAnimationFrame(rafId);
      lenis.destroy();
      setLenis(null);
    };
  }, [setLenis]);

  useEffect(() => {
    if (isEnableScroll) {
      lenis?.start();
      enableNativeScroll(true);
    } else {
      lenis?.stop();
      enableNativeScroll(false);
    }
  }, [isEnableScroll, lenis]);

  useEffect(() => {
    if (lenis && hash) {
      setTimeout(() => {
        scrollTo(hash, true);
      }, 300);
    }
  }, [lenis, hash]);

  return null; // This component doesn't render anything visible
}

const enableNativeScroll = (value: boolean) => {
  if (typeof document === "undefined") return;
  if (!document) return;
  const html = document.querySelector("html");
  if (!html) return;
  if (!value) {
    html.style.position = "relative";
    html.style.overflow = "hidden";
    html.style.height = "100%";
  } else {
    html.style.removeProperty("position");
    html.style.removeProperty("overflow");
    html.style.removeProperty("height");
  }
};

/**
 * Shared animation ticker.
 *
 * A single, app-wide `requestAnimationFrame` loop. Every animation hook that
 * needs per-frame work subscribes here instead of starting its own rAF — so a
 * page with N scroll-driven components runs **one** loop, not N.
 *
 * The loop is reference-counted: it starts on the first subscriber and stops
 * (`cancelAnimationFrame`) when the last one leaves, so an idle page costs
 * nothing. Each subscriber is throttled independently by its own framerate.
 *
 * 📖 Docs: obsidian/frontend/animation-system.md
 */

export type TickerCallback = (time: number) => void;

interface Subscriber {
  callback: TickerCallback;
  /** Read live each frame so framerate prop changes take effect. */
  getFramerate: () => number;
  /** Timestamp of this subscriber's last invocation. */
  last: number;
}

const subscribers = new Set<Subscriber>();
let rafId: number | null = null;

const frame = (time: number): void => {
  // Snapshot first: a callback may subscribe/unsubscribe during iteration.
  for (const sub of [...subscribers]) {
    if (!subscribers.has(sub)) continue;
    if (time - sub.last <= sub.getFramerate()) continue;
    sub.last = time;
    try {
      sub.callback(time);
    } catch (error) {
      // Isolate failures — one bad subscriber must not kill the shared loop.
      console.error("[ticker] subscriber threw:", error);
    }
  }
  rafId = requestAnimationFrame(frame);
};

const start = (): void => {
  if (rafId === null) rafId = requestAnimationFrame(frame);
};

const stop = (): void => {
  if (rafId !== null) {
    cancelAnimationFrame(rafId);
    rafId = null;
  }
};

/**
 * Subscribe a callback to the shared rAF loop.
 *
 * @param callback - invoked with the rAF timestamp, no more often than `getFramerate()` ms apart.
 * @param getFramerate - returns the current minimum gap (ms) between invocations; read live every frame.
 * @returns an unsubscribe function.
 */
export const subscribeToTicker = (
  callback: TickerCallback,
  getFramerate: () => number,
): (() => void) => {
  const subscriber: Subscriber = {
    callback,
    getFramerate,
    last: performance.now(),
  };
  subscribers.add(subscriber);
  start();

  return () => {
    subscribers.delete(subscriber);
    if (subscribers.size === 0) stop();
  };
};

/**
 * Typed client for same-origin `/api/*` endpoints.
 *
 * For use in Client Components that need to fetch after mount. It unwraps the
 * `{ data }` / `{ error }` envelope and throws `ApiClientError` on failure.
 * The browser must only ever call same-origin `/api/*` — never a third-party
 * API directly (that belongs in a route handler).
 */

interface ApiFailure {
  error: {
    code: string;
    message: string;
    issues?: { path: string; message: string }[];
  };
}

/** Thrown by `apiFetch` when an endpoint responds with an error envelope. */
export class ApiClientError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "ApiClientError";
  }
}

/**
 * Calls a same-origin `/api` endpoint and returns the unwrapped `data`.
 * `path` must be a relative path (e.g. `/api/contact`).
 */
export async function apiFetch<T>(
  path: string,
  init?: RequestInit,
): Promise<T> {
  const res = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...init?.headers },
  });

  const body = (await res.json().catch(() => null)) as
    | { data: T }
    | ApiFailure
    | null;

  if (!res.ok || !body || "error" in body) {
    const err =
      body && "error" in body
        ? body.error
        : { code: "request_failed", message: "Request failed." };
    throw new ApiClientError(err.code, err.message, res.status);
  }

  return body.data;
}

/**
 * Shared helpers for `app/api/**` route handlers.
 *
 * Gives every endpoint a consistent JSON envelope and error handling:
 * - success → `{ data: ... }`
 * - failure → `{ error: { code, message, issues? } }`
 *
 * Route handlers stay free to hold business logic and secrets (the file is
 * server-only by construction) — these helpers only standardise the I/O shape.
 */

import { NextRequest, NextResponse } from "next/server";
import { ZodError } from "zod";

/** Throw inside a route handler to return a specific error response. */
export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

type RouteContext = { params: Promise<Record<string, string>> };

/**
 * Wraps an `app/api` route handler. The handler returns its payload (wrapped
 * as `{ data }`, 200) or a `NextResponse` (passed through). Thrown errors are
 * mapped to the error envelope:
 * - `ZodError` / malformed JSON → 400
 * - `ApiError` → its own status/code
 * - anything else → 500 (logged server-side, no internals leaked)
 */
export function handle<C extends RouteContext = RouteContext>(
  handler: (req: NextRequest, ctx: C) => Promise<unknown>,
) {
  return async (req: NextRequest, ctx: C): Promise<NextResponse> => {
    try {
      const result = await handler(req, ctx);
      if (result instanceof NextResponse) return result;
      return NextResponse.json({ data: result }, { status: 200 });
    } catch (error) {
      if (error instanceof ZodError) {
        return NextResponse.json(
          {
            error: {
              code: "invalid_input",
              message: "Invalid request payload.",
              issues: error.issues.map((issue) => ({
                path: issue.path.map(String).join("."),
                message: issue.message,
              })),
            },
          },
          { status: 400 },
        );
      }
      if (error instanceof SyntaxError) {
        return NextResponse.json(
          { error: { code: "invalid_json", message: "Request body is not valid JSON." } },
          { status: 400 },
        );
      }
      if (error instanceof ApiError) {
        return NextResponse.json(
          { error: { code: error.code, message: error.message } },
          { status: error.status },
        );
      }
      console.error("[api] unhandled error:", error);
      return NextResponse.json(
        { error: { code: "internal_error", message: "Something went wrong." } },
        { status: 500 },
      );
    }
  };
}

// 📖 Docs: obsidian/frontend/seo-metadata.md

/**
 * The route registry — every public page the site serves, in one list.
 *
 * `sitemap.xml`, `/llms.txt` and the breadcrumb JSON-LD all read it, so a page
 * can't be in one and missing from another. `.claude/scripts/verify.sh` FAILs
 * when an `app/**\/page.tsx` has no entry here — a route left out of a
 * hand-kept sitemap array was the most common SEO miss on sites built from
 * this starter.
 *
 * Plain data, no imports: a client component (a nav, a footer) may read it
 * without pulling in `siteConfig` (server-only, it ships zod).
 */

export type ChangeFrequency =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SiteRoute {
  /** The path, no trailing slash (`/`, `/about`, `/services/branding`). */
  path: `/${string}`;
  /** A short name — the breadcrumb, the `/llms.txt` link text, a nav label. */
  label: string;
  /**
   * What the page gives a reader, one sentence — `/llms.txt` lists it. The
   * home page falls back to `siteConfig.description`.
   */
  summary?: string;
  /** `false` keeps it out of `sitemap.xml` and `/llms.txt` (set `noIndex` on its metadata too). */
  indexable: boolean;
  /**
   * When the page's content last really changed — `YYYY-MM-DD`. Omitted → no
   * `<lastmod>`. Never the build time: a date that moves on every deploy
   * teaches Google to ignore the site's dates.
   */
  updated?: string;
  changeFrequency?: ChangeFrequency;
  /** 0–1, relative to the site's other pages. */
  priority?: number;
  /** The parent's path, for the breadcrumb trail. Omitted → the home page. */
  parent?: `/${string}`;
  /**
   * Multi-language sites only (skill: i18n-seo): every language version of
   * this page — hreflang code → path, **its own included** — the same map on
   * each version's entry, e.g. `{ en: "/about", de: "/de/uber-uns" }`.
   * `x-default` → the first listed unless named. Feeds hreflang in `<head>`
   * (`routeLanguages()` in `src/utils/seo/hreflang.ts`) and `sitemap.xml`.
   */
  alternates?: Readonly<Record<string, `/${string}`>>;
}

/**
 * One entry per route in `src/app`. A new page = a new entry here, in the same
 * change (obsidian/workflows/new-page.md). `/robot-view` is never listed — it
 * is served under `/`.
 */
export const ROUTES = [
  {
    path: "/",
    label: "Home",
    indexable: true,
    changeFrequency: "monthly",
    priority: 1,
  },
  {
    path: "/privacy-policy",
    label: "Privacy Policy",
    summary:
      "What the site collects, why, how long it is kept, and the choices a visitor has.",
    indexable: true,
    changeFrequency: "yearly",
    priority: 0.2,
  },
] as const satisfies readonly SiteRoute[];

export type RoutePath = (typeof ROUTES)[number]["path"];

/** The registry entry for a path, if it has one. */
export const findRoute = (path: string): SiteRoute | undefined =>
  (ROUTES as readonly SiteRoute[]).find((route) => route.path === path);

/** Home → … → the page, following `parent`. Unknown paths give `[]`. */
export function routeTrail(path: string): SiteRoute[] {
  const trail: SiteRoute[] = [];
  let current = findRoute(path);
  // The length guard stops a `parent` cycle typed by mistake.
  while (current && trail.length < ROUTES.length) {
    trail.unshift(current);
    if (current.path === "/") break;
    current = findRoute(current.parent ?? "/");
  }
  return trail;
}

// 📖 Docs: obsidian/frontend/webgl-scenes.md → "Device tilt"

/**
 * Device tilt for a hero model on phones — the gyroscope as a cursor.
 *
 * A module-level singleton, not React state: a scene reads `readTilt()` inside
 * its own frame loop (r3f `useFrame`, a raw rAF, a worker message on change),
 * so nothing re-renders and nothing runs when no scene asks.
 *
 *   startTilt()              once, from the scene's mount effect (client only); → live?
 *   const t = readTilt(dt)   per frame: { x, y } in [-1, 1], eased, dt in s
 *   stopTilt()               on unmount
 *
 * Sources, in order:
 *  1. `deviceorientation` — listened to from the start. Android Chrome sends
 *     it freely (https). iOS 13+ sends nothing until
 *     `DeviceOrientationEvent.requestPermission()` is called inside a user
 *     gesture: the first `touchend` / `click` asks (Safari shows its own
 *     "Allow motion & orientation" sheet); an ask rejected for want of a
 *     gesture (a scroll's touchend) re-arms for the next one. Declined or
 *     unsupported → source 3.
 *  2. The reading is relative to how the phone was held at the first sample
 *     (baseline), so a phone held at 45° reads 0 — and it re-centres slowly,
 *     so a visitor who changes grip doesn't leave the model stuck at an edge.
 *  3. Idle sway — a slow Lissajous drift (±0.35) so the model is never dead
 *     before permission, without it, or on a laptop with no sensor.
 * Off (always 0) for the robot form and `prefers-reduced-motion`; only on
 * coarse pointers — a mouse keeps the scene's own pointer code.
 *
 * SEO/perf: no DOM, no render, no network; listeners are passive and added
 * after mount. The robot form never calls `startTilt()`.
 */

import { isRobotView } from "@/components/common/robot-view";

type Tilt = { x: number; y: number };

const RANGE_DEG = 22; // tilt that reaches ±1
const EASE = 6; // 1/s — exp(-EASE·dt) smoothing of the target
const RECENTRE = 0.15; // 1/s — baseline drifts toward the current pose

let started = 0;
let active = false;
let hasSensor = false;
let base: { b: number; g: number } | null = null;
let raw: Tilt = { x: 0, y: 0 };
const out: Tilt = { x: 0, y: 0 };
let clock = 0;
let lastT = 0;

const clamp = (v: number) => Math.max(-1, Math.min(1, v));

const screenAngle = (): number =>
  (typeof screen !== "undefined" && screen.orientation?.angle) ||
  (typeof window !== "undefined" && typeof (window as { orientation?: number }).orientation === "number"
    ? ((window as { orientation?: number }).orientation as number)
    : 0);

function onOrientation(e: DeviceOrientationEvent) {
  if (e.beta == null || e.gamma == null) return;
  hasSensor = true;
  // Map to screen axes: in landscape, beta and gamma swap.
  const a = screenAngle();
  let b = e.beta;
  let g = e.gamma;
  if (a === 90) [b, g] = [g, -b];
  else if (a === -90 || a === 270) [b, g] = [-g, b];
  if (!base) base = { b, g };
  const now = performance.now();
  const dt = lastT ? Math.min((now - lastT) / 1000, 0.1) : 0;
  lastT = now;
  const k = 1 - Math.exp(-RECENTRE * dt);
  base.b += (b - base.b) * k;
  base.g += (g - base.g) * k;
  raw = { x: clamp((g - base.g) / RANGE_DEG), y: clamp((b - base.b) / RANGE_DEG) };
}

type PermissionApi = { requestPermission?: () => Promise<"granted" | "denied"> };

function disarm() {
  removeEventListener("touchend", askOnce);
  removeEventListener("click", askOnce);
}

function askOnce() {
  if (hasSensor) return disarm(); // already streaming (Chrome exposes the API but needs no grant)
  const api = (globalThis as { DeviceOrientationEvent?: PermissionApi }).DeviceOrientationEvent;
  const ask = api?.requestPermission?.();
  if (!ask) return disarm();
  disarm();
  ask
    // The listener is already on (see startTilt); "granted" just lets iOS send.
    .then((s) => { if (s !== "granted") hasSensor = false; })
    // Rejected = not a user activation (e.g. the touchend that ended a scroll):
    // ask again on the next gesture rather than giving up for the visit.
    .catch(() => { if (active) arm(); });
}

function arm() {
  addEventListener("touchend", askOnce, { passive: true });
  addEventListener("click", askOnce, { passive: true });
}

/**
 * Reduced motion, or the robot form (`components/common/robot-view.tsx` sets
 * `window.__robotView` and serves `<meta name="x-robot-view">`).
 */
const motionOff = (): boolean =>
  matchMedia("(prefers-reduced-motion: reduce)").matches ||
  window.__robotView === true ||
  isRobotView();

/** Returns whether tilt is live (a phone, motion allowed) — a caller can skip its own loop. */
export function startTilt(): boolean {
  if (typeof window === "undefined") return false;
  if (started++ > 0) return active;
  if (motionOff() || !matchMedia("(pointer: coarse)").matches) return false;
  active = true;
  // Listening asks for nothing: Android Chrome streams at once; iOS stays
  // silent until granted. No prompt on load either way.
  addEventListener("deviceorientation", onOrientation, { passive: true });
  const api = (globalThis as { DeviceOrientationEvent?: PermissionApi }).DeviceOrientationEvent;
  // iOS: ask inside the first gesture; a rejected ask (no activation) re-arms.
  if (typeof api?.requestPermission === "function") arm();
  return true;
}

export function stopTilt(): void {
  if (typeof window === "undefined" || --started > 0) return;
  started = 0;
  active = false;
  removeEventListener("deviceorientation", onOrientation);
  disarm();
  base = null;
  lastT = 0;
  hasSensor = false;
  raw = { x: 0, y: 0 };
}

/** Per frame. `dt` in seconds. Returns the same object — read, don't keep. */
export function readTilt(dt: number): Readonly<Tilt> {
  if (!active) return out;
  clock += dt;
  const target = hasSensor
    ? raw
    : { x: Math.sin(clock * 0.45) * 0.35, y: Math.sin(clock * 0.31 + 1.3) * 0.2 };
  const k = 1 - Math.exp(-EASE * dt);
  out.x += (target.x - out.x) * k;
  out.y += (target.y - out.y) * k;
  return out;
}

// 📖 Docs: obsidian/frontend/webgl-scenes.md → "Frame rate and time"

/**
 * Frame-rate-independent motion for render loops (WebGL scenes, canvas
 * effects, any hand-written rAF loop).
 *
 * Phones run at 120 Hz (ProMotion iPhones, most Android flagships), laptops at
 * 60–120 Hz, a busy phone drops to 30. A loop that moves things by a fixed
 * amount **per frame** runs at a different speed on each — twice as fast at
 * 120 Hz, and 4× when two loops tick it (a worker loop + a page loop). Every
 * per-frame step must be scaled by the frame's duration, in **seconds**.
 *
 *   const clock = createFrameClock();
 *   function frame(now: number) {
 *     const { dt, t } = clock.tick(now);           // seconds
 *     x += (target - x) * perFrame(0.08, dt);      // was: x += (target - x) * 0.08
 *     angle += SPEED_PER_60HZ_FRAME * dt * 60;     // was: angle += SPEED_PER_60HZ_FRAME
 *     material.uniforms.uTime.value = t;           // was: performance.now() (ms!)
 *   }
 *
 * One clock, in seconds, for every path that draws the scene: a scene moved
 * into an OffscreenCanvas worker once received its time in milliseconds where
 * the page path passed seconds — every timed motion ran ~1000× fast, aliased
 * into jitter ("2–4× too fast and shaking"). No lab metric sees speed:
 * Lighthouse and scroll tests count frames, not pixels per second.
 */

/** The longest step a frame may take — a tab coming back must not teleport. */
export const MAX_FRAME_DT = 0.1;

/**
 * The fraction of the gap a per-frame ease `k` (authored at 60 fps) closes over
 * `dt` seconds: `x += (target - x) * perFrame(k, dt)` feels at every frame rate
 * the way `x += (target - x) * k` felt at 60 fps.
 */
export const perFrame = (k: number, dt: number): number =>
  1 - Math.pow(1 - k, Math.max(0, dt) * 60);

/**
 * Exponential damping toward `target` with a rate in 1/s — the time-based
 * form of the same ease (`lambda` ≈ 60·k for small k).
 */
export const damp = (
  current: number,
  target: number,
  lambda: number,
  dt: number,
): number => current + (target - current) * (1 - Math.exp(-lambda * dt));

export interface FrameClock {
  /**
   * Call once per frame with the rAF timestamp (ms). Returns `dt`, the clamped
   * step since the last frame, and `t`, the time since the first frame — both
   * in seconds.
   */
  tick(nowMs: number): { dt: number; t: number };
  /** Forget the last frame (after a pause) so the next `dt` is 0, not the pause. */
  reset(): void;
}

/** One time source in seconds, shared by every path that draws the scene. */
export const createFrameClock = (): FrameClock => {
  let first = -1;
  let last = -1;
  return {
    tick(nowMs) {
      if (first < 0) first = nowMs;
      const dt = last < 0 ? 0 : Math.min(MAX_FRAME_DT, (nowMs - last) / 1000);
      last = nowMs;
      return { dt: Math.max(0, dt), t: (nowMs - first) / 1000 };
    },
    reset() {
      last = -1;
    },
  };
};

/**
 * Desktop draw gate: 12.5 ms sits between a 120 Hz (8.3 ms) and a 60 Hz
 * (16.7 ms) tick, so a 60 Hz screen draws every frame and a 120 Hz one every
 * other. Desktop WebGL scenes redrawing at 120 Hz were the steady scroll-drop
 * cause on several production sites (rule); gating the draw at ~60 fps made
 * desktop scroll ideal. Gate the DRAW only — keep easing every tick (scaled by
 * `dt`). **Never on phones**: a fixed phone frame cap reads as choppy on a
 * 120 Hz iPhone and can trip a scene's own fps → DPR fallback.
 */
export const DESKTOP_DRAW_GATE_MS = 12.5;

export interface DrawGate {
  /** Call every tick with the frame's `dt` (s); true when this tick should draw. */
  shouldDraw(dt: number): boolean;
  /** Draw on the next tick regardless (a resize, a state change, a rebuild). */
  force(): void;
}

/**
 * `const gate = createDrawGate(isDesktop)` — then in the loop, after easing:
 * `if (gate.shouldDraw(dt)) renderer.render(scene, camera)`. With
 * `enabled = false` (phones, tablets) it draws every tick.
 */
export const createDrawGate = (
  enabled: boolean,
  intervalMs: number = DESKTOP_DRAW_GATE_MS,
): DrawGate => {
  let since = Infinity;
  return {
    shouldDraw(dt) {
      if (!enabled) return true;
      since += dt * 1000;
      if (since < intervalMs) return false;
      since = 0;
      return true;
    },
    force() {
      since = Infinity;
    },
  };
};

// 📖 Docs: obsidian/frontend/webgl-scenes.md → "A lost context"

/**
 * WebGL context-loss recovery — the hero scene always comes back.
 *
 * iOS drops WebGL contexts under memory pressure (decoding big images while
 * the scene is off screen is enough). Without a handler a lost context is a
 * permanent blank: scroll the page and back, and the hero is gone. Reproduce it
 * with `gl.getExtension("WEBGL_lose_context").loseContext()`.
 *
 * The recovery, measured on a production site (a context-loss probe FAIL →
 * PASS, scroll and Lighthouse unchanged):
 *  1. `webglcontextlost` → `preventDefault()` (without it the browser never
 *     offers a restore) and mark the scene broken;
 *  2. when the scene nears the viewport, the tab returns, or the page comes
 *     back from the bfcache, a broken scene is **rebuilt on a fresh context**
 *     — at rest, no intro replay — rather than trusted in place (a restored
 *     context comes back with every *rendered* resource empty: environment
 *     maps, render targets);
 *  3. rebuilds are spaced (≥ 1 s) and a build that throws is retried a few
 *     times, so a device that keeps dropping contexts can't spin;
 *  4. every teardown releases its context at once (`releaseContext`), not at
 *     garbage collection — a rebuild otherwise holds two;
 *  5. optionally, while the scene is on screen, a once-a-second self-check
 *     asks whether it is still drawing: an event WebKit never sends (or sends
 *     during a rebuild) otherwise leaves the hero blank until the reader
 *     scrolls away and back.
 *
 * Also: never stop drawing a *visible* canvas on iOS — pause only off screen.
 * iOS drops the last frame after a toolbar resize, and a stopped scene never
 * repaints.
 *
 *   useEffect(() => keepSceneAlive({
 *     container: containerRef.current!,
 *     build: async ({ settled, onContextChange }) => {
 *       const scene = await createHeroScene(containerRef.current!, { skipIntro: settled });
 *       const stop = watchContext(scene.canvas, onContextChange);
 *       return {
 *         isBroken: () => scene.gl.isContextLost(),
 *         frames: () => scene.frameCount,
 *         dispose: () => { stop(); scene.dispose(); releaseContext(scene.gl); scene.canvas.remove(); },
 *       };
 *     },
 *   }), []);
 */

type GL = WebGLRenderingContext | WebGL2RenderingContext;

/**
 * Listen for context loss and restore on `canvas`. `onChange` fires on either;
 * the loss is `preventDefault`ed so the browser may restore. Returns cleanup.
 */
export const watchContext = (
  canvas: HTMLCanvasElement | OffscreenCanvas,
  onChange: (event: "lost" | "restored") => void,
): (() => void) => {
  const lost = (event: Event) => {
    event.preventDefault();
    onChange("lost");
  };
  const restored = () => onChange("restored");
  canvas.addEventListener("webglcontextlost", lost);
  canvas.addEventListener("webglcontextrestored", restored);
  return () => {
    canvas.removeEventListener("webglcontextlost", lost);
    canvas.removeEventListener("webglcontextrestored", restored);
  };
};

/**
 * Hand the GPU memory back now (three.js: `renderer.forceContextLoss()` does
 * the same). Safe on an already-lost context.
 */
export const releaseContext = (gl: GL | null | undefined): void => {
  if (!gl || gl.isContextLost()) return;
  gl.getExtension("WEBGL_lose_context")?.loseContext();
};

export interface SceneHandle {
  /** The context is lost, or the scene otherwise can't draw. */
  isBroken(): boolean;
  /** Frames drawn so far — enables the on-screen self-check. Omit to skip it. */
  frames?(): number;
  /** Stop the loop, free GPU resources (`releaseContext`), remove the canvas. */
  dispose(): void;
}

export interface KeepSceneAliveOptions<H extends SceneHandle> {
  /** The scene's box — observed for proximity and visibility. */
  container: Element;
  /**
   * Build the scene. `settled` is true for a rebuild (skip the intro: the
   * reader already saw it). Wire `onContextChange` to `watchContext` on the
   * new canvas. May throw/reject when no context can be had.
   */
  build(context: { settled: boolean; onContextChange: () => void }): H | Promise<H>;
  /** How early to rebuild before the scene is back in view. */
  rootMargin?: string;
  /** Minimum time between two rebuilds. */
  gapMs?: number;
  /** Builds that may fail in a row before giving up for the visit. */
  maxFailures?: number;
  /** Self-check period while on screen (needs `handle.frames`); 0 disables. */
  watchMs?: number;
  /** Called when a build fails — e.g. show the still instead. */
  onFail?(error: unknown): void;
}

/** Build the scene and keep it alive. Returns the cleanup for the effect. */
export function keepSceneAlive<H extends SceneHandle>({
  container,
  build,
  rootMargin = "50% 0px",
  gapMs = 1000,
  maxFailures = 3,
  watchMs = 1000,
  onFail,
}: KeepSceneAliveOptions<H>): () => void {
  let current: H | null = null;
  let generation = 0;
  let building = false;
  let recheck = false;
  let failures = 0;
  let near = true;
  let inView = false;
  let cancelled = false;
  let lastBuild = Number.NEGATIVE_INFINITY;
  let retryTimer: ReturnType<typeof setTimeout> | undefined;
  let watchTimer: ReturnType<typeof setInterval> | undefined;
  let lastFrames = -1;
  let stalls = 0;

  const mount = (settled: boolean): void => {
    const mine = ++generation;
    current?.dispose();
    current = null;
    building = true;
    lastBuild = performance.now();
    Promise.resolve()
      .then(() =>
        build({
          settled,
          // A loss while still building is not dropped: re-checked on landing.
          onContextChange: () => {
            if (building) recheck = true;
            else if (near) ensureAlive();
          },
        }),
      )
      .then((handle) => {
        if (cancelled || mine !== generation) return handle.dispose();
        building = false;
        failures = 0;
        current = handle;
        if (recheck || handle.isBroken()) {
          recheck = false;
          if (near) ensureAlive();
        }
      })
      .catch((error: unknown) => {
        if (cancelled || mine !== generation) return;
        building = false;
        failures += 1;
        onFail?.(error);
      });
  };

  const ensureAlive = (): void => {
    if (cancelled || building) return;
    if (current && !current.isBroken()) return;
    if (!current && failures >= maxFailures) return;
    const wait = lastBuild + gapMs - performance.now();
    if (wait > 0) {
      if (retryTimer) clearTimeout(retryTimer);
      retryTimer = setTimeout(() => near && ensureAlive(), wait);
      return;
    }
    mount(true);
  };

  const watch = (): void => {
    if (cancelled || building || !inView || document.hidden || !current?.frames) return;
    const frames = current.frames();
    if (current.isBroken() || frames !== lastFrames) {
      lastFrames = frames;
      stalls = 0;
      if (current.isBroken()) ensureAlive();
      return;
    }
    // Two looks in a row without a new frame while on screen: rebuild.
    if (++stalls < 2) return;
    stalls = 0;
    lastFrames = -1;
    current.dispose();
    current = null;
    ensureAlive();
  };

  const nearby = new IntersectionObserver(
    ([entry]) => {
      near = entry.isIntersecting;
      if (near) ensureAlive();
    },
    { rootMargin },
  );
  const visible = new IntersectionObserver(([entry]) => {
    inView = entry.isIntersecting;
    if (inView && watchMs > 0 && !watchTimer) {
      lastFrames = -1;
      stalls = 0;
      watchTimer = setInterval(watch, watchMs);
    } else if (!inView && watchTimer) {
      clearInterval(watchTimer);
      watchTimer = undefined;
    }
  });
  nearby.observe(container);
  visible.observe(container);

  const onReturn = (): void => {
    if (!document.hidden && near) ensureAlive();
  };
  document.addEventListener("visibilitychange", onReturn);
  window.addEventListener("pageshow", onReturn);

  mount(false);

  return () => {
    cancelled = true;
    nearby.disconnect();
    visible.disconnect();
    document.removeEventListener("visibilitychange", onReturn);
    window.removeEventListener("pageshow", onReturn);
    if (retryTimer) clearTimeout(retryTimer);
    if (watchTimer) clearInterval(watchTimer);
    current?.dispose();
    current = null;
  };
}

// 📖 Docs: obsidian/frontend/seo-metadata.md

/**
 * Site-wide configuration — the single source of truth for SEO.
 *
 * Consumed by the metadata generator, `manifest.ts`, `robots.ts`,
 * `sitemap.ts`, and the JSON-LD helper. **Server-only**: it reads the server
 * env (and so `zod`) — a client component that imports it ships ~69 KB gz of
 * zod to every visitor. Client code that needs the brand name gets it as a prop
 * or from a plain constants module.
 *
 * ⚠️ Every `TODO:` value below is a placeholder. They render loudly in dev (the
 * tab title says TODO), warn on every build, and **fail a Vercel production
 * build** — production sites measured with the old quiet placeholders shipped
 * "New Project" as their title, OG card and JSON-LD name, and Lighthouse still
 * scored SEO 100 because a title *existed*.
 */
import { getServerEnv, publicEnv } from "@/env";

const TODO = "TODO:";

export type Weekday =
  | "Monday"
  | "Tuesday"
  | "Wednesday"
  | "Thursday"
  | "Friday"
  | "Saturday"
  | "Sunday";

/** Days that share opening times — `opens`/`closes` in 24 h `HH:MM`. */
export interface OpeningHours {
  days: readonly Weekday[];
  opens: string;
  closes: string;
}

const serverEnv = getServerEnv();

/**
 * Vercel's production domain, read at build time — the fallback when a deploy
 * doesn't set `NEXT_PUBLIC_SITE_URL`. Without it, sites that never set the
 * variable served `http://localhost:3000` as canonical, og:url, og:image and
 * every sitemap `<loc>` (11 of 12 live deploys checked).
 */
const vercelProduction = serverEnv.VERCEL_PROJECT_PRODUCTION_URL;

export const siteConfig = {
  /** The brand, exactly as the logo writes it. */
  name: `${TODO} Brand name`,
  /**
   * The home page's `<title>`: the brand + what it is, ≤ 60 characters
   * ("Acme — Industrial design studio"). Sub-pages use `%s · <name>`.
   */
  title: `${TODO} Brand — what it is`,
  /** 120–160 characters, from the site's own copy (the hero's lead line). */
  description: `${TODO} One or two sentences from the site's own copy, 120–160 characters.`,
  /** 5–8 phrases from the copy. */
  keywords: [] as string[],
  /**
   * Public origin, no trailing slash. Drives canonical URLs, OG tags, the
   * sitemap, robots.txt and JSON-LD. `NEXT_PUBLIC_SITE_URL` (set it for a
   * custom domain) → Vercel's production domain → localhost. `origin-sync.ts`
   * fixes JS-running readers on any other host.
   */
  url:
    publicEnv.NEXT_PUBLIC_SITE_URL ??
    (vercelProduction
      ? `https://${vercelProduction}`
      : "http://localhost:3000"),
  /** Default Open Graph / Twitter share image (path under `public/`), 1200×630. */
  ogImage: "/open-graph.png",
  /** Describes the share image for screen readers and when it fails to load. */
  ogImageAlt: `${TODO} What the share image shows`,
  /**
   * The site's real X/Twitter handle (`"@acme"`), or `undefined` — the
   * generator then omits the tags. Never invent one: it tags a stranger.
   */
  twitterHandle: undefined as string | undefined,
  /** Author / creator / publisher — the brand, not the agency. */
  author: `${TODO} Brand name`,
  /** Browser theme-color (address bar / PWA) — the brand's ground. */
  themeColor: "#000000",
  /** The manifest and the PWA splash background. */
  backgroundColor: "#000000",
  locale: "en_US",
  /**
   * Facts about the organisation — the JSON-LD `Organization` node and the
   * "Key facts" in `/llms.txt` read them. Answer engines weigh consistency:
   * write each exactly as the About page, Google Business Profile and LinkedIn
   * state it. Leave a field out rather than guess — an absent fact costs
   * nothing, a wrong one contradicts the rest of the web.
   */
  organization: {
    /** Year founded, `YYYY` (or `YYYY-MM-DD`). */
    foundingDate: undefined as string | undefined,
    /** Public contact address. */
    email: undefined as string | undefined,
    /** International format: `+44 20 7946 0000`. */
    telephone: undefined as string | undefined,
    /** A street address, for a business people visit or that serves an area. */
    address: undefined as
      | {
          streetAddress?: string;
          addressLocality: string;
          addressRegion?: string;
          postalCode?: string;
          /** ISO 3166-1 alpha-2, e.g. `GB`. */
          addressCountry: string;
        }
      | undefined,
    /** Profiles the site itself links to (LinkedIn, Instagram, Crunchbase…) — `sameAs`. */
    sameAs: [] as string[],
    /*
      Local business facts (skill: local-seo). Emitted only when the JSON-LD
      `type` is a LocalBusiness subtype — hours, coordinates and a price range
      mean nothing on a plain Organization. Copy them from the Google Business
      Profile, character for character: the site, the profile and every
      directory listing must agree.
    */
    /** Opening hours — one row per set of days sharing the same times (24 h `HH:MM`). */
    openingHours: [] as OpeningHours[],
    /** The entrance's coordinates — the pin on the Business Profile, 5+ decimals. */
    geo: undefined as { latitude: number; longitude: number } | undefined,
    /** Cities, regions or countries served — a service-area business's main fact. */
    areaServed: [] as string[],
    /** `$`–`$$$$`, or a range like `£40–£120`. */
    priceRange: undefined as string | undefined,
    /** The Google Business Profile / Maps listing URL. */
    hasMap: undefined as string | undefined,
  },
  /**
   * Which AI crawlers may read the site — `robots.ts` writes one named group
   * per crawler. Three purposes, three decisions (the client's, not ours — ask):
   * - `search`: crawlers that index for AI search answers and cite the page
   *   (OAI-SearchBot, Claude-SearchBot, PerplexityBot). Blocking them drops
   *   the site from those answers.
   * - `userFetch`: fetches a person asked an assistant to make (ChatGPT-User,
   *   Claude-User, Perplexity-User).
   * - `training`: crawlers that collect text for model training (GPTBot,
   *   ClaudeBot, CCBot, Google-Extended, Applebot-Extended…). Blocking them is
   *   a training opt-out and does not, by itself, remove citations; it never
   *   affects Google Search.
   */
  aiCrawlers: {
    search: true,
    userFetch: true,
    training: true,
  },
  /** Search engine ownership codes, from the server env (`.env.example`). */
  verification: {
    google: serverEnv.GOOGLE_SITE_VERIFICATION,
    bing: serverEnv.BING_SITE_VERIFICATION,
  },
};

/** The fields still holding a `TODO:` placeholder. */
const unset = Object.entries(siteConfig)
  .filter(([, value]) => typeof value === "string" && value.startsWith(TODO))
  .map(([key]) => key);

if (unset.length > 0) {
  const message = `siteConfig has placeholder values: ${unset.join(", ")} — set them in src/lib/site.ts`;
  if (serverEnv.VERCEL_ENV === "production") throw new Error(message);
  const flagged = globalThis as { __siteConfigWarned?: boolean };
  if (!flagged.__siteConfigWarned) {
    flagged.__siteConfigWarned = true;
    console.warn(`⚠ ${message}`);
  }
}

/**
 * @fileoverview Configuration file for Spring animation components
 *
 * Global configuration for all Spring components.
 * Controls behavior and features across the entire application.
 *
 * disableOnMobile: Controls which spring animations are disabled on mobile devices
 * - hover: Disable hover animations on mobile (default: true since no hover on mobile)
 * - inview: Disable in-view animations on mobile
 * - spring: Disable basic spring animations on mobile
 * - springtrigger: Disable scroll-triggered animations on mobile
 */
interface SpringsConfig {
  mobileWidth: number;
  disableOnMobile: {
    hover: boolean;
    inview: boolean;
    spring: boolean;
    springtrigger: boolean;
  };
}

export const springsConfig: SpringsConfig = {
  mobileWidth: 768,
  disableOnMobile: {
    hover: true,
    inview: false,
    spring: false,
    springtrigger: false,
  },
} as const;

/**
 * @param value - whether the animation opts into mobile-disabling
 * @param viewportWidth - optional explicit width (px); pass a React-tracked
 *   value here so callers re-evaluate on resize. Omitted (event handlers) →
 *   `window.innerWidth`.
 *
 * A tracked width of **0** means "not measured yet": `useWindowWidth()`
 * returns its server snapshot (0) during hydration. That must answer like the
 * server (`false`), never fall back to `window.innerWidth` — on a phone the
 * fallback made a render that hides an element differ from the server HTML
 * (React #418, the whole root re-rendered: a 453 ms task measured on a
 * production site). The real width arrives on the next render.
 */
export const isMobileDisabled = (value: boolean, viewportWidth?: number) => {
  if (typeof window === "undefined") return false;
  if (!value) return false;
  if (viewportWidth === 0) return false;
  const width = viewportWidth ?? window.innerWidth;
  return width <= springsConfig.mobileWidth;
};

