/**
 * A bag of animatable values — the shape `from`/`to` take on every spring
 * component. Values are plain numbers, or strings carrying a CSS unit or
 * transform function (`"10px"`, `"45deg"`, `"translate(10px)"`).
 */
export type SpringValues = Record<string, string | number>;

/**
 * @fileoverview Utility function to transform a value from one range to another
 * Takes a value and maps it from its original min/max range to a new min/max range
 * Clamps the input value to the original range before transforming
 */
export const transformRange = (
  value: number,
  min: number,
  max: number,
  newMin: number,
  newMax: number,
) => {
  const normalized = (Math.min(Math.max(value, min), max) - min) / (max - min);
  return newMin + normalized * (newMax - newMin);
};

/**
 * @fileoverview Linear interpolation (lerp) function for smooth transitions
 * Calculates intermediate value between start and end based on interpolation factor
 * Commonly used for animations and gradual value changes
 * @param start Starting value
 * @param end Ending value
 * @param t Interpolation factor (0-1)
 * @returns Interpolated value
 */
export const lerp = (start: number, end: number, t: number): number => {
  return start * (1 - t) + end * t;
};

/**
 * @fileoverview Debounce utility to limit how often a function can be called
 * Creates a debounced version of the provided function that delays execution
 * Useful for handling frequent events like resize or scroll
 */
export const debounce = <T extends (...args: never[]) => void>(
  func: T,
  delay: number,
): T => {
  let timeout: NodeJS.Timeout;
  return ((...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), delay);
  }) as T;
};

/**
 * @fileoverview Interpolation utility for transitioning between object states
 * Takes a start object and end object with numeric or unit-based values (e.g. '10px', 'rotate(45deg)')
 * Interpolates between corresponding properties based on a progress value (0-1)
 * Handles CSS units and transform functions while maintaining correct formatting
 * Returns an object with interpolated values in their original format
 */
export const interpolate = (
  start: SpringValues,
  end: SpringValues,
  progress: number,
): SpringValues => {
  const result: SpringValues = {};

  // Helper to extract number from string with units
  const extractNumber = (
    value: unknown,
  ): { number: number; unit: string | null } => {
    if (typeof value === "number") return { number: value, unit: null };
    if (typeof value === "string") {
      // Handle CSS transform functions like translate(10px) or rotate(45deg)
      const functionMatch = value.match(/^([a-zA-Z]+)\(([-0-9.]+)([^)]*)\)$/);
      if (functionMatch) {
        return {
          number: parseFloat(functionMatch[2]),
          unit: `${functionMatch[1]}(${functionMatch[3]})`,
        };
      }
      // Handle regular values with units like 45deg or 100px
      const match = value.match(/([-0-9.]+)([^0-9.]+)/);
      if (match) {
        return {
          number: parseFloat(match[1]),
          unit: match[2],
        };
      }
    }
    return { number: 0, unit: null };
  };

  // Interpolate each property in the objects
  for (const key in start) {
    const startVal = extractNumber(start[key]);
    const endVal = extractNumber(end[key]);

    if (startVal.unit !== null || endVal.unit !== null) {
      const unit = startVal.unit || endVal.unit;
      if (unit?.includes("(")) {
        // Check if it's any CSS transform function
        result[key] =
          `${unit.split("(")[0]}(${lerp(startVal.number, endVal.number, progress)}${unit.split(")")[0].slice(unit.split("(")[0].length)})`;
      } else {
        result[key] =
          `${lerp(startVal.number, endVal.number, progress)}${unit}`;
      }
    } else {
      result[key] = lerp(startVal.number, endVal.number, progress);
    }
  }

  return result;
};

/**
 * @fileoverview Utility function for smooth scrolling to elements or positions
 * Handles both scrolling to element IDs and numeric positions
 * Temporarily disables scroll state during animation if scroll is enabled
 */

//if lenis
import { useScroll } from "@/hooks/smooth-scroll/use-scroll";
//endif

export const scrollTo = (id?: string | number, immediate?: boolean) => {
  //if lenis
  const isEnabled = useScroll.getState().isEnableScroll;
  //endif

  if (typeof id === "string") {
    const el = document.getElementById(id);
    if (!el) {
      return;
    }

    //if lenis
    if (isEnabled) {
      useScroll.setState({ isEnableScroll: false });
    }
    //endif

    setTimeout(() => {
      window.scrollTo({
        top: getDistanceFromTop(el),
        behavior: immediate ? "instant" : "smooth",
      });
    }, 50);
  } else {
    setTimeout(() => {
      window.scrollTo({
        top: Number(id) || 0,
        behavior: immediate ? "instant" : "smooth",
      });
    }, 50);
  }

  if (isEnabled) {
    setTimeout(() => {
      useScroll.setState({ isEnableScroll: true });
    }, 100);
  }

  function getDistanceFromTop(element: HTMLElement) {
    const rect = element.getBoundingClientRect();
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    return rect.top + scrollTop;
  }
};

/**
 * @fileoverview Standardised metadata + viewport generators for pages.
 * 📖 Docs: obsidian/frontend/seo-metadata.md
 *
 * `generateMetadata` builds a Next.js `Metadata` object — title (with the
 * site-wide template), description, keywords, OpenGraph, Twitter cards,
 * canonical URL, icons, robots. `metadataBase` is always set (from
 * `siteConfig`) so relative URLs (OG image, canonical) resolve to absolute —
 * required by social scrapers.
 *
 * `generateViewport` builds the `Viewport` export. `themeColor` lives here, not
 * in `Metadata` — Next deprecated it on the metadata object.
 */

import { Metadata, Viewport } from "next";

import { siteConfig } from "@/lib/site";

interface MetadataProps {
  /**
   * The page's own title. Omitted → the home title (`siteConfig.title`).
   * Given → rendered through the template as `<title> · <brand>`.
   */
  title?: string;
  description?: string;
  /** Canonical path (e.g. `/about`) or absolute URL for this page. */
  url?: string;
  /** Open Graph / Twitter image — path under `public/` or absolute URL, 1200×630. */
  ogImage?: string;
  ogImageAlt?: string;
  keywords?: string[];
  twitterHandle?: string;
  author?: string;
  siteName?: string;
  /**
   * The title is the whole `<title>` — not run through `· <brand>`. Set by
   * the CMS (`cms/content.ts`): an editor writes, and the SEO plugin counts,
   * exactly what a search result shows.
   */
  absoluteTitle?: boolean;
  /** The share image's real size — an uploaded image passes its own. */
  ogImageSize?: { width: number; height: number };
  /** Keep the page out of search results (the 404, or an editor's choice). */
  noIndex?: boolean;
  /** `og:locale` — `language_REGION`. */
  locale?: string;
  /**
   * Multi-language pages only: hreflang code → path or URL for every language
   * version, this one and `x-default` included — `routeLanguages(path)`
   * (`src/utils/seo/hreflang.ts`) builds it from the route registry. Omitted →
   * no hreflang links, as on a single-language site.
   */
  languages?: Record<string, string>;
  /** `og:locale:alternate` — the other versions' locales (`de_DE`…). */
  alternateLocales?: string[];
}

export function generateMetadata({
  title,
  description = siteConfig.description,
  url = "/",
  ogImage = siteConfig.ogImage,
  ogImageAlt = siteConfig.ogImageAlt,
  keywords = siteConfig.keywords,
  twitterHandle = siteConfig.twitterHandle,
  author = siteConfig.author,
  siteName = siteConfig.name,
  absoluteTitle = false,
  ogImageSize = { width: 1200, height: 630 },
  noIndex = false,
  locale = siteConfig.locale,
  languages,
  alternateLocales,
}: MetadataProps = {}): Metadata {
  // The `<title>`: the home title as is, a page title through the template
  // (or as given, when the CMS wrote the whole of it).
  const fullTitle = title ? (absoluteTitle ? title : `${title} · ${siteName}`) : siteConfig.title;
  const image = { url: ogImage, ...ogImageSize, alt: ogImageAlt };
  const { verification } = siteConfig;

  return {
    // Resolves every relative URL below to an absolute one.
    metadataBase: new URL(siteConfig.url),
    title: title
      ? { absolute: fullTitle }
      : { default: siteConfig.title, template: `%s · ${siteName}` },
    description,
    applicationName: siteName,
    ...(keywords.length > 0 ? { keywords } : {}),
    authors: [{ name: author }],
    creator: author,
    publisher: author,
    // Each language version is canonical to itself — never to another language.
    alternates: {
      canonical: url,
      ...(languages ? { languages } : {}),
    },
    openGraph: {
      title: fullTitle,
      description,
      url,
      siteName,
      // The image must really be 1200×630 — scrapers crop or letterbox a
      // mismatch. Replace the placeholder in public/.
      images: [image],
      locale,
      ...(alternateLocales?.length ? { alternateLocale: alternateLocales } : {}),
      type: "website",
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      // No handle → no tags. An invented handle tags a stranger.
      ...(twitterHandle ? { site: twitterHandle, creator: twitterHandle } : {}),
      images: [image],
    },
    // `icon.svg` first: modern browsers take the vector. There is deliberately
    // no `src/app/favicon.ico` — Next links that file convention ahead of these
    // and it wins `/favicon.ico`; the ICO lives in `public/` instead.
    icons: {
      icon: [
        { url: "/icon.svg", type: "image/svg+xml" },
        { url: "/favicon.ico", sizes: "48x48" },
        { url: "/favicon-32x32.png", sizes: "32x32", type: "image/png" },
        { url: "/favicon-16x16.png", sizes: "16x16", type: "image/png" },
      ],
      apple: [
        { url: "/apple-icon-180x180.png", sizes: "180x180", type: "image/png" },
      ],
    },
    // `src/app/manifest.ts` is linked automatically.
    robots: {
      index: !noIndex,
      follow: true,
    },
    // Search Console / Bing Webmaster ownership — only the codes that are set.
    ...(verification.google || verification.bing
      ? {
          verification: {
            ...(verification.google ? { google: verification.google } : {}),
            ...(verification.bing ? { other: { "msvalidate.01": verification.bing } } : {}),
          },
        }
      : {}),
  };
}

export function generateViewport(): Viewport {
  return {
    themeColor: siteConfig.themeColor,
    width: "device-width",
    initialScale: 1,
  };
}

/**
 * @fileoverview hreflang — the language versions of a page, for `<head>` and
 * the sitemap. 📖 Docs: obsidian/frontend/seo-metadata.md · skill: i18n-seo
 *
 * Opt-in: a single-language site never calls this and emits no hreflang.
 * A multi-language page lists *every* version of itself, its own included,
 * in `ROUTES[].alternates` (`src/lib/routes.ts`); `routeLanguages(path)` turns
 * that into the `alternates.languages` map `generateMetadata({ languages })`
 * and `sitemap.ts` take — with `x-default` added. Each version carries the
 * same cluster, so the links are reciprocal by construction (a one-way
 * hreflang is ignored by Google). `yarn qa:seo` checks the served result.
 *
 * Plain functions over plain data — no `siteConfig` — so client code may use
 * it too. Paths stay relative here; `metadataBase` / the sitemap make them
 * absolute.
 */

import { findRoute } from "@/lib/routes";

export const X_DEFAULT = "x-default";

/*
  Country codes people write where the language code belongs. Each is either
  not an ISO 639-1 code at all or a different language — Google ignores the
  tag, or files the page under the wrong language.
*/
const COUNTRY_AS_LANGUAGE: Record<string, string> = {
  jp: "ja",
  gr: "el",
  cz: "cs",
  dk: "da",
  ua: "uk",
  cn: "zh",
  kr: "ko",
  vn: "vi",
  il: "he",
};

/** Regions that are not ISO 3166-1 alpha-2 codes, though they look like one. */
const NOT_REGIONS: Record<string, string> = { UK: "GB", EU: "a country", UN: "a country" };

/**
 * Why an hreflang value is wrong, or `null` when it is valid: an ISO 639-1
 * language (`de`), optionally a script (`zh-Hant`) and an ISO 3166-1 region
 * (`en-GB`), hyphen-separated — or `x-default`. Google reads only alpha-2
 * regions: a UN M.49 one like `es-419` is ignored.
 */
export function hreflangProblem(code: string): string | null {
  if (code === X_DEFAULT) return null;
  if (code.includes("_")) return `"${code}": a hyphen, not an underscore (${code.replace(/_/g, "-")})`;
  const match = /^([a-z]{2,3})(?:-([A-Z][a-z]{3}))?(?:-([A-Z]{2}|\d{3}))?$/i.exec(code);
  if (!match) return `"${code}" is not language[-Script][-REGION]`;
  const [, language, , region] = match;
  const swap = COUNTRY_AS_LANGUAGE[language.toLowerCase()];
  if (swap) return `"${language}" is a country code — the language is "${swap}"`;
  if (region && /^\d+$/.test(region)) return `"${region}": Google reads ISO 3166-1 alpha-2 regions only — list each country`;
  const notRegion = region && NOT_REGIONS[region.toUpperCase()];
  if (notRegion) return `"${region}" is not an ISO 3166-1 region — use ${notRegion}`;
  return null;
}

/**
 * The `alternates.languages` map for one page: every version (its own
 * included), plus `x-default` → the `defaultLanguage` version (the first
 * listed when omitted) unless the cluster names one. Throws on an invalid
 * code or a cluster that leaves the page out — a build that fails beats a
 * cluster Google silently drops.
 */
export function languageAlternates(
  path: string,
  versions: Readonly<Record<string, string>>,
  defaultLanguage?: string,
): Record<string, string> {
  const codes = Object.keys(versions);
  const problems = codes.map(hreflangProblem).filter((p): p is string => p !== null);
  if (problems.length > 0) throw new Error(`[hreflang] ${path}: ${problems.join("; ")}`);
  if (!Object.values(versions).includes(path)) {
    throw new Error(`[hreflang] ${path}: its alternates must list the page itself`);
  }
  if (X_DEFAULT in versions || codes.length === 0) return { ...versions };
  const fallback = versions[defaultLanguage ?? codes[0]];
  if (fallback === undefined) {
    throw new Error(`[hreflang] ${path}: default language "${defaultLanguage}" is not among its versions`);
  }
  return { ...versions, [X_DEFAULT]: fallback };
}

/** The registry's language versions of a route, or `undefined` for a single-language page. */
export function routeLanguages(path: string): Record<string, string> | undefined {
  const versions = findRoute(path)?.alternates;
  return versions ? languageAlternates(path, versions) : undefined;
}

/**
 * @fileoverview JSON-LD structured data helpers.
 * 📖 Docs: obsidian/frontend/seo-metadata.md · skill: schema-markup
 *
 * Structured data lets search and answer engines read the site as entities
 * (an Organization, its WebSite, a page's place in the site, an article and
 * its author) rather than only as text. Every builder here returns a node;
 * `jsonLdGraph()` wraps nodes into one document, `<JsonLd>`
 * (`src/components/common/json-ld.tsx`) renders it. Entities link by `@id`, so
 * the Organization is defined once (root layout) and referenced everywhere.
 *
 * Only describe what is on the page — schema claiming content the page does
 * not show is spam. Check Google's supported-features gallery before adding a
 * type for a rich result: FAQ (May 2026), HowTo (2023) and the sitelinks
 * search box (2024) no longer show any.
 */

import { routeTrail } from "@/lib/routes";
import { siteConfig, type OpeningHours } from "@/lib/site";

/** A JSON value a JSON-LD node may hold. */
export type JsonLdValue =
  | string
  | number
  | boolean
  | JsonLdNode
  | readonly JsonLdValue[];

/** One JSON-LD node — `@type` plus its properties. */
export interface JsonLdNode {
  [property: string]: JsonLdValue;
}

/** A path under `public/`, or a page path, becomes an absolute URL on the site's origin. */
export const absoluteUrl = (url: string): string =>
  url.startsWith("/") ? `${siteConfig.url}${url === "/" ? "" : url}` : url;

/** The `@id` of the site's Organization and WebSite nodes — reference them, don't repeat them. */
export const ORGANIZATION_ID = `${siteConfig.url}/#organization`;
export const WEBSITE_ID = `${siteConfig.url}/#website`;

/** Wraps nodes into one JSON-LD document. */
export const jsonLdGraph = (...nodes: JsonLdNode[]): JsonLdNode => ({
  "@context": "https://schema.org",
  "@graph": nodes,
});

/** Overrides — a CMS's SEO global passes these; `siteConfig` fills the rest. */
export interface StructuredDataInput {
  /** The organisation's and the site's name — `og:site_name`'s twin. */
  name?: string;
  /** The legal name — the author/publisher the metadata carries. */
  legalName?: string;
  description?: string;
  /** The logo — a path under `public/` or an absolute URL. */
  logo?: string;
  /** The company's profiles elsewhere — `sameAs`. */
  sameAs?: readonly string[];
  /**
   * The schema.org type: `Organization`, or a `LocalBusiness` subtype
   * (`ProfessionalService`, `Restaurant`, `Dentist`…) for a business with a
   * place customers visit or an area it serves — then set the address.
   */
  type?: string;
}

/** Opening hours as schema.org `OpeningHoursSpecification` rows. */
const openingHoursSpecification = (rows: readonly OpeningHours[]): JsonLdNode[] =>
  rows.map(({ days, opens, closes }) => ({
    "@type": "OpeningHoursSpecification",
    dayOfWeek: [...days],
    opens,
    closes,
  }));

/** The LocalBusiness-only facts that are set — hours, coordinates, price range. */
const localFacts = ({
  openingHours = [],
  geo,
  priceRange,
}: {
  openingHours?: readonly OpeningHours[];
  geo?: { latitude: number; longitude: number };
  priceRange?: string;
}): JsonLdNode => ({
  ...(openingHours.length > 0
    ? { openingHoursSpecification: openingHoursSpecification(openingHours) }
    : {}),
  ...(geo ? { geo: { "@type": "GeoCoordinates", ...geo } } : {}),
  ...(priceRange ? { priceRange } : {}),
});

/**
 * Organization + WebSite schema for the site root. Emit once, in the root
 * layout. The two nodes are linked by `@id` so crawlers treat them as related.
 * The facts come from `siteConfig.organization` — only the ones that are set.
 */
export function getSiteStructuredData({
  name = siteConfig.name,
  legalName = siteConfig.author,
  description = siteConfig.description,
  logo = "/android-icon-192x192.png",
  sameAs = siteConfig.organization.sameAs,
  type = "Organization",
}: StructuredDataInput = {}): JsonLdNode {
  const { foundingDate, email, telephone, address, areaServed, hasMap } =
    siteConfig.organization;
  const local = type !== "Organization";
  return jsonLdGraph(
    {
      "@type": type,
      "@id": ORGANIZATION_ID,
      name,
      ...(legalName && legalName !== name ? { legalName } : {}),
      description,
      url: siteConfig.url,
      logo: absoluteUrl(logo),
      // A LocalBusiness also wants an image; the logo is the honest default.
      ...(type !== "Organization" ? { image: absoluteUrl(logo) } : {}),
      ...(foundingDate ? { foundingDate } : {}),
      ...(email ? { email } : {}),
      ...(telephone ? { telephone } : {}),
      ...(address ? { address: { "@type": "PostalAddress", ...address } } : {}),
      ...(email || telephone
        ? {
            contactPoint: {
              "@type": "ContactPoint",
              contactType: "customer service",
              ...(email ? { email } : {}),
              ...(telephone ? { telephone } : {}),
            },
          }
        : {}),
      ...(sameAs.length > 0 ? { sameAs: [...sameAs] } : {}),
      ...(areaServed.length > 0 ? { areaServed: [...areaServed] } : {}),
      ...(hasMap ? { hasMap } : {}),
      // Hours, coordinates and price range are LocalBusiness properties.
      ...(local ? localFacts(siteConfig.organization) : {}),
    },
    {
      "@type": "WebSite",
      "@id": WEBSITE_ID,
      name,
      description,
      url: siteConfig.url,
      inLanguage: siteConfig.locale.replace("_", "-"),
      publisher: { "@id": ORGANIZATION_ID },
    },
  );
}

/**
 * Home → … → the page, from the route registry's `parent` chain
 * (`src/lib/routes.ts`). `null` for the home page (a one-item trail says
 * nothing) and for a path the registry doesn't know.
 */
export function getBreadcrumbStructuredData(path: string): JsonLdNode | null {
  const trail = routeTrail(path);
  if (trail.length < 2) return null;
  return {
    "@type": "BreadcrumbList",
    "@id": `${absoluteUrl(path)}#breadcrumb`,
    itemListElement: trail.map((route, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: route.label,
      item: absoluteUrl(route.path),
    })),
  };
}

/** A person — an article's author, a team member. */
export interface PersonInput {
  name: string;
  /** Their page on this site, or a profile that is clearly theirs. */
  url?: string;
  jobTitle?: string;
  image?: string;
  /** Their profiles elsewhere (LinkedIn…). */
  sameAs?: readonly string[];
}

export const getPersonStructuredData = ({
  name,
  url,
  jobTitle,
  image,
  sameAs = [],
}: PersonInput): JsonLdNode => ({
  "@type": "Person",
  name,
  ...(url ? { url: absoluteUrl(url) } : {}),
  ...(jobTitle ? { jobTitle } : {}),
  ...(image ? { image: absoluteUrl(image) } : {}),
  ...(sameAs.length > 0 ? { sameAs: [...sameAs] } : {}),
  worksFor: { "@id": ORGANIZATION_ID },
});

export interface ArticleInput {
  /** The article's path, e.g. `/journal/how-we-work`. */
  path: string;
  /** The visible headline — the page's `<h1>`. */
  headline: string;
  description: string;
  /** At least one image, path or URL — Google requires it. */
  image: string;
  /** `YYYY-MM-DD` (or full ISO) — shown on the page too. */
  datePublished: string;
  /** The last real edit — shown on the page as "Updated …". */
  dateModified?: string;
  author: PersonInput;
  /** `BlogPosting` for a blog, `NewsArticle` for news; `Article` otherwise. */
  type?: "Article" | "BlogPosting" | "NewsArticle";
}

/** An article or blog post — author, dates and publisher are what answer engines weigh. */
export const getArticleStructuredData = ({
  path,
  headline,
  description,
  image,
  datePublished,
  dateModified,
  author,
  type = "BlogPosting",
}: ArticleInput): JsonLdNode => ({
  "@type": type,
  "@id": `${absoluteUrl(path)}#article`,
  headline,
  description,
  image: [absoluteUrl(image)],
  datePublished,
  dateModified: dateModified ?? datePublished,
  author: getPersonStructuredData(author),
  publisher: { "@id": ORGANIZATION_ID },
  mainEntityOfPage: absoluteUrl(path),
  inLanguage: siteConfig.locale.replace("_", "-"),
});

export interface ServiceInput {
  /** The service page's path. */
  path: string;
  name: string;
  description: string;
  /** The category of service, in searchers' words ("Brand identity design"). */
  serviceType?: string;
  /** Where it is offered — a city, region or country name. */
  areaServed?: string | readonly string[];
}

/** A service the organisation offers — one per service page. */
export const getServiceStructuredData = ({
  path,
  name,
  description,
  serviceType,
  areaServed,
}: ServiceInput): JsonLdNode => ({
  "@type": "Service",
  "@id": `${absoluteUrl(path)}#service`,
  name,
  description,
  url: absoluteUrl(path),
  ...(serviceType ? { serviceType } : {}),
  ...(areaServed ? { areaServed: typeof areaServed === "string" ? areaServed : [...areaServed] } : {}),
  provider: { "@id": ORGANIZATION_ID },
});

export interface FaqItem {
  question: string;
  /** Plain text — the answer exactly as the page shows it. */
  answer: string;
}

/**
 * A visible FAQ section. Google no longer shows FAQ rich results (May 2026),
 * so this is for answer engines and for describing the page — never for
 * questions the page doesn't show.
 */
export const getFaqStructuredData = (
  path: string,
  items: readonly FaqItem[],
): JsonLdNode => ({
  "@type": "FAQPage",
  "@id": `${absoluteUrl(path)}#faq`,
  mainEntity: items.map(({ question, answer }) => ({
    "@type": "Question",
    name: question,
    acceptedAnswer: { "@type": "Answer", text: answer },
  })),
});

export interface LocalBusinessInput {
  /** The location page's path, e.g. `/locations/leeds`. */
  path: string;
  /** The location's name as its Business Profile writes it ("Acme Leeds"). */
  name: string;
  /** Required — a location without an address is a service area, not a place. */
  address: NonNullable<typeof siteConfig.organization.address>;
  telephone?: string;
  email?: string;
  geo?: { latitude: number; longitude: number };
  openingHours?: readonly OpeningHours[];
  priceRange?: string;
  /** A photo of this location — path or URL. Falls back to the site's logo. */
  image?: string;
  /** This location's Google Business Profile / Maps listing. */
  hasMap?: string;
  /** A LocalBusiness subtype — `Dentist`, `Restaurant`, `ProfessionalService`… */
  type?: string;
}

/**
 * One location of a multi-location business — emit on that location's page.
 * Its own `@id`, tied to the brand by `parentOrganization`. Every value must
 * match the location's Business Profile (skill: local-seo).
 */
export const getLocalBusinessStructuredData = ({
  path,
  name,
  address,
  telephone,
  email,
  geo,
  openingHours,
  priceRange,
  image = "/android-icon-192x192.png",
  hasMap,
  type = "LocalBusiness",
}: LocalBusinessInput): JsonLdNode => ({
  "@type": type,
  "@id": `${absoluteUrl(path)}#location`,
  name,
  url: absoluteUrl(path),
  image: absoluteUrl(image),
  address: { "@type": "PostalAddress", ...address },
  ...(telephone ? { telephone } : {}),
  ...(email ? { email } : {}),
  ...localFacts({ openingHours, geo, priceRange }),
  ...(hasMap ? { hasMap } : {}),
  parentOrganization: { "@id": ORGANIZATION_ID },
});

// 📖 Docs: obsidian/frontend/webgl-scenes.md → "The iOS toolbar"

/**
 * A viewport height that does not follow the mobile browser's toolbar.
 *
 * iOS Safari collapses and expands its URL bar while the page scrolls: the
 * viewport's height changes, `resize` fires, `100dvh` / `fixed inset-0` boxes
 * change height, and a WebGL renderer that follows them reallocates its
 * drawing buffer (cleared → a blank frame) and re-renders — the scene flickers
 * on every scroll direction change (measured on 4 production sites; one also
 * re-randomised its physics on every resize, another went black for good).
 *
 * So a scene's box is sized to the **large** viewport (the toolbar collapsed),
 * measured once, and on touch devices it is re-measured only when the width
 * changes (a rotation). A desktop window still follows every resize.
 */

/** A phone or tablet: the devices whose toolbar moves with the scroll. */
export const isTouchViewport = (): boolean =>
  typeof window !== "undefined" &&
  (window.matchMedia("(pointer: coarse)").matches ||
    (navigator.maxTouchPoints > 0 && /Android|iPhone|iPad|iPod|Mobi/i.test(navigator.userAgent)));

/** The large viewport height in CSS px: `100lvh`, never less than `innerHeight`. */
const largeViewportHeight = (): number => {
  const probe = document.createElement("div");
  probe.style.cssText = "position:fixed;top:0;left:0;width:0;height:100lvh;visibility:hidden;pointer-events:none";
  document.body.appendChild(probe);
  const lvh = probe.getBoundingClientRect().height;
  probe.remove();
  return Math.round(Math.max(lvh, window.innerHeight));
};

/** A rotation settles its height a beat after the first `resize`. */
const ROTATION_SETTLE_MS = 300;

let width = 0;
let height = 0;
let bound = false;
let settleTimer: ReturnType<typeof setTimeout> | undefined;
const listeners = new Set<() => void>();

const publish = (nextHeight: number) => {
  if (nextHeight === height) return;
  height = nextHeight;
  listeners.forEach((listener) => listener());
};

const onResize = () => {
  const nextWidth = window.innerWidth;
  // A height-only change on a touch device is the toolbar: ignore it.
  if (isTouchViewport() && nextWidth === width) return;
  width = nextWidth;
  publish(largeViewportHeight());
  if (settleTimer) clearTimeout(settleTimer);
  settleTimer = setTimeout(() => publish(largeViewportHeight()), ROTATION_SETTLE_MS);
};

export const subscribeStableViewport = (listener: () => void): (() => void) => {
  if (!bound) {
    width = window.innerWidth;
    height = largeViewportHeight();
    window.addEventListener("resize", onResize, { passive: true });
    bound = true;
  }
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
    if (listeners.size > 0) return;
    window.removeEventListener("resize", onResize);
    if (settleTimer) clearTimeout(settleTimer);
    bound = false;
  };
};

/** The locked height in CSS px (0 before the first subscriber). */
export const getStableViewportHeight = (): number => height;

// 📖 Docs: obsidian/frontend/utils.md → "warmImage"

import { getImageProps, type ImageProps } from "next/image";

/**
 * Warm (download + decode) exactly the candidate a rendered `<Image>` will
 * pick — never the source file.
 *
 * A preloader, a reveal or a canvas effect that does
 * `new Image().src = "/assets/hero.png"` downloads the multi-megabyte original
 * from `public/`, while the page's `<Image>` asks `/_next/image` for a
 * 30–200 KB AVIF/WebP. Measured on four production sites: page weight
 * 11.5 → 0.57 MB, hosted mobile LCP 31.0 → 3.7 s; a canvas reveal's photo
 * 2,776 → 20 KB. Pass the same `src`/`width`/`height`/`sizes`/`quality` the
 * `<Image>` gets — keep one spec object for both — and the warm-up hits the
 * same URL, so the rendered image comes from cache.
 *
 *   const HERO = { src: "/assets/hero/plate.jpg", width: 2400, height: 1600, sizes: "100vw", alt: "" };
 *   <Image {...HERO} alt={HERO.alt} priority />
 *   await warmImage(HERO);            // in a preloader / before a reveal
 *   const img = await warmImage(SPEC); // a canvas effect draws `img`
 *
 * Below-the-fold warming belongs after `load`, in idle time — never during the
 * page's own load. CSS backgrounds: take `getImageProps(...).props.srcSet`
 * and write it as `image-set(url(…) 1x, url(…) 2x)` instead of a raw `url()`.
 */
export const warmImage = (
  spec: Omit<ImageProps, "alt"> & { alt?: string },
): Promise<HTMLImageElement> => {
  const { props } = getImageProps({ alt: "", ...spec });
  const img = new Image();
  // Order matters: `sizes` and `srcset` before `src`, or the browser starts
  // fetching `src` (the largest candidate) before it knows the layout width.
  if (props.sizes) img.sizes = props.sizes;
  if (props.srcSet) img.srcset = props.srcSet;
  img.src = props.src;
  return img.decode().then(
    () => img,
    () => img, // a decode error must not hold a preloader forever
  );
};

