  const d = [];
  if (Math.abs(a.scrollY - b.scrollY) > TOL) d.push(`scrollY ${a.scrollY} vs ${b.scrollY}`);
  if (Math.abs(a.docH - b.docH) > TOL) d.push(`document height ${a.docH} vs ${b.docH}`);
