    await f.page.goto(o.url, { waitUntil: "load", timeout: 90_000 });
    await sleep(SETTLE.at(-1));
    await hide(f.page);
    const b = await state(f.page);
    const fresh = join(tmp, `${sc.name}-fresh.png`);
