  await browser.close();
  rmSync(tmp, { recursive: true, force: true });
}
console.log(`  strips → ${rel(outDir)}  (resized at each settle moment … | fresh load, right) — look at every one`);
finish({ outDir, rel, pass: failed === 0, result: { tool: "resize-check", url: o.url, sels: SELS, tol: TOL, scenarios }, summary: failed ? `${failed} of ${scenarios.length} resize paths land somewhere a fresh load doesn't` : `all ${scenarios.length} resize paths match a fresh load` });

#!/usr/bin/env node
// The scroll test — the bar Lighthouse can't see. A visible real Chrome
// scrolls the whole page like a person (PC: wheel bursts; phone: touch flings
// at 4× CPU on 4G), cold (fresh profile) then warm (second visit), ≥ 3 runs per
// device, and judges every frame.
//
//   node tools/qa/scroll-test.mjs --url http://localhost:4500/
//   node tools/qa/scroll-test.mjs --url … --devices mobile --runs 1     # chase one freeze
//   node tools/qa/scroll-test.mjs --url … --first-scroll                # + scroll from the unlock frame
//   node tools/qa/scroll-test.mjs --url … --video                       # + one unmeasured recording per device (needs ffmpeg)
//   node tools/qa/scroll-test.mjs --url … --headless                    # no window — less faithful GPU behaviour
//   node tools/qa/scroll-test.mjs --url … --touch-drag                  # ONLY the touch-drag check (below), ~20 s
//
// The page's scroller is found, not assumed (lib/scroller.mjs): a page that
// locks <html>/<body> and scrolls a full-screen div or a Lenis wrapper is
// scrolled through that element. A long page that scrolled 0 px is an ERROR,
// never "static" — before this, such a page read "one screen, 0 px" and passed.
//
// --touch-drag: a real finger drag (CDP touch events) on the phone profile,
// starting ON each fixed full-screen panel (else the centre), then a wheel at
// the same spot. FAIL when the finger moves the page 0 px. Chrome chains a
// touch scroll along the containing block, not the DOM: a fixed panel inside a
// fixed inner scroller with the document locked swallows every drag while the
// wheel still works. Fix: `pointer-events: none` on those panels on coarse
// pointers, `auto` again on their controls / links / canvases.
//
// Verdict per device (the worse of cold and warm, medians across runs):
//   ideal   no frame > 50 ms · ≤ 1 % dropped · p99 ≤ 33 ms     ← the bar
//   smooth  no frame > 100 ms · ≤ 3 % dropped
//   janky   anything else
//   incomplete  the pass did not reach the bottom (pinned / locked / not ready) — not a result
// Exit 0 only when every device is ideal (--accept smooth to relax).
//
// Each freeze is printed with how many runs reproduced it (3/3 = a bug, 1/3 =
// re-run first), the section under the viewport's centre, and its cause:
// script / React render / React mounting a lazy chunk / render (style+layout)
// / decode (media fetched just before) / gpu-raster (main thread idle).
// Budgets are 60 Hz even on a 120 Hz screen.
import { execFileSync } from "node:child_process";
import { cli, checkTarget, headersFrom, finish, warnIfBusy } from "./lib/run.mjs";
import { scrollTest, touchDrag, DEVICES } from "./lib/scroll.mjs";

const USAGE = `usage: node tools/qa/scroll-test.mjs --url <url> [--devices desktop,mobile] [--runs 3] [--first-scroll] [--touch-drag] [--video] [--headless] [--accept ideal|smooth] [--header "k: v"]`;
const { o, outDir, rel } = cli("scroll-test", USAGE, {
  devices: { type: "string", default: "desktop,mobile" }, runs: { type: "string", default: "3" },
  "first-scroll": { type: "boolean" }, "touch-drag": { type: "boolean" }, video: { type: "boolean" }, headless: { type: "boolean" },
  accept: { type: "string", default: "ideal" }, header: { type: "string", multiple: true },
  "ready-timeout": { type: "string", default: "30" }, "allow-dev": { type: "boolean" },
});
const devices = o.devices.split(",").map((s) => s.trim()).filter(Boolean);
for (const d of devices) if (!DEVICES[d]) { console.error(`✖ unknown device "${d}" — one of ${Object.keys(DEVICES).join(", ")}`); process.exit(2); }
const runs = Number(o.runs);
const headers = headersFrom(o.header);
if (o.video) { try { execFileSync("ffmpeg", ["-version"], { stdio: "ignore" }); } catch { console.error("✖ --video needs ffmpeg on PATH (puppeteer's screencast encodes with it)"); process.exit(2); } }

if (o["touch-drag"]) {
  console.log(`▸ touch-drag check · mobile${o.headless ? " · headless" : " · a Chrome window opens — leave it visible"}`);
  const target = await checkTarget(o.url, { headers });
  let r;
  try { r = await touchDrag({ url: o.url, headless: o.headless, headers, readyTimeout: Number(o["ready-timeout"]) * 1000 }); }
  catch (e) { console.error(`✖ ${e.message}`); finish({ outDir, rel, pass: false, result: { tool: "scroll-test", mode: "touch-drag", url: o.url, error: e.message }, summary: `touch-drag: ${e.message}` }); }
  if (r.static) console.log("    · nothing to scroll on this page (one screen) — nothing to drag");
  const bad = r.points.filter((p) => !p.ok);
  finish({
    outDir, rel, pass: r.pass, result: { tool: "scroll-test", mode: "touch-drag", url: o.url, at: new Date().toISOString(), local: target.local, ...r },
    summary: r.static ? "one-screen page — nothing to drag" : bad.length
      ? `a finger drag from ${bad.map((p) => p.on).join(", ")} moved the page 0 px (scroller: ${r.scroller})${bad.some((p) => p.wheelPx > 2) ? " while the wheel works — make the fixed layers transparent to touch on coarse pointers (pointer-events: none), re-enable on their controls" : ""}`
      : `every finger drag moved the page (scroller: ${r.scroller})`,
  });
}

console.log(`▸ scroll test · ${devices.join(" + ")} × ${runs}${o.headless ? " · headless" : " · a Chrome window opens — leave it visible"}`);
if (runs < 3) console.log(`  ! --runs ${runs}: for iterating; a verdict is the median of ≥ 3`);
const target = await checkTarget(o.url, { headers });
const load = warnIfBusy();

const { result, config } = await scrollTest({ url: o.url, devices, runs, outDir, headless: o.headless, video: o.video, firstScroll: o["first-scroll"], headers, readyTimeout: Number(o["ready-timeout"]) * 1000 });

const RANK = { ideal: 0, smooth: 1, janky: 2, incomplete: 3, error: 4 };
const okRank = RANK[o.accept] ?? 0;
let pass = true;
console.log("");
for (const [d, r] of Object.entries(result)) {
  if (r.error) { pass = false; console.log(`  ✖ ${d.padEnd(8)} ERROR — ${r.error}`); continue; }
  if (RANK[r.verdict] > okRank) pass = false;
  const p = (k) => `${k} ${r[k].verdict} (max ${r[k].max}ms, p99 ${r[k].p99}, >50ms ${r[k].over50}, dropped ${r[k].droppedPct}%, fetched ${r[k].fetchedCount})`;
  console.log(`  ${RANK[r.verdict] > okRank ? "✖" : "✔"} ${d.padEnd(8)} ${r.verdict.toUpperCase()}${r.static ? " (one-screen page: pointer sweeps, not scrolling)" : ""}  │ ${p("cold")}  │ ${p("warm")}`);
  if (r.readyMs > 3000) console.log(`      scroll was locked ${Math.round(r.readyMs / 100) / 10}s after load (loader / intro lock)`);
  for (const f of [...r.cold.freezeSections.map((x) => ({ ...x, pass: "cold" })), ...r.warm.freezeSections.map((x) => ({ ...x, pass: "warm" }))].sort((a, b) => b.worstMs - a.worstMs).slice(0, 6))
    console.log(`      ${String(f.worstMs).padStart(4)}ms  ${f.reproduced}  ${f.pass}  ${f.cause.padEnd(34)} ${f.section}`);
  if (r.cold.droppedPct > 1) for (const g of (r.cold.dropsBySection || []).slice(0, 3))
    console.log(`      drops ${String(g.droppedPct).padStart(5)}%  (${g.dropped} frames over ${g.seconds}s, cold)  ${g.section}`);
  if (r.cold.fetched?.length) console.log(`      fetched during the cold pass: ${r.cold.fetched.length} (each one is a freeze waiting for a slower link)`);
  if (r.firstScroll) {
    const fs = r.firstScroll;
    console.log(`      first scroll (from the unlock frame): max ${fs.max}ms, >50ms ${fs.over50}${fs.over50 ? "  ← what a person feels the instant the loader lets go" : ""}`);
    for (const f of fs.freezes.slice(0, 3)) console.log(`        ${String(f.ms).padStart(4)}ms  ${f.cause.padEnd(34)} ${f.section}`);
  }
}
if (target.local) console.log("  · localhost serves instantly: network emulation is on, but treat any mid-scroll fetch as a freeze a real 4G phone will feel");
console.log("  · not covered here: a phone's GPU (fill rate), iOS Safari (→ webkit-probe, ios-toolbar-probe), how fast a scene animates (→ fps-probe)");

const verdicts = Object.entries(result).map(([d, r]) => `${d} ${r.verdict}`).join(", ");
finish({ outDir, rel, pass, result: { tool: "scroll-test", url: o.url, at: new Date().toISOString(), runs, load: load.load, accept: o.accept, result, config }, summary: `${verdicts}${pass ? "" : ` — the bar is ${o.accept} on every device`}` });

#!/usr/bin/env node
// SEO crawl — what Lighthouse's SEO score lets through. Lighthouse checks one
// page for the *presence* of a title, a description, a canonical: 11 of 12 live
// sites built from this starter scored SEO 100 while serving localhost as the
// canonical, three titled "New Project". This tool reads the whole site the way
// a crawler does — the served HTML, no JavaScript — and checks the *values*,
// and the site as a graph:
//
//  - robots.txt, sitemap.xml and /llms.txt exist, agree, and name the real origin
//  - every sitemap page answers 200, is indexable, and is linked from another page
//  - per page: one title (≤ 60 chars, unique), a description (70–160, unique),
//    a self-referencing canonical, exactly one h1, JSON-LD that parses,
//    images with alt, no internal link that 404s, ≤ 3 clicks from home
//  - hreflang (multi-language sites only): valid codes, absolute URLs,
//    reciprocal between versions, self-referencing, an x-default, <html lang>
//    agreeing, canonicals that stay in their own language
//  - the robot form (Googlebot UA) carries the same title, description,
//    canonical, h1, JSON-LD and hreflang as the people form — different copy is cloaking
//
//   node tools/qa/seo-crawl.mjs --url http://localhost:4500/
//   node tools/qa/seo-crawl.mjs --url https://example.com/ --max 500
//
// Exit 1 on any FAIL. WARNs are worth reading, not blocking. Pair it with
// `qa:motion` (is the h1 hidden from non-JS crawlers?) and `qa:lh --as-bot`.
import { existsSync, readFileSync } from "node:fs";

import { cli, checkTarget, finish, isLocal } from "./lib/run.mjs";
import { UA } from "./lib/chrome.mjs";

const USAGE = `usage: node tools/qa/seo-crawl.mjs --url <url> [--max 200]`;
const { o, outDir, rel } = cli("seo-crawl", USAGE, { max: { type: "string", default: "200" }, "allow-dev": { type: "boolean" } });
await checkTarget(o.url);

const base = new URL(o.url);
const local = isLocal(o.url);
const MAX = Number(o.max);
const findings = [];
const add = (level, where, issue, fix) => findings.push({ level, where, issue, fix });

// ── HTML reading ─────────────────────────────────────────────────────────────
const ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };
const decode = (s) => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&([a-z]+);/gi, (m, n) => ENTITIES[n.toLowerCase()] ?? m);
const attrs = (tag) => {
  const out = {};
  for (const m of tag.matchAll(/([\w:.-]+)\s*=\s*("([^"]*)"|'([^']*)')/g)) out[m[1].toLowerCase()] = decode(m[3] ?? m[4] ?? "");
  return out;
};
const text = (html) => decode(html.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
const norm = (path) => (path.length > 1 ? path.replace(/\/+$/, "") : path) || "/";

// hreflang values — the same rules as src/utils/seo/hreflang.ts (keep in step).
const COUNTRY_AS_LANGUAGE = { jp: "ja", gr: "el", cz: "cs", dk: "da", ua: "uk", cn: "zh", kr: "ko", vn: "vi", il: "he" };
const NOT_REGIONS = { UK: "GB", EU: "a country", UN: "a country" };
function hreflangProblem(code) {
  if (code === "x-default") return null;
  if (code.includes("_")) return `"${code}": a hyphen, not an underscore`;
  const m = /^([a-z]{2,3})(?:-([A-Z][a-z]{3}))?(?:-([A-Z]{2}|\d{3}))?$/i.exec(code);
  if (!m) return `"${code}" is not language[-Script][-REGION]`;
  const [, language, , region] = m;
  if (COUNTRY_AS_LANGUAGE[language.toLowerCase()]) return `"${language}" is a country code — the language is "${COUNTRY_AS_LANGUAGE[language.toLowerCase()]}"`;
  if (region && /^\d+$/.test(region)) return `"${region}": Google reads ISO 3166-1 alpha-2 regions only`;
  if (region && NOT_REGIONS[region.toUpperCase()]) return `"${region}" is not an ISO 3166-1 region — use ${NOT_REGIONS[region.toUpperCase()]}`;
  return null;
}
const primary = (code) => code.toLowerCase().split("-")[0];

function read(html) {
  const head = html.split(/<\/head>/i)[0];
  const titles = [...head.matchAll(/<title[^>]*>([\s\S]*?)<\/title>/gi)].map((m) => decode(m[1]).trim());
  const metas = [...head.matchAll(/<meta\b[^>]*>/gi)].map((m) => attrs(m[0]));
  const links = [...head.matchAll(/<link\b[^>]*>/gi)].map((m) => attrs(m[0]));
  const meta = (key, value) => metas.filter((a) => (a[key] || "").toLowerCase() === value).map((a) => a.content ?? "");
  const body = html.replace(/<script\b[\s\S]*?<\/script>/gi, "").replace(/<style\b[\s\S]*?<\/style>/gi, "");
  const h1s = [...body.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map((m) => text(m[1]));
  const ld = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)].map((m) => {
    try {
      const data = JSON.parse(m[1]);
      const nodes = [].concat(data["@graph"] ?? data);
      return { ok: true, types: nodes.map((n) => [].concat(n["@type"] ?? "?").join("/")) };
    } catch (e) { return { ok: false, error: e.message }; }
  });
  const hrefs = [...body.matchAll(/<a\b[^>]*>/gi)].map((m) => attrs(m[0]).href).filter(Boolean);
  const imgs = [...body.matchAll(/<img\b[^>]*>/gi)].map((m) => attrs(m[0]));
  return {
    titles,
    description: meta("name", "description"),
    robots: meta("name", "robots").join(",").toLowerCase(),
    canonical: links.filter((l) => (l.rel || "").toLowerCase() === "canonical").map((l) => l.href),
    hreflang: links.filter((l) => (l.rel || "").toLowerCase() === "alternate" && l.hreflang).map((l) => ({ code: l.hreflang, href: l.href ?? "" })),
    lang: attrs(/<html\b[^>]*>/i.exec(html)?.[0] ?? "").lang,
    ogImage: meta("property", "og:image")[0],
    h1s,
    ld,
    hrefs,
    imgsNoAlt: imgs.filter((a) => !("alt" in a)).length,
  };
}

/** A same-site path for an href, or null for external / non-page links. */
function internalPath(href, from, origins) {
  if (/^(mailto:|tel:|javascript:|#)/i.test(href)) return null;
  let u;
  try { u = new URL(href, from); } catch { return null; }
  if (!origins.has(u.origin)) return null;
  if (/\.(png|jpe?g|webp|avif|gif|svg|ico|pdf|xml|txt|json|webmanifest|mp4|webm|woff2?)$/i.test(u.pathname)) return null;
  if (u.pathname.startsWith("/_next/") || u.pathname.startsWith("/api/")) return null;
  return norm(u.pathname);
}

async function get(path, ua = UA.desktop) {
  const url = new URL(path, base).href;
  try {
    const res = await fetch(url, { headers: { "user-agent": ua }, redirect: "manual" });
    const type = res.headers.get("content-type") || "";
    return { status: res.status, location: res.headers.get("location"), type, body: res.status < 300 ? await res.text() : "" };
  } catch (e) {
    return { status: 0, error: e.message, type: "", body: "" };
  }
}

// ── robots.txt, sitemap.xml, llms.txt ────────────────────────────────────────
console.log("  site files");
const robots = await get("/robots.txt");
const sitemap = await get("/sitemap.xml");
const llms = await get("/llms.txt");
let siteOrigin = null;
const sitemapPaths = new Set();

if (robots.status !== 200) add("FAIL", "/robots.txt", `answers ${robots.status}`, "src/app/robots.ts");
else {
  const star = robots.body.split(/\n\s*\n/).find((g) => /user-agent:\s*\*/i.test(g)) || "";
  if (/^disallow:\s*\/\s*$/im.test(star)) add("FAIL", "/robots.txt", "User-agent: * is disallowed from the whole site", "only a staging build may block / — check robots.ts per environment");
  if (!/^sitemap:/im.test(robots.body)) add("WARN", "/robots.txt", "no Sitemap: line", "robots.ts → sitemap");
  const blocked = [...robots.body.split(/\n\s*\n/)].filter((g) => /^disallow:\s*\/\s*$/im.test(g) && !/user-agent:\s*\*/i.test(g)).flatMap((g) => [...g.matchAll(/user-agent:\s*(\S+)/gi)].map((m) => m[1]));
  if (blocked.length) console.log(`    · AI crawlers blocked by policy: ${blocked.join(", ")} (siteConfig.aiCrawlers — the client's decision)`);
}
if (sitemap.status !== 200) add("FAIL", "/sitemap.xml", `answers ${sitemap.status}`, "src/app/sitemap.ts");
else {
  for (const m of sitemap.body.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)) {
    const u = new URL(decode(m[1]));
    siteOrigin ??= u.origin;
    sitemapPaths.add(norm(u.pathname));
  }
  if (!sitemapPaths.size) add("FAIL", "/sitemap.xml", "lists no URLs", "ROUTES in src/lib/routes.ts");
  const lastmods = [...sitemap.body.matchAll(/<lastmod>([^<]+)<\/lastmod>/g)].map((m) => m[1]);
  if (lastmods.length > 1 && new Set(lastmods).size === 1 && Date.now() - Date.parse(lastmods[0]) < 864e5) add("WARN", "/sitemap.xml", "every <lastmod> is today — the build time, not content dates", "ROUTES[].updated, or omit");
}
if (siteOrigin && /localhost|127\.0\.0\.1/.test(siteOrigin) && !local) add("FAIL", "/sitemap.xml", `URLs on ${siteOrigin} on a live host`, "set NEXT_PUBLIC_SITE_URL (obsidian/frontend/seo-metadata.md → Origin)");
if (llms.status !== 200) add("WARN", "/llms.txt", `answers ${llms.status}`, "src/app/llms.txt/route.ts");
console.log(`    robots ${robots.status} · sitemap ${sitemap.status} (${sitemapPaths.size} URLs on ${siteOrigin ?? "?"}) · llms.txt ${llms.status}`);

// The site's canonical origin (sitemap) and the origin being tested are both "this site".
const origins = new Set([base.origin, siteOrigin].filter(Boolean));

// ── Crawl ────────────────────────────────────────────────────────────────────
console.log("  crawl (served HTML, no JavaScript)");
const pages = new Map();
const inbound = new Map();
// Links first (breadth-first from home, so depth is real), then any sitemap
// page no link reached — those are the orphans.
const queue = [{ path: "/", depth: 0 }];
const seeds = [...sitemapPaths].map((path) => ({ path, depth: null }));
const seen = new Set();
while ((queue.length || seeds.length) && pages.size < MAX) {
  const { path, depth } = queue.length ? queue.shift() : seeds.shift();
  if (seen.has(path)) continue;
  seen.add(path);
  const res = await get(path);
  const page = { path, depth, status: res.status, location: res.location, inSitemap: sitemapPaths.has(path) };
  pages.set(path, page);
  if (res.status >= 300 || !res.type.includes("text/html")) continue;
  Object.assign(page, read(res.body));
  for (const href of page.hrefs) {
    const target = internalPath(href, new URL(path, base).href, origins);
    if (!target || target === path) continue;
    if (!inbound.has(target)) inbound.set(target, new Set());
    inbound.get(target).add(path);
    if (!seen.has(target)) queue.push({ path: target, depth: depth == null ? null : depth + 1 });
  }
  // Language versions are crawled too — after the links, like sitemap seeds.
  for (const { href } of page.hreflang) {
    const target = internalPath(href, new URL(path, base).href, origins);
    if (target && !seen.has(target)) seeds.push({ path: target, depth: null });
  }
}
// Depth for sitemap-seeded pages reached later through links.
for (const [target, froms] of inbound) {
  const p = pages.get(target);
  if (!p || p.depth != null) continue;
  const ds = [...froms].map((f) => pages.get(f)?.depth).filter((d) => d != null);
  if (ds.length) p.depth = Math.min(...ds) + 1;
}
const partial = [...queue, ...seeds].some((q) => !seen.has(q.path));
if (partial) add("WARN", "crawl", `stopped at --max ${MAX} pages — orphan and depth checks skipped`, "raise --max for a whole-site verdict");

// ── Per page ─────────────────────────────────────────────────────────────────
const titles = new Map();
const descriptions = new Map();
for (const p of pages.values()) {
  const where = p.path;
  if (p.status === 0) { add("FAIL", where, "no answer", "is the route built?"); continue; }
  if (p.status >= 400) {
    const from = [...(inbound.get(where) || [])].slice(0, 3).join(", ");
    add("FAIL", where, `answers ${p.status}${from ? ` — linked from ${from}` : ""}${p.inSitemap ? " — and listed in the sitemap" : ""}`, "build the page, or point the link at an existing one (<Link> prefetches it: a console 404 on every page)");
    continue;
  }
  if (p.status >= 300) {
    if (p.inSitemap) add("WARN", where, `in the sitemap but redirects (${p.status} → ${p.location})`, "list the final URL");
    continue;
  }
  if (!p.titles) continue; // not HTML
  const noindex = p.robots.includes("noindex");
  if (noindex && p.inSitemap) add("FAIL", where, "noindex but listed in the sitemap", "set indexable: false in ROUTES, or drop the noindex");
  if (!noindex && !p.inSitemap) add("WARN", where, "indexable page missing from the sitemap", "add it to ROUTES in src/lib/routes.ts");

  const title = p.titles[0];
  if (!title) add("FAIL", where, "no <title>", "generateMetadata({ title })");
  else {
    if (p.titles.length > 1) add("WARN", where, `${p.titles.length} <title> tags`, "one per page");
    if (/TODO|New Project/i.test(title)) add(noindex ? "WARN" : "FAIL", where, `placeholder title "${title}"`, "fill src/lib/site.ts / the page's metadata");
    if (title.length > 60) add("WARN", where, `title ${title.length} chars (search shows ~60): "${title}"`, "lead with the query, brand last");
    if (title.length < 15) add("WARN", where, `title only ${title.length} chars: "${title}"`, "say what the page is");
    if (!noindex) titles.set(title, [...(titles.get(title) || []), where]);
  }
  const desc = p.description[0];
  if (!desc) add("WARN", where, "no meta description", "generateMetadata({ description })");
  else {
    if (desc.length > 160 || desc.length < 70) add("WARN", where, `description ${desc.length} chars (aim 70–160)`, "one sentence on what the reader gets");
    if (!noindex) descriptions.set(desc, [...(descriptions.get(desc) || []), where]);
  }
  const canonical = p.canonical[0];
  if (!canonical) add(noindex ? "WARN" : "FAIL", where, "no canonical", "generateMetadata({ url })");
  else {
    const cu = new URL(canonical, new URL(where, base));
    if (/localhost|127\.0\.0\.1/.test(cu.host) && !local) add("FAIL", where, `canonical on ${cu.origin} on a live host`, "set NEXT_PUBLIC_SITE_URL");
    else if (norm(cu.pathname) !== where) add("WARN", where, `canonical points elsewhere: ${cu.pathname}`, "intended (a duplicate)? otherwise generateMetadata({ url: its own path })");
  }
  if (p.ogImage && /localhost|127\.0\.0\.1/.test(p.ogImage) && !local) add("FAIL", where, `og:image on localhost: ${p.ogImage}`, "set NEXT_PUBLIC_SITE_URL");
  if (p.h1s.length === 0) add("FAIL", where, "no <h1> in the served HTML", "one h1 per page, server-rendered (a robot-text twin if it animates)");
  if (p.h1s.length > 1) add("WARN", where, `${p.h1s.length} <h1>s: ${p.h1s.map((h) => `"${h.slice(0, 40)}"`).join(", ")}`, "exactly one");
  for (const block of p.ld) if (!block.ok) add("FAIL", where, `JSON-LD does not parse: ${block.error}`, "build it with src/utils/seo/structured-data.ts");
  if (!p.ld.length && !noindex) add("WARN", where, "no JSON-LD", "the root layout's site graph is missing?");
  if (p.imgsNoAlt) add("WARN", where, `${p.imgsNoAlt} <img> without alt`, 'meaningful alt, or alt="" when decorative');
  if (!partial && !noindex && where !== "/" && !(inbound.get(where)?.size)) add("WARN", where, "no page links to it (orphan)", "link it from at least 3 related pages, with descriptive anchor text");
  if (!partial && p.depth != null && p.depth > 3) add("WARN", where, `${p.depth} clicks from home`, "keep important pages within 3");
}
for (const [t, ws] of titles) if (ws.length > 1) add("FAIL", ws.join(", "), `share one title: "${t}"`, "a unique title per page");
for (const [, ws] of descriptions) if (ws.length > 1) add("WARN", ws.join(", "), "share one description", "a unique description per page");

// ── hreflang (only pages that declare any) ───────────────────────────────────
const localHost = (u) => /localhost|127\.0\.0\.1/.test(u);
for (const p of pages.values()) {
  if (!p.hreflang?.length) continue;
  const where = p.path;
  const own = [];
  const targets = [];
  for (const { code, href } of p.hreflang) {
    const problem = hreflangProblem(code);
    if (problem) add("FAIL", where, `invalid hreflang ${problem}`, "language[-REGION], ISO 639-1 + ISO 3166-1 (src/utils/seo/hreflang.ts)");
    if (!/^https?:\/\//i.test(href)) { add("FAIL", where, `hreflang="${code}" href is not absolute: "${href}"`, "absolute URLs only — metadataBase / routeLanguages()"); continue; }
    if (localHost(href) && !local) add("FAIL", where, `hreflang="${code}" on localhost: ${href}`, "set NEXT_PUBLIC_SITE_URL");
    const target = internalPath(href, new URL(where, base).href, origins);
    if (target === where) { if (code !== "x-default") own.push(code); }
    else if (target && code !== "x-default") targets.push({ code, target });
  }
  if (!own.length) add("WARN", where, "hreflang set lists every version but this one (no self-reference)", "each version lists itself too — ROUTES[].alternates includes its own path");
  if (!p.hreflang.some((h) => h.code === "x-default")) add("WARN", where, "hreflang without x-default", "x-default → the version for everyone else (routeLanguages() adds it)");
  if (p.lang && own.length && !own.some((c) => primary(c) === primary(p.lang))) add("WARN", where, `<html lang="${p.lang}"> but this page's hreflang is ${own.join("/")}`, "the root layout under [lang] sets lang from the URL");
  const cu = p.canonical?.[0] && norm(new URL(p.canonical[0], new URL(where, base)).pathname);
  if (cu && cu !== where && targets.some((t) => t.target === cu)) add("WARN", where, `canonical points to another language version (${cu})`, "each language version is canonical to itself — a cross-language canonical drops this one from the index");
  for (const { code, target } of targets) {
    const other = pages.get(target);
    if (!other) continue; // past --max
    if (other.status !== 200) { add("FAIL", where, `hreflang="${code}" → ${target}, which answers ${other.status}`, "every listed version must answer 200 and be indexable"); continue; }
    if (!(other.hreflang ?? []).some(({ href }) => internalPath(href, new URL(target, base).href, origins) === where)) add("FAIL", where, `hreflang="${code}" → ${target}, which does not link back (non-reciprocal)`, "give every version the same set — ROUTES[].alternates on each entry");
  }
}

// llms.txt lists every registry page in the sitemap, and nothing the sitemap
// doesn't. CMS collection pages (posts, entries) may be a curated subset —
// llms.txt is a map, not a dump — so only `src/lib/routes.ts` paths must be in it.
if (llms.status === 200 && sitemapPaths.size) {
  const listed = new Set([...llms.body.matchAll(/\]\((https?:\/\/[^)\s]+)\)/g)].map((m) => { try { return norm(new URL(m[1]).pathname); } catch { return null; } }).filter(Boolean));
  const registryFile = new URL("../../src/lib/routes.ts", import.meta.url);
  const registry = existsSync(registryFile)
    ? new Set([...readFileSync(registryFile, "utf8").matchAll(/path:\s*"(\/[^"]*)"/g)].map((m) => norm(m[1])))
    : null;
  const missing = [...sitemapPaths].filter((p) => !listed.has(p) && (!registry || registry.has(p)));
  const extra = [...listed].filter((p) => !sitemapPaths.has(p));
  if (missing.length) add("WARN", "/llms.txt", `misses sitemap pages: ${missing.join(", ")}`, "both read ROUTES — a hand-written llms.txt?");
  if (extra.length) add("WARN", "/llms.txt", `lists pages not in the sitemap: ${extra.join(", ")}`, "keep the two in step");
  if (/TODO/.test(llms.body)) add("WARN", "/llms.txt", "still holds TODO placeholders", "fill src/lib/site.ts");
}

// ── People vs robot form ─────────────────────────────────────────────────────
console.log("  robot form parity (Googlebot)");
const parity = [];
for (const p of [...pages.values()].filter((x) => x.titles && x.status === 200).slice(0, 30)) {
  const bot = await get(p.path, UA.googlebot);
  if (bot.status !== 200) { add("FAIL", p.path, `Googlebot gets ${bot.status}, people 200`, "src/proxy.ts / robot-view"); continue; }
  const r = read(bot.body);
  const diffs = [];
  if (r.titles[0] !== p.titles[0]) diffs.push(`title "${r.titles[0]}" vs "${p.titles[0]}"`);
  if (r.description[0] !== p.description[0]) diffs.push("description");
  if (r.canonical[0] !== p.canonical[0]) diffs.push(`canonical ${r.canonical[0]} vs ${p.canonical[0]}`);
  if (r.h1s.join("|") !== p.h1s.join("|")) diffs.push(`h1 "${r.h1s.join("|").slice(0, 50)}" vs "${p.h1s.join("|").slice(0, 50)}"`);
  if (r.ld.length !== p.ld.length) diffs.push(`JSON-LD blocks ${r.ld.length} vs ${p.ld.length}`);
  const langs = (x) => x.hreflang.map((h) => `${h.code}=${h.href}`).sort().join(" ");
  if (langs(r) !== langs(p)) diffs.push("hreflang set");
  if (/noindex/.test(r.robots) && !/noindex/.test(p.robots)) diffs.push("robot form is noindex");
  parity.push({ path: p.path, diffs });
  if (diffs.length) add("FAIL", p.path, `robot form differs: ${diffs.join("; ")}`, "same content and metadata for robots (obsidian/frontend/robot-form.md) — different copy is cloaking");
}

// ── Report ───────────────────────────────────────────────────────────────────
const rows = [...pages.values()].filter((p) => p.titles);
console.log(`\n  ${"page".padEnd(28)} ${"st".padEnd(4)} ${"depth".padEnd(6)} ${"in".padEnd(3)} ${"title".padEnd(6)} ${"desc".padEnd(5)} h1  ld`);
for (const p of rows) {
  console.log(`  ${p.path.slice(0, 27).padEnd(28)} ${String(p.status).padEnd(4)} ${String(p.depth ?? "–").padEnd(6)} ${String(inbound.get(p.path)?.size ?? 0).padEnd(3)} ${String(p.titles[0]?.length ?? 0).padEnd(6)} ${String(p.description[0]?.length ?? 0).padEnd(5)} ${String(p.h1s.length).padEnd(3)} ${p.ld.flatMap((b) => b.types ?? ["✖"]).join(",")}`);
}
const fails = findings.filter((f) => f.level === "FAIL");
const warns = findings.filter((f) => f.level === "WARN");
console.log("");
for (const f of [...fails, ...warns]) console.log(`  ${f.level === "FAIL" ? "✖" : "!"} ${f.where} — ${f.issue}\n      → ${f.fix}`);

finish({
  outDir, rel, pass: fails.length === 0,
  result: {
    tool: "seo-crawl", url: o.url, siteOrigin, sitemap: [...sitemapPaths],
    pages: rows.map((p) => ({ path: p.path, status: p.status, depth: p.depth, inbound: inbound.get(p.path)?.size ?? 0, title: p.titles[0], description: p.description[0], canonical: p.canonical[0], hreflang: p.hreflang, lang: p.lang, h1s: p.h1s, jsonLd: p.ld, robots: p.robots })),
    parity, findings,
  },
  summary: `${pages.size} URLs crawled · ${fails.length} FAIL · ${warns.length} WARN`,
});

#!/usr/bin/env node
// One-time setup for tools/qa: installs Lighthouse, puppeteer-core,
// chrome-launcher, axe-core, Playwright (+ its WebKit build) and pngjs into a
// cache dir OUTSIDE the project. The site's package.json gains nothing.
//
//   node tools/qa/setup.mjs            # install / update
//   node tools/qa/setup.mjs --check    # report what is there, install nothing
//
// Cache: ~/.cache/next16-qa (override with NEXT16_QA_CACHE). Re-run any time;
// it is idempotent. Needs Google Chrome installed (the tools drive the real
// browser — never a bundled Chromium: GPU behaviour is the point).
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { CACHE_DIR, PACKAGES } from "./lib/deps.mjs";
import { chromePath } from "./lib/chrome.mjs";

const check = process.argv.includes("--check");
const pkgFile = join(CACHE_DIR, "package.json");

function installed() {
  return Object.fromEntries(Object.keys(PACKAGES).map((name) => {
    try { return [name, JSON.parse(readFileSync(join(CACHE_DIR, "node_modules", name, "package.json"), "utf8")).version]; }
    catch { return [name, null]; }
  }));
}

const major = Number(process.versions.node.split(".")[0]);
if (major < 20) { console.error(`✖ Node ${process.version}: the QA tools need Node ≥ 20 (use the project's .nvmrc).`); process.exit(1); }

const before = installed();
if (check) {
  console.log(`QA cache: ${CACHE_DIR}`);
  for (const [n, v] of Object.entries(before)) console.log(`  ${v ? "✔" : "✖"} ${n}${v ? " " + v : " — missing"}`);
  console.log(`  ${chromePath() ? "✔" : "✖"} Google Chrome ${chromePath() || "— not found (set CHROME_PATH)"}`);
  process.exit(Object.values(before).every(Boolean) && chromePath() ? 0 : 1);
}

mkdirSync(CACHE_DIR, { recursive: true });
if (!existsSync(pkgFile)) writeFileSync(pkgFile, JSON.stringify({ name: "next16-qa-cache", private: true, description: "Dependencies of tools/qa — installed by tools/qa/setup.mjs. Not a project." }, null, 2) + "\n");

const specs = Object.entries(PACKAGES).map(([n, v]) => `${n}@${v}`);
console.log(`▸ installing into ${CACHE_DIR}\n  ${specs.join(" ")}`);
// npm, not yarn: the cache is not a workspace and must not inherit the project's resolver.
execFileSync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=error", "--prefix", CACHE_DIR, ...specs], { stdio: "inherit" });

// Playwright's WebKit build (for webkit-probe.mjs). Chrome is NOT downloaded:
// every Chrome tool drives the installed Google Chrome.
console.log("▸ installing Playwright WebKit");
execFileSync(process.execPath, [join(CACHE_DIR, "node_modules", "playwright", "cli.js"), "install", "webkit"], { stdio: "inherit" });

const after = installed();
console.log("\n✔ QA cache ready:");
for (const [n, v] of Object.entries(after)) console.log(`  ${n.padEnd(16)} ${v}${before[n] && before[n] !== v ? `  (was ${before[n]})` : ""}`);
const chrome = chromePath();
console.log(chrome ? `  Google Chrome    ${chrome}` : "  ! Google Chrome not found — install it or set CHROME_PATH");
console.log("\nNext: `next build && next start -p 4500`, then e.g. `node tools/qa/lighthouse.mjs --url http://localhost:4500/` — see tools/qa/README.md");

#!/usr/bin/env node
// WebKit probe: the iOS-only bugs. Playwright's WebKit (the engine inside
// every iOS browser) with an iPhone device profile, scrolled the way a thumb
// does — momentum flicks, partial scrolls, past-and-back, to the bottom and
// back, quick reversals, a URL-bar height change mid-fling, a status-bar tap
// to the top. At every stop it records, for EVERY canvas on the page, whether
// it is on screen, shown (opacity / visibility / display of it and every
// ancestor), its WebGL context state, whether it is still DRAWING, and how its
// region looks in a real screenshot compared with its first good frame.
//
// Why it exists: headless Chrome missed an iOS-only "the hero disappears after
// scrolling" bug twice. iOS drops a canvas's last frame after a toolbar resize
// and drops WebGL contexts under memory pressure — a scene that stops drawing
// while visible, or never rebuilds a lost context, is blank on an iPhone and
// fine everywhere else. Rule from production sites: never stop drawing a
// visible WebGL canvas on iOS; pause only when it is off screen.
//
//   node tools/qa/webkit-probe.mjs --url http://localhost:4500/
//   node tools/qa/webkit-probe.mjs --url … --iterations 4 --shots          # a shot at every step
//   node tools/qa/webkit-probe.mjs --url … --faults                        # + WebGL context losses at the worst moments
//   node tools/qa/webkit-probe.mjs --url … --gpu-kill                      # + kill WebKit's GPU process (macOS; iOS jetsam)
//   node tools/qa/webkit-probe.mjs --url … --device "iPhone 15 Pro Max" --headed
//
// The flicks are driven per frame in the page (an initial velocity decaying
// like UIScrollView's 0.998/ms) — Playwright cannot synthesise native touch
// scrolling in WebKit — so the engine itself fires the scroll events, as the
// compositor does on a phone. The probe forces preserveDrawingBuffer so the
// canvas can be read back.
// A step FAILS when a canvas on screen is: context-lost, hidden by CSS,
// drawing nothing while it drew at its first look, or blank in the screenshot
// (luminance stddev < 30 % of its first good frame, with ≥ 60 % of it on
// screen). Exit 1 on any failing step. fail-*.png in the report dir — look.
import { writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { cli, checkTarget, finish } from "./lib/run.mjs";
import { playwright } from "./lib/deps.mjs";
import { CANVAS_PROBE, ISOLATE_CSS } from "./lib/canvas-probe.mjs";
import { regionStats } from "./lib/image.mjs";
import { installScroller, scrollState } from "./lib/scroller.mjs";

const USAGE = `usage: node tools/qa/webkit-probe.mjs --url <url> [--device "iPhone 13"] [--iterations 2] [--wait 9000] [--shots] [--faults] [--gpu-kill] [--headed] [--no-isolate]`;
const { o, outDir, rel } = cli("webkit-probe", USAGE, {
  device: { type: "string", default: "iPhone 13" }, iterations: { type: "string", default: "2" }, wait: { type: "string", default: "9000" },
  shots: { type: "boolean" }, faults: { type: "boolean" }, "gpu-kill": { type: "boolean" }, headed: { type: "boolean" },
  "no-isolate": { type: "boolean" }, "no-scroll": { type: "boolean" }, "allow-dev": { type: "boolean" },
});
await checkTarget(o.url);
const { webkit, devices } = await playwright();
const profile = devices[o.device];
if (!profile) { console.error(`✖ unknown device "${o.device}" — e.g. "iPhone 13", "iPhone 15 Pro Max" (Playwright's device list)`); process.exit(2); }
const vp = profile.viewport;

// WebKit's GPU process(es) belonging to THIS run (other runs may be live).
const gpuPids = () => { try { return new Set(execFileSync("ps", ["-axo", "pid=,command="], { encoding: "utf8" }).split("\n").filter((l) => /WebKit\.GPU|WebKitGPU|GPUProcess/.test(l)).map((l) => Number(l.trim().split(/\s+/)[0]))); } catch { return new Set(); } };
const gpuBefore = gpuPids();

const browser = await webkit.launch({ headless: !o.headed });
const context = await browser.newContext({ ...profile });
const page = await context.newPage();
page.setDefaultTimeout(20_000);
const logs = [];
let crashed = false;
page.on("console", (m) => { if (/error|warn/.test(m.type())) logs.push(`${m.type()}: ${m.text()}`.slice(0, 200)); });
page.on("pageerror", (e) => logs.push("pageerror: " + e.message.slice(0, 200)));
page.on("crash", () => { crashed = true; console.log("  ✖ PAGE CRASHED (WebContent process gone)"); });

await page.addInitScript(CANVAS_PROBE, { preserve: true });
// Every flick, jump and read goes through the page's scroller (lib/scroller.mjs):
// a page that locks <html>/<body> and scrolls a full-screen div never moves under window.scrollBy.
await installScroller(page);
await page.addInitScript(() => {
  // A thumb flick, per frame: velocity v0 (px/ms, + = down) decaying like UIScrollView.
  window.__fling = (v0, { decel = 0.998, reverseAfterMs = 0, v1 = 0 } = {}) => new Promise((resolve) => {
    let v = v0, last = performance.now(); const start = last; let reversed = false;
    const step = (now) => {
      const dt = Math.min(34, now - last); last = now;
      if (reverseAfterMs && !reversed && now - start > reverseAfterMs) { v = v1; reversed = true; }
      window.__by(v * dt);
      v *= Math.pow(decel, dt);
      if (Math.abs(v) > 0.02) requestAnimationFrame(step); else resolve(window.__sy());
    };
    requestAnimationFrame(step);
  });
});

// A crashed WebContent process leaves evaluate hanging: fail loudly instead.
const guard = (p, what) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error(`${what} timed out${crashed ? " (page crashed)" : ""}`)), 25_000))]);
const read = () => guard(page.evaluate(async () => {
  const list = __qa.all();
  const els = [...document.querySelectorAll("canvas")].filter((c) => c.dataset.qaId);
  const d0 = Object.fromEntries(els.map((c) => [c.dataset.qaId, c.__qaDraws || 0]));
  await new Promise((r) => setTimeout(r, 300));
  for (const c of list) {
    const el = els.find((e) => e.dataset.qaId === c.id);
    c.draws300 = el ? (el.__qaDraws || 0) - (d0[c.id] || 0) : 0;
    c.readback = el ? __qa.readback(el) : null;
  }
  return { y: Math.round(window.__sy()), vh: innerHeight, canvases: list };
}), "state read");

const shot = async () => {
  if (!o["no-isolate"]) await page.addStyleTag({ content: ISOLATE_CSS("canvas") }).then((h) => h.evaluate((el) => { el.id = "__qa-iso"; }));
  const buf = await page.screenshot({ scale: "css" });
  if (!o["no-isolate"]) await page.evaluate(() => document.getElementById("__qa-iso")?.remove());
  return buf;
};

const base = {}; // per canvas id: { draws300, std } from its first good look
const result = { url: o.url, device: o.device, steps: [], failures: [] };
let n = 0;
const check = async (label, { offOk = true } = {}) => {
  n++;
  const s = await read();
  const buf = await shot();
  const reasons = [];
  for (const c of s.canvases) {
    if (!c.onScreen || c.box.h < 40) continue;
    const rect = { x: Math.max(0, c.box.x), y: Math.max(0, c.box.y), w: Math.min(vp.width, c.box.x + c.box.w) - Math.max(0, c.box.x), h: Math.min(s.vh, c.box.y + c.box.h) - Math.max(0, c.box.y) };
    c.screen = rect.w > 4 && rect.h > 4 ? regionStats(buf, rect, 1) : null;
    const b = base[c.id];
    const why = [];
    if (c.lost) why.push("context lost");
    if (c.opacity < 0.05) why.push(`opacity ${c.opacity}`);
    if (c.flags.length) why.push(c.flags.join(", "));
    if (b && b.draws300 > 0 && c.draws300 === 0 && c.type !== "offscreen") why.push("stopped drawing while visible");
    if (b && c.screen && c.visibleFrac >= 0.6 && b.std > 3 && c.screen.std < b.std * 0.3) why.push(`blank on screen (stddev ${c.screen.std} vs ${b.std})`);
    if (why.length) reasons.push(`canvas #${c.id} ${c.box.w}x${c.box.h}@${c.box.y}: ${why.join("; ")}`);
    else if (!b && c.visibleFrac >= 0.6 && c.screen) base[c.id] = { draws300: c.draws300, std: c.screen.std };
  }
  if (!offOk && !s.canvases.length) reasons.push("no canvas on the page");
  const ok = reasons.length === 0;
  const step = { label, y: s.y, ok, reasons, canvases: s.canvases.map((c) => ({ id: c.id, onScreen: c.onScreen, visibleFrac: c.visibleFrac, box: c.box, type: c.type, lost: c.lost, opacity: c.opacity, draws300: c.draws300, std: c.screen?.std ?? null })) };
  result.steps.push(step);
  if (!ok) { result.failures.push(step); writeFileSync(join(outDir, `fail-${result.failures.length}-${label.replace(/[^\w-]+/g, "_")}.png`), buf); }
  else if (o.shots) writeFileSync(join(outDir, `${String(n).padStart(3, "0")}-${label.replace(/[^\w-]+/g, "_")}.png`), buf);
  const on = s.canvases.filter((c) => c.onScreen);
  console.log(`  ${ok ? "ok  " : "FAIL"} ${label.padEnd(30)} y=${String(s.y).padStart(5)} on screen: ${on.map((c) => `#${c.id} ${c.draws300}dr${c.screen ? " sd" + c.screen.std : ""}`).join(" ") || "—"}${reasons.length ? "  ← " + reasons.join(" | ") : ""}`);
  return step;
};

const fling = (v, extra) => guard(page.evaluate(([v, e]) => window.__fling(v, e), [v, extra ?? {}]), "fling");
const top = () => page.evaluate(() => window.__top());
const wait = (ms) => page.waitForTimeout(ms);
const killGpu = () => { const mine = [...gpuPids()].filter((p) => !gpuBefore.has(p)); mine.forEach((p) => { try { process.kill(p, "SIGKILL"); } catch {} }); return mine; };

try {
  await page.goto(o.url, { waitUntil: "load", timeout: 90_000 });
  await wait(Number(o.wait));
  // Dismiss a consent banner the way a reader would (it can cover the scene).
  const reject = page.getByRole("button", { name: /reject|decline|only necessary|accept/i });
  if (await reject.count()) await reject.first().click({ timeout: 2000 }).catch(() => undefined);
  await wait(600);
  const first = await check("baseline");
  const s0 = await scrollState(page);
  if (s0.scroller !== "document") console.log(`  · the page scrolls an inner element (${s0.scroller}, ${s0.max} px) — flicks drive it`);
  if (!first.canvases.length) console.log("  ! no canvas on the page — this probe has nothing to judge (pass for a page without a scene)");

  let deepest = 0;
  const seen = (step) => { deepest = Math.max(deepest, step.y); return step; };
  for (let it = 0; it < (o["no-scroll"] ? 0 : Number(o.iterations)); it++) {
    const t = `#${it}`;
    await fling(0.6); await check(`${t} partial-down`);
    await fling(-0.6); await check(`${t} partial-up`);
    await fling(2.5); await check(`${t} flick-past-first-screen`);
    await fling(-2.5); await wait(100); await check(`${t} flick-back`);
    await fling(9); await fling(9); seen(await check(`${t} bottom`));
    await wait(800);
    await fling(-9); await fling(-9); await fling(-9); await top(); await check(`${t} back-from-bottom`);
    await fling(2.2, { reverseAfterMs: 120, v1: -2.4 }); await check(`${t} reversal-1`);
    await fling(1.4, { reverseAfterMs: 60, v1: -1.6 }); await check(`${t} reversal-2`);
    // The URL bar: the viewport height changes mid-fling (collapse, then expand).
    const p1 = fling(1.2); await wait(80); await page.setViewportSize({ width: vp.width, height: vp.height + 86 }); await p1; await check(`${t} toolbar-collapsed`);
    const p2 = fling(-1.2); await wait(80); await page.setViewportSize({ width: vp.width, height: vp.height }); await p2; await top(); await wait(150); await check(`${t} toolbar-expanded`);
    // An anchor jump away, then the status-bar tap that smooth-scrolls to the top.
    await page.evaluate(() => window.__to(window.__max())); await wait(500); await check(`${t} jump-bottom`);
    // On an inner scroller the smooth return is driven per frame: WebKit dropped an element's
    // scrollTo({ behavior: "smooth" }) here (and iOS's status-bar tap only scrolls the document).
    await page.evaluate(() => {
      const s = window.__scroller();
      if (window.__isDoc(s)) return window.scrollTo({ top: 0, behavior: "smooth" });
      const y0 = s.scrollTop, t0 = performance.now();
      const f = (now) => { const k = Math.min(1, (now - t0) / 600); s.scrollTop = y0 * Math.pow(1 - k, 3); if (k < 1) requestAnimationFrame(f); };
      requestAnimationFrame(f);
    }); await wait(1200); await check(`${t} status-bar-top`);
    // Sit at the bottom (images decode, the scene is far off screen), then come back slowly.
    await fling(12); await fling(12); await wait(2500);
    for (let k = 0; k < 6; k++) await fling(-3.2);
    await top(); await wait(200); await check(`${t} slow-return`);
  }

  // A long page the flicks never moved: every step judged the first screen — an error, not a pass.
  if (!o["no-scroll"] && Number(o.iterations) > 0 && ((s0.max > 16 && deepest <= 2) || s0.unclaimed)) {
    const why = s0.unclaimed ? `the page reads as one screen, but ${s0.unclaimed} scrolls — the flicks could not move it; nothing below the first screen was checked`
      : `the page is ${s0.max} px longer than its screen but every flick scrolled it 0 px (scroller: ${s0.scroller}) — nothing below the first screen was checked`;
    result.failures.push({ label: "scrolled 0 px", reasons: [why] });
    console.log(`  ✖ ${why}`);
  }

  if (o["gpu-kill"]) {
    if (process.platform !== "darwin") console.log("  ! --gpu-kill is macOS-only — skipped");
    else {
      // At most two kills per run: WebKit's crash-loop guard ends the WebContent
      // process on the third (Safari's "a problem repeatedly occurred").
      await fling(12); await fling(12); await wait(400);
      console.log(`  · killed WebKit GPU process ${killGpu().join(" ") || "(none found)"} with the scene off screen`);
      await wait(1500); for (let k = 0; k < 4; k++) await fling(-4); await top(); await wait(2500);
      await check("gpu killed off screen → back +2.5s");
      console.log(`  · killed WebKit GPU process ${killGpu().join(" ") || "(none found)"} with the scene on screen`);
      await wait(2500); await check("gpu killed on screen +2.5s");
    }
  }

  if (o.faults) {
    const lose = () => page.evaluate(() => { const c = [...document.querySelectorAll("canvas")].find((x) => x.__qaCtx?.getExtension && !x.__qaCtx.isContextLost() && x.getBoundingClientRect().bottom > 0 && x.getBoundingClientRect().top < innerHeight) || [...document.querySelectorAll("canvas")].find((x) => x.__qaCtx?.getExtension && !x.__qaCtx.isContextLost()); const e = c?.__qaCtx.getExtension("WEBGL_lose_context"); if (!e) return "no WebGL canvas"; e.loseContext(); return `lost #${c.dataset.qaId}`; });
    const loseNext = (count, delay) => page.evaluate(([count, delay]) => { __qa.loseNext = { count, delay }; }, [count, delay]);
    for (const delay of [0, 20, 60]) {
      // The REBUILD's own fresh context lost within its first milliseconds — the hole a simple handler leaves.
      await loseNext(1, delay); console.log(`  · ${await lose()} on screen (its rebuild lost @${delay}ms)`);
      await wait(4000); await check(`fault: on screen, rebuild lost @${delay}ms`);
      await fling(12); await fling(12); await wait(500);
      await loseNext(1, delay); console.log(`  · ${await lose()} off screen (its rebuild lost @${delay}ms)`);
      await wait(800); for (let k = 0; k < 4; k++) await fling(-4); await top(); await wait(4000);
      await check(`fault: off screen, rebuild lost @${delay}ms`);
    }
    await loseNext(2, 10); console.log(`  · ${await lose()} — a storm: two rebuilds in a row lost`);
    await wait(6000); await check("fault: storm");
    await fling(2.5); await fling(-2.5); await top(); await wait(300); await check("after the faults, a plain cycle");
  }
} catch (e) {
  result.error = e.message;
  result.failures.push({ label: "probe error", reasons: [e.message] });
  console.log(`  ✖ ${e.message}`);
} finally {
  await browser.close().catch(() => undefined);
}

result.console = logs.slice(-40);
const total = result.steps.length, failed = result.failures.length;
finish({
  outDir, rel, pass: failed === 0, result: { tool: "webkit-probe", ...result },
  summary: failed ? `${failed} of ${total} steps show a canvas blank, hidden, lost or stopped while on screen in WebKit — see fail-*.png` : `${total} steps: every on-screen canvas stayed shown and drawing in WebKit (${o.device})`,
});
